empo":{"min":35,"max":45,"texto":"35 – 45 minutos"},"pasos":["Coloca el objeto simbólico en el centro o úsalo como bastón de la palabra. Quien lo sostiene tiene el espacio para hablar; el resto escucha con presencia y apertura."],"citas":[],"preguntas":[],"nota":"Invita al grupo a escuchar sin interrumpir, aconsejar ni intentar solucionar la experiencia del otro. La intención es crear un espacio donde cada persona se sienta genuinamente vista."},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Reúne al grupo para compartir cómo se sintieron al hablar y al escuchar desde la presencia."],"citas":["A veces, la escucha consciente también es una forma de sanación."],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Finaliza con una respiración colectiva en silencio o una palabra de gratitud compartida por cada participante."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Modela tú la escucha activa — tu atención plena durante el turno de cada persona enseña más que cualquier instrucción.","origen":"fuente"},{"texto":"Si alguien habla demasiado largo, puedes hacer una señal suave con la mano para invitar a cerrar — sin interrumpir abruptamente.","origen":"fuente"},{"texto":"Recuerda al inicio que nadie está obligado a hablar — la escucha en silencio también es una forma válida de participar.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[30,31],"rol":"principal"},{"archivo":"edicion2","paginas":[32,33],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Receptiva · Pr