apertura"],"temas":["sonido","relajación","descanso"],"formato":["grupo"],"tipoFuente":"Grupal · Receptivo","duracion":{"min":45,"max":75,"texto":"45 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Profunda · Restauradora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas, mantas o colchonetas","ids":["cojines-esterillas","mantas"],"opcional":false},{"texto":"Almohadas o cojines de apoyo","ids":["cojines-esterillas"],"opcional":false},{"texto":"Instrumentos de sonido (ver sección inferior)","ids":["instrumentos"],"opcional":false},{"texto":"Vendas para los ojos (opcional)","ids":["vendas"],"opcional":true}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["meditacion-del-sonido-interior","escaneo-corporal"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Si no tienes instrumentos en vivo, una playlist de alta calidad de cuencos tibetanos funciona muy bien — lo que importa es la intención del espacio.","origen":"fuente"}],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Instrumentos recomendados","tipo":"lista","items":["Cuencos tibetanos","Campanas de cristal","Handpan","Sonidos naturales","Música ambiental","Flauta o didgeridoo"]},{"titulo":"Frases para acompañar la experiencia","tipo":"frases","items":["Permite que el sonido te acompañe.","No necesitas controlar la experiencia.","Solo respira y recibe."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Prepara el espacio cómodo y silencioso. Invita a los participantes a recostarse, cerrar los ojos y permitir que el cuerpo descanse sin necesidad de hacer nada."],"citas":[],"preguntas":[],"nota":null},{"id":"bano-de-sonido","nombre":"Baño de sonido","tipo":"desarrollo","tiempo":{"min":30,"max":50,"texto":"30 – 50 minutos"},"pasos":["A medida que los sonidos aparecen, guía suavemente la atención hacia la respiración, las sensaciones físicas y el momento presente. Usa las frases guía de forma espaciada y sin saturar."],"citas":[],"preguntas":[],"nota":"Deja largas pausas entre frases — el silencio entre los sonidos es tan importante como los sonidos mismos."},{"id":"transicion-suave","nombre":"Transición suave","tipo":"integracion","tiempo":{"min":5,"max":10,"texto":"5 – 10 minutos"},"pasos":["Permite unos minutos de silencio y quietud antes de invitar al grupo a regresar lentamente: mover los dedos, estirar el cuerpo, abrir los ojos despacio."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen pueden compartir cómo se sintieron. También es válido permanecer en silencio — algunos necesitan más tiempo para integrar."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Muévete con suavidad por el espacio si tocas instrumentos en vivo — evita ruidos bruscos o movimientos que rompan el estado de relajación.","origen":"fuente"},{"texto":"La transición de regreso es tan importante como el baño mismo — no apresures el cierre; es donde la experiencia se integra en el cuerpo.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[34,35],"rol":"principal"},{"archivo":"edicion2","paginas":[36,37],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Profunda · Restauradora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":50,"max":75},"orden":16},{"id":"circulo-de-historias-de-vida","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Historias de Vida","subtitulo":"Una experiencia para compartir aprendizajes, emociones y experiencias desde la autenticidad","resumen":"Una experiencia para compartir aprendizajes, emociones y experiencias desde la autenticidad","contexto":"Cada persona lleva consigo historias que han marcado su camino, sus decisiones y su forma de ver la vida. Esta dinámica invita al grupo a abrir un espacio de escucha y conexión humana a través de relatos personales compartidos desde la honestidad y la presencia.","objetivo":"Crear un espacio de conexión profunda donde los participantes puedan compartir relatos significativos de sus vidas, reconociendo que las experiencias humanas nos unen más de lo que imaginamos.","momentos":["conexion","exploracion"],"temas":["historias","escucha","círculo"],"formato":["grupo"],"tipoFuente":"Grupal · Círculo","duracion":{"min":60,"max":90,"texto":"60 – 90 minutos"},"notaDuracion":null,"nivelFuente":"Intermedio","energiaFuente":"Auténtica · Vincular","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio íntimo en círculo","ids":[],"opcional":false},{"texto":"Iluminación cálida y velas (opcional)","ids":["velas"],"opcional":true},{"texto":"Objeto simbólico como bastón de la palabra","ids":["objeto-palabra"],"opcional":false},{"texto":"Música suave solo para la apertura","ids":["musica"],"opcional":false}],"ambiente":["Espacio íntimo en círculo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["circulo-de-escucha-consciente","dinamica-de-conexion-humana"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Preguntas para invitar al relato","tipo":"preguntas","items":["¿Qué experiencia cambió la manera en que ves la vida?","¿Qué aprendizaje marcó un antes y un después en tu camino?","¿Qué parte de tu historia merece hoy ser reconocida?"],"cita":"No es necesario contar toda la historia. A veces, un momento pequeño también puede contener una gran transformación."}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Prepara el ambiente íntimo con iluminación cálida y música suave. Invita al grupo a sentarse en círculo y comenzar con unos minutos de respiración consciente para crear una energía de calma y apertura."],"citas":[],"preguntas":[],"nota":null},{"id":"relatos-compartidos","nombre":"Relatos compartidos","tipo":"desarrollo","tiempo":{"min":40,"max":60,"texto":"40 – 60 minutos"},"pasos":["Propone compartir una experiencia significativa que haya dejado un aprendizaje importante. Usa las preguntas guía como puerta de entrada, no como cuestionario."],"citas":[],"preguntas":[],"nota":"Invita al grupo a escuchar desde la empatía y la presencia, sin interrumpir ni intentar aconsejar. La intención no es encontrar respuestas perfectas, sino recordar que las experiencias humanas nos unen."},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Finaliza con una breve reflexión colectiva o unos minutos de silencio consciente, permitiendo que los relatos escuchados se integren desde la gratitud."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Comparte tú también una historia breve al inicio — modela la vulnerabilidad que invitas al grupo a vivir.","origen":"fuente"},{"texto":"Recuerda antes de comenzar que lo compartido en el círculo es confidencial y no sale del espacio.","origen":"fuente"},{"texto":"Si alguien se emociona al hablar, sostén el silencio — no intervengas con palabras; tu presencia tranquila ya acompaña.","origen":"fuente"}],"variantes":[{"id":"ed2-40","titulo":"Variante centrada en transformaciones (Edición 2, «Círculo de Historias Transformadoras»)","tituloFuente":"Círculo de Historias Transformadoras","estado":"revision","fuente":{"archivo":"edicion2","paginas":[86,87]},"nota":"Misma estructura central que el Círculo de Historias de Vida (círculo, compartir una experiencia significativa, escuchar sin aconsejar, cierre en silencio). Se registra como variante centrada en experiencias de transformación (incluye pérdidas).","subtitulo":"Un espacio para compartir experiencias que dejaron huella en el camino personal","contexto":"Cada persona guarda momentos que cambiaron su forma de ver la vida. Experiencias que, de una u otra manera, marcaron un antes y un después en su manera de sentir, pensar o relacionarse consigo misma.","fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente cálido e íntimo, acompañado de iluminación suave, velas o música tranquila que favorezca la presencia y la apertura emocional.","Invita al grupo a sentarse en círculo y comenzar con unos minutos de respiración consciente para crear una atmósfera de calma y confianza.","Después, propone compartir una experiencia de vida que haya generado una transformación importante: un cambio, una pérdida, un aprendizaje, una decisión o un momento que les permitió ver la vida de manera diferente. No es necesario contar todos los detalles.","Invita al resto del grupo a escuchar desde la empatía y la presencia, sin interrumpir ni intentar aconsejar.","Al finalizar, permite unos minutos de silencio o reflexión grupal para integrar lo compartido durante la experiencia."],"citas":[],"preguntas":["¿Qué experiencia transformó tu manera de verte a ti mismo?","¿Qué aprendizaje marcó una nueva etapa en tu vida?","¿Qué descubriste sobre ti a través de esa experiencia?"],"nota":null}]}],"fuentes":[{"archivo":"principal","paginas":[36,37],"rol":"principal"},{"archivo":"edicion2","paginas":[38,39],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Intermedio; energía: Auténtica · Vincular."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":60,"max":80},"orden":17},{"id":"conexion-con-la-naturaleza","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Conexión con la Naturaleza","subtitulo":"Una experiencia para reconectar con la calma, los sentidos y el entorno natural","resumen":"Una experiencia para reconectar con la calma, los sentidos y el entorno natural","contexto":"La naturaleza tiene una forma única de devolvernos al presente. Esta dinámica invita a los participantes a desacelerar, observar con más atención y conectar con el entorno desde una experiencia consciente y sensorial.","objetivo":"Invitar a los participantes a reconectar con el entorno natural desde la presencia plena, activando los sentidos como puerta de regreso al momento presente.","momentos":["apertura","integracion"],"temas":["naturaleza","sentidos","atención plena"],"formato":["grupo"],"tipoFuente":"Grupal · Exterior","duracion":{"min":60,"max":90,"texto":"60 – 90 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Enraizante · Sensorial","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"exterior","texto":"Naturaleza abierta"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Si alguien no puede o no quiere caminar o salir, ofrece un lugar cómodo desde donde participar.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Acorta o suspende el recorrido ante frío, calor intenso, terreno inseguro o cansancio del grupo.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["caminata-consciente","conexion-con-los-cuatro-elementos"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Elige el espacio con antelación y recórrelo tú primero para asegurarte de que sea seguro y tranquilo.","origen":"fuente"}],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Espacios recomendados","tipo":"lista","items":["Bosque o zona arbolada tranquila","Jardín o parque con poca afluencia","Playa, ribera o zona de agua","Montaña o terreno natural abierto"]},{"titulo":"Sentidos a activar durante el recorrido","tipo":"lista","items":["Colores y formas","Sonidos del entorno","Texturas y superficies","Temperatura y viento","Contacto con el suelo","Aromas naturales"]},{"titulo":"Frases para acompañar el recorrido","tipo":"frases","items":["Observa sin necesidad de interpretar.","Permite que el entorno también forme parte de la experiencia.","Respira con calma y vuelve al presente."]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Reúne al grupo en el espacio natural y presenta la intención: caminar en silencio, observar el entorno con presencia y dejar de lado conversaciones y distracciones externas."],"citas":[],"preguntas":[],"nota":null},{"id":"recorrido-sensorial","nombre":"Recorrido sensorial","tipo":"desarrollo","tiempo":{"min":30,"max":45,"texto":"30 – 45 minutos"},"pasos":["Invita al grupo a caminar lentamente y en silencio, activando los seis sentidos de la tabla superior. Acompaña con las frases guía de forma espaciada."],"citas":[],"preguntas":[],"nota":"Durante el recorrido, invita a cada participante a recolectar un elemento natural — hoja, piedra, rama — que represente algo significativo para ellos en este momento."},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":15,"max":20,"texto":"15 – 20 minutos"},"pasos":["Reúne nuevamente al grupo e invita a compartir qué elemento eligieron y qué significado tuvo para ellos durante la experiencia."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Finaliza recordando que no se trata de encontrar respuestas, sino de crear un momento de presencia, observación y conexión genuina con el entorno."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Camina tú también en silencio durante el recorrido — tu presencia modela el estado de calma que invitas al grupo a habitar.","origen":"fuente"},{"texto":"El elemento recolectado puede quedarse con el participante como recordatorio de la experiencia — un objeto pequeño que conecte con el retiro.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[39,40],"rol":"principal"},{"archivo":"edicion2","paginas":[42,43],"rol":"contraste"}],"correcciones":[],"incidencias":[{"tipo":"materiales","severidad":"baja","detalle":"La ficha no incluye lista de materiales (describe espacios y sentidos)."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Enraizante · Sensorial."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","s