momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Como cierre del retiro: su energía de reconocimiento e integración sella la experiencia colectiva.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["circulo-de-gratitud","circulo-de-cierre-del-retiro"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"¿Qué pueden agradecer los participantes?","tipo":"lista","items":["Una experiencia vivida durante el retiro","Un aprendizaje o descubrimiento personal","Una persona o conexión que surgió","Una emoción o parte de sí mismo que reconoció"]},{"titulo":"Frases para acompañar la experiencia","tipo":"frases","items":["La gratitud también es una forma de presencia.","Reconocer lo vivido nos ayuda a integrarlo.","A veces, los momentos más simples son los que más transforman."]},{"titulo":"Gestos colectivos de cierre","tipo":"lista","items":["Encender una vela como símbolo de la luz que cada persona lleva consigo al salir","Un abrazo grupal o gesto de contacto consciente entre todos","Unas respiraciones colectivas en silencio como sello final compartido"]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Prepara el espacio íntimo en círculo con luz cálida y velas. Comienza con una breve respiración consciente o un momento de silencio para conectar emocionalmente con la experiencia vivida."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-personal","nombre":"Reflexión personal","tipo":"integracion","tiempo":{"min":5,"max":10,"texto":"5 – 10 minutos"},"pasos":["Invita a los participantes a tomarse unos minutos en silencio para conectar con aquello que desean agradecer. Pueden escribirlo brevemente o simplemente dejarlo surgir desde el interior."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-colectivo","nombre":"Compartir colectivo","tipo":"integracion","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Cada participante comparte en voz alta aquello por lo que se siente agradecido, si así lo desea."],"citas":[],"preguntas":[],"nota":"Anima al grupo a escuchar desde la presencia y sin interrupciones. No se trata de decir algo perfecto, sino de reconocer aquello que realmente dejó huella."},{"id":"ritual-de-cierre","nombre":"Ritual de cierre","tipo":"cierre","tiempo":{"min":5,"max":10,"texto":"5 – 10 minutos"},"pasos":["Acompaña el cierre con uno de los gestos colectivos de la sección inferior para sellar la experiencia con presencia y significado."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Comparte tú también tu gratitud — modela la apertura emocional que invitas al grupo a vivir.","origen":"fuente"},{"texto":"Recibe cada agradecimiento con silencio y presencia — evita comentarios o aplausos que rompan la atmósfera ceremonial.","origen":"fuente"},{"texto":"Usa esta dinámica como cierre del retiro — su energía de reconocimiento e integración es perfecta para sellar la experiencia colectiva.","origen":"fuente"}],"variantes":[{"id":"ed2-64","titulo":"Variante centrada en el grupo (Edición 2, «Ritual de Gratitud al Grupo»)","tituloFuente":"Ritual de Gratitud al Grupo","estado":"revision","fuente":{"archivo":"edicion2","paginas":[134,135]},"nota":"Misma estructura central que el Ritual de Gratitud Colectiva (círculo de gratitud con gesto colectivo de cierre), centrada en agradecer a las personas del grupo.","subtitulo":"Un momento para reconocer la conexión, el apoyo y la experiencia compartida","contexto":null,"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente cálido e íntimo, acompañado de velas, música suave o iluminación tenue. Invita a los participantes a reunirse en círculo y comenzar con unas respiraciones conscientes.","Guía una breve reflexión sobre la importancia de los encuentros humanos y cómo cada persona aporta algo único dentro de una experiencia grupal.","Invita a cada participante a expresar unas palabras de gratitud hacia el grupo, hacia una persona en particular o hacia la experiencia compartida. No es necesario decir algo perfecto.","Puedes cerrar la experiencia con un gesto colectivo: una respiración compartida, un abrazo grupal, unas palabras finales o unos minutos de silencio consciente."],"citas":[],"preguntas":["¿Qué aprendiste gracias a las personas de este grupo?","¿Qué conexión o conversación dejó huella en ti?","¿Qué te gustaría agradecer hoy?"],"nota":null}]}],"fuentes":[{"archivo":"principal","paginas":[41,42],"rol":"principal"},{"archivo":"edicion2","paginas":[44,45],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Cálida · Integradora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":45,"max":60},"orden":19},{"id":"visualizacion-del-futuro","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Visualización del Futuro","subtitulo":"Una experiencia para conectar con la vida que deseas construir","resumen":"Una experiencia para conectar con la vida que deseas construir","contexto":"A veces necesitamos detenernos unos minutos para recordar hacia dónde realmente queremos ir. Esta dinámica invita a los participantes a visualizar con mayor claridad la vida, la energía y las experiencias que desean comenzar a crear a partir de este momento.","objetivo":"Conectar a los participantes con una visión más clara y consciente de la vida que desean construir, guiándolos desde las emociones y sensaciones más que desde los objetivos materiales.","momentos":["exploracion","integracion"],"temas":["visión","visualización","escritura"],"formato":["grupo"],"tipoFuente":"Grupal · Visualización","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Expansiva · Esperanzadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas, cojines o sillas cómodas","ids":["cojines-esterillas","sillas"],"opcional":false},{"texto":"Música suave o sonidos naturales","ids":["musica"],"opcional":false},{"texto":"Iluminación tenue para favorecer la calma","ids":[],"opcional":false},{"texto":"Papel y bolígrafos para integración escrita","ids":["papel","boligrafos"],"opcional":false}],"ambiente":["Iluminación tenue para favorecer la calma"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Si una imagen resulta incómoda, se puede abrir los ojos, volver a la respiración o dejar la visualización y descansar.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["mapa-de-suenos-e-intenciones","meditacion-templo-interior"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Preguntas guía de la visualización","tipo":"preguntas","items":["¿Cómo se siente esa versión futura de ti?","¿Qué decisiones comenzó a tomar?","¿Qué dejó atrás para llegar hasta ahí?","¿Qué energía transmite su vida hoy?"],"nota":"Guía hacia emociones y sensaciones más que hacia logros materiales. No es \"predecir el futuro\", sino conectar con una dirección más consciente y auténtica."}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Prepara el ambiente tranquilo con música suave e iluminación tenue. Invita al grupo a recostarse o sentarse cómodamente. Guía unas respiraciones lentas para relajar el cuerpo y conectar con el momento presente."],"citas":[],"preguntas":[],"nota":null},{"id":"visualizacion-guiada","nombre":"Visualización guiada","tipo":"desarrollo","tiempo":{"min":20,"max":25,"texto":"20 – 25 minutos"},"pasos":["Invita a los participantes a imaginar una versión futura de sí mismos viviendo una vida más alineada, plena y consciente. Acompaña con las cuatro preguntas guía de forma lenta y espaciada."],"citas":["Invita a conectar no solo con imágenes, sino también con las emociones y sensaciones que aparecen durante la experiencia."],"preguntas":[],"nota":null},{"id":"silencio-e-integracion","nombre":"Silencio e integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Permite unos minutos de silencio al finalizar la visualización para que cada participante integre lo vivido desde la calma antes de volver al espacio compartido."],"citas":[],"preguntas":[],"nota":null},{"id":"escritura-y-cierre","nombre":"Escritura y cierre","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Invita a escribir algunas reflexiones, palabras o intenciones surgidas durante la práctica. Quienes lo deseen pueden compartir brevemente con el grupo."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Narra en tiempo presente — \"eres\", \"sientes\", \"vives\" — para que el cuerpo y la mente vivan la experiencia como real, no como fantasía.","origen":"fuente"},{"texto":"Evita describir logros materiales concretos — guía hacia estados emocionales, calidad de vida y relaciones, que son universales y no limitan la experiencia.","origen":"fuente"},{"texto":"Respeta el silencio posterior — algunos participantes necesitan más tiempo para integrar; no apresures el regreso al espacio grupal.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[43,44],"rol":"principal"},{"archivo":"edicion2","paginas":[46,47],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Expansiva · Esperanzadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":43,"max":51},"orden":20},{"id":"espejo-de-las-sombras","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Espejo de las Sombras","subtitulo":"Una experiencia para reconocer y abrazar las partes de nosotros que solemos evitar","resumen":"Una experiencia para reconocer y abrazar las partes de nosotros que solemos evitar","contexto":"Muchas veces, aquello que más rechazamos de nosotros mismos también guarda aprendizajes importantes. Esta dinámica invita a los participantes a observar con honestidad ciertas emociones, patrones o aspectos personales que normalmente intentan ocultar, negar o evitar.","objetivo":"Crear un espacio seguro de introspección donde los participantes puedan observar sus sombras personales con consciencia y compasión, sin juzgarlas ni intentar eliminarlas.","momentos":["exploracion"],"temas":["sombra","autoconocimiento","escritura"],"formato":["individual"],"tipoFuente":"Individual · Escritura","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Profundo","energiaFuente":"Honesta · Compasiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Iluminación tenue y música suave","ids":["musica"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false},{"texto":"Espacio con mayor intimidad y silencio","ids":[],"opcional":false}],"ambiente":["Espacio con mayor intimidad y silencio"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["integracion-sombra-luz","viaje-de-los-arquetipos"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles y visibles — esta dinámica puede mover emociones profundas e inesperadas.","origen":"fuente"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Aspectos que puede explorar la sombra","tipo":"lista","items":["Miedos","Inseguridades","Enojo","Culpa","Autoexigencia","Emociones reprimidas"],"nota":"La intención no es juzgar ni \"eliminar\" esas partes, sino observarlas con más consciencia y compasión. Todas forman parte de la experiencia humana."},{"titulo":"Preguntas de reflexión","tipo":"preguntas","items":["¿Qué parte de mí suelo esconder de los demás?","¿Qué emoción me cuesta más aceptar?","¿Qué intento controlar o evitar constantemente?","¿Qué necesitaría escuchar esa parte de mí?"],"cita":"El crecimiento personal también implica aprender a mirar nuestras sombras con más comprensión y menos juicio."}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Crea un ambiente íntimo y emocionalmente seguro. Guía una breve reflexión sobre cómo todas las personas tienen partes luminosas y partes más incómodas, y cómo ambas forman parte de la experiencia humana."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-e-introspeccion","nombre":"Reflexión e introspección","tipo":"integracion","tiempo":{"min":30,"max":35,"texto":"30 – 35 minutos"},"pasos":["Invita al grupo a escribir o reflexionar sobre los aspectos de su sombra usando las preguntas guía. Permite que el proceso ocurra desde la introspección, en silencio y sin presión de compartir."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Invita al grupo a respirar profundamente y reconocer que observar las sombras con compasión ya es un acto de crecimiento. Abre un pequeño espacio voluntario para compartir reflexiones."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Cierra con una respiración colectiva y una frase de cierre que honre el coraje de mirar hacia adentro sin juzgarse."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Introduce el concepto de \"sombra\" con suavidad y sin dramatismo — no es lo oscuro que hay que temer, sino lo desconocido que merece ser visto.","origen":"fuente"},{"texto":"Nunca presiones a compartir — lo que cada persona descubra en su sombra le pertenece solo a ella.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[47,48],"rol":"principal"},{"archivo":"edicion2","paginas":[50,51],"rol":"contraste"}],"correcciones":[],"incidencias":[{"tipo":"categoria","severidad":"baja","detalle":"El encabezado de la ficha la ubica en «Trabajando con los chakras y la energía», aunque el contenido trata la sombra personal."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Profundo; energía: Honesta · Compasiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":65},"orden":21},{"id":"ritual-del-perdon","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Ritual del Perdón","subtitulo":"Una experiencia para liberar emociones y crear espacio para una mayor paz interior","resumen":"Una experiencia para liberar emociones y crear espacio para una mayor paz interior","contexto":"Perdonar no siempre significa olvidar lo vivido. A veces, significa dejar de cargar aquello que ya no queremos seguir sosteniendo dentro de nosotros. Esta dinámica invita a los participantes a reflexionar sobre emociones, heridas o situaciones que aún generan peso emocional, creando un espacio consciente de liberación y compasión.","objetivo":"Abrir un espacio seguro donde los participantes puedan explorar el perdón como un acto de liberación personal, comenzando a transformar la relación con aquello que aún genera peso emocional.","momentos":["exploracion"],"temas":["perdón","ritual","escritura","fuego"],"formato":["individual"],"tipoFuente":"Individual · Ritual","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Profundo","energiaFuente":"Compasiva · Liberadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Velas e iluminación cálida","ids":["velas"],"opcional":false},{"texto":"Música suave o cuencos tibetanos","ids":["cuenco-campana","musica"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Ofrece siempre una alternativa sin fuego (romper, enterrar o guardar el papel) para quien prefiera no usarlo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"},{"texto":"Si el fuego se vuelve difícil de controlar (viento, chispas), suspende el acto con fuego y pasa a la alternativa sin fuego.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ritual-de-autoperdon","ritual-de-liberacion"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles — esta dinámica puede mover emociones profundas. Sostén el espacio con calma sin intervenir ni apresurar el proceso.","origen":"fuente"},{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar la reflexión","tipo":"preguntas","items":["¿Qué emoción sigo cargando dentro de mí?","¿Qué parte de esta historia necesita más compasión?","¿Qué cambiaría en mí si dejara de sostener este peso emocional?"],"cita":"El propósito no es justificar lo ocurrido, sino permitir que cada persona explore qué necesita soltar para recuperar más paz y ligereza interior."},{"titulo":"Gestos simbólicos de cierre","tipo":"lista","items":["Romper el papel conscientemente como acto de soltar","Guardarlo en un sobre — para volver a él cuando el momento lo pida","Quemarlo de forma segura como símbolo de liberación","Sostener unos minutos de silencio consciente como cierre"]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Prepara el ambiente íntimo y tranquilo con velas y música suave. Guía unas respiraciones lentas e introduce el concepto del perdón como liberación personal, no como justificación de lo ocurrido."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-y-escritura","nombre":"Reflexión y escritura","tipo":"integracion","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a cada participante a pensar en una persona, situación o experiencia que aún necesite comprensión, cierre o liberación emocional. Guía la reflexión con las preguntas de la sección superior."],"citas":[],"preguntas":[],"nota":"La experiencia es completamente personal. No es necesario compartirlo ni explicarlo. Cada proceso tiene su propio ritmo y profundidad."},{"id":"gesto-simbolico","nombre":"Gesto simbólico","tipo":"desarrollo","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Cuando todos hayan terminado, invita al grupo a realizar el gesto simbólico de cierre que más resuene con su proceso. Acompaña con presencia y silencio."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion-y-cierre","nombre":"Integración y cierre","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Guía unas respiraciones profundas colectivas. Quienes lo deseen pueden compartir brevemente cómo se sienten. Cierra recordando que el perdón es un proceso, no un evento único."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Distingue claramente desde el inicio: perdonar no es justificar lo ocurrido, sino dejar de cargar el peso emocional que genera en uno mismo.","origen":"fuente"},{"texto":"Recuerda al grupo que el perdón también puede ser hacia uno mismo — a veces es la herida más difícil de sanar y la más importante de reconocer.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[49,50],"rol":"principal"},{"archivo":"edicion2","paginas":[52,53],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Profundo; energía: Compasiva · Liberadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":60},"orden":22},{"id":"constelacion-onirica","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Constelación Onírica","subtitulo":"Una experiencia para explorar los mensajes del inconsciente a través de los sueños","resumen":"Una experiencia para explorar los mensajes del inconsciente a través de los sueños","contexto":"Los sueños son una de las formas más antiguas de comunicación del inconsciente. Esta dinámica invita a los participantes a explorar los símbolos, emociones y mensajes que aparecen en sus sueños, utilizándolos como espejo de sus procesos internos más profundos.","objetivo":"Invitar a los participantes a explorar sus sueños como fuente de autoconocimiento, decodificando sus símbolos e imágenes desde la intuición y la reflexión personal.","momentos":["exploracion"],"temas":["sueños","símbolos","escritura"],"formato":["individual"],"tipoFuente":"Individual · Escritura","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Intermedio","energiaFuente":"Simbólica · Introspectiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Cuaderno o papel individual","ids":["papel"],"opcional":false},{"texto":"Bolígrafos y lápices de colores (opcional)","ids":["boligrafos","colores"],"opcional":true},{"texto":"Iluminación tenue y música suave","ids":["musica"],"opcional":false},{"texto":"Espacio tranquilo propicio para la introspección","ids":[],"opcional":false}],"ambiente":["Espacio tranquilo propicio para la introspección"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["viaje-de-los-arquetipos","escritura-libre"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten lista la alternativa para quienes no recuerdan sueños — una imagen o sensación recurrente funciona igual de bien como punto de partida.","origen":"fuente"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Capas de exploración del sueño","tipo":"lista","items":["Imagen central — ¿Qué imagen, lugar o figura recuerdas con más intensidad?","Emoción predominante — ¿Qué sentiste durante el sueño o al despertar?","Símbolos — ¿Qué elementos o personas aparecieron? ¿Qué representan para ti?","Mensaje — ¿Qué crees que intenta comunicar tu inconsciente?","Conexión presente — ¿Qué relación tiene este sueño con lo que estás viviendo hoy?"],"nota":"No existe una interpretación única ni correcta. Cada persona conoce mejor que nadie el lenguaje de su propio inconsciente. La intuición es la guía principal."},{"titulo":"Frases para acompañar la exploración","tipo":"frases","items":["No busques el significado correcto — busca el que resuena.","Los sueños hablan en imágenes, no en lógica.","Confía en lo que sientes al recordarlos."]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Prepara el ambiente tranquilo con música suave. Introduce brevemente el concepto de los sueños como lenguaje del inconsciente, y cómo sus símbolos pueden reflejar procesos emocionales internos."],"citas":[],"preguntas":[],"nota":null},{"id":"exploracion-escrita","nombre":"Exploración escrita","tipo":"desarrollo","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a los participantes a evocar un sueño reciente o recurrente y explorarlo usando las cinco capas de la tabla superior. Permite el silencio y la música como compañía durante el proceso."],"citas":["Si alguien no recuerda sueños, puede explorar una imagen, metáfora o sensación recurrente que aparezca en su vida consciente."],"preguntas":[],"nota":null},{"id":"compartir-voluntario","nombre":"Compartir voluntario","tipo":"integracion","tiempo":{"min":15,"max":20,"texto":"15 – 20 minutos"},"pasos":["Quienes lo deseen pueden compartir su sueño y los descubrimientos surgidos durante la exploración. El grupo escucha en presencia, sin interpretar ni analizar la experiencia ajena."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Finaliza con una respiración consciente y una invitación a prestar más atención a los mensajes que aparecen durante el sueño como parte de su proceso de autoconocimiento."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Nunca interpretes el sueño de otra persona — cada símbolo tiene un significado único para quien lo vivió. Tu rol es acompañar la exploración, no analizar.","origen":"fuente"},{"texto":"Sugiere llevar un diario de sueños durante el retiro — escribirlos al despertar potencia la conexión con el inconsciente a lo largo de los días.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[51,52],"rol":"principal"},{"archivo":"edicion2","paginas":[54,55],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Intermedio; energía: Simbólica · Introspectiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":65},"orden":23},{"id":"viaje-chamanico-guiado","version":1,"estado":"revision","motivoEstado":"Requiere revisión especializada: busca «estados expandidos de conciencia» con tambor a 4–7 golpes por segundo y vendas en los ojos; la propia ficha recomienda experiencia previa del facilitador. La Edición 2 trae una versión más suave (variante pendiente).","titulo":"Viaje Chamánico Guiado","subtitulo":"Una experiencia para conectar con la sabiduría ancestral y los mundos interiores","resumen":"Una experiencia para conectar con la sabiduría ancestral y los mundos interiores","contexto":"El viaje chamánico es una de las prácticas más antiguas de la humanidad para acceder a estados expandidos de conciencia. A través del ritmo del tambor y la guía del facilitador, los participantes son invitados a explorar sus mundos interiores en busca de mensajes, símbolos y sabiduría que el estado ordinario no siempre revela.","objetivo":"Guiar a los participantes en un viaje de introspección profunda a través del sonido rítmico del tambor, conectando con símbolos, animales de poder e imágenes que emergen desde el inconsciente.","momentos":["exploracion"],"temas":["tambor","visualización","estados expandidos"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":60,"max":90,"texto":"60 – 90 minutos"},"notaDuracion":null,"nivelFuente":"Profundo","energiaFuente":"Ancestral · Expandida","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Tambor chamánico o grabación de ritmo de tambor","ids":["tambor"],"opcional":false},{"texto":"Esterillas, mantas y cojines","ids":["cojines-esterillas","mantas"],"opcional":false},{"texto":"Vendas para los ojos (favorecen la inmersión)","ids":["vendas"],"opcional":false},{"texto":"Papel y bolígrafos para integración escrita","ids":["papel","boligrafos"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Si una imagen resulta incómoda, se puede abrir los ojos, volver a la respiración o dejar la visualización y descansar.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["meditacion-templo-interior","constelacion-onirica"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Si no tienes tambor, una grabación de 4–7 BPS (beats por segundo) de ritmo chamánico funciona muy bien — hay muchas disponibles en plataformas de audio.","origen":"fuente"},{"texto":"Realiza tú mismo este viaje antes de facilitarlo — la experiencia personal es la mejor preparación y te permitirá guiar desde la autenticidad.","origen":"fuente"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Los tres mundos del viaje chamánico","tipo":"lista","items":["Mundo inferior · La raíz — Espacio de los instintos, los animales de poder y la sabiduría corporal. Se accede a través de la tierra y las raíces.","Mundo medio · El presente — El aquí y ahora. El espacio del cuerpo, las emociones y las situaciones que necesitan atención en el momento actual.","Mundo superior · La visión — Espacio de los guías, la inspiración y la perspectiva más amplia. Se accede a través de la luz y la elevación."]},{"titulo":"Frases para acompañar el viaje","tipo":"frases","items":["Permite que el tambor te guíe — no necesitas controlar adónde vas.","Observa lo que aparece sin juzgarlo ni descartarlo.","Cada imagen, animal o símbolo tiene un mensaje para ti."]}],"fases":[{"id":"preparacion-sagrada","nombre":"Preparación sagrada","tipo":"apertura","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Prepara el espacio con intención: iluminación tenue, incienso o elementos naturales si el contexto lo permite. Invita al grupo a recostarse y guía unas respiraciones profundas para relajar el cuerpo y entrar en estado receptivo."],"citas":[],"preguntas":[],"nota":null},{"id":"viaje-guiado","nombre":"Viaje guiado","tipo":"desarrollo","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["Inicia el tambor a un ritmo constante de 4–7 golpes por segundo. Guía el descenso al mundo inferior, el recorrido por el mundo medio o el ascenso al mundo superior según la intención del grupo."],"citas":[],"preguntas":[],"nota":"Al finalizar, cambia el ritmo del tambor a una señal de retorno — generalmente cuatro golpes rápidos seguidos de cuatro lentos — para invitar a los participantes a regresar conscientemente."},{"id":"escritura-e-integracion","nombre":"Escritura e integración","tipo":"integracion","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Invita a los participantes a escribir inmediatamente lo que vieron, sintieron o recibieron durante el viaje — imágenes, animales, mensajes, emociones — antes de que se desvanezca."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Quienes lo deseen comparten su experiencia. Cierra con un gesto de gratitud hacia los mundos visitados y una respiración colectiva de anclaje al presente."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Algunas personas pueden vivir experiencias muy intensas. Ten pañuelos disponibles y sostén el espacio con calma — lo que emerge durante el viaje merece ser recibido sin prisa.","origen":"fuente"}],"variantes":[{"id":"ed2-25","titulo":"Versión de visualización suave (Edición 2)","tituloFuente":"Viaje Chamánico Guiado","estado":"revision","fuente":{"archivo":"edicion2","paginas":[56,57]},"nota":"Versión más suave: visualización con música rítmica suave, sin vendas ni ritmo de tambor especificado (4–7 golpes/s) ni 'tres mundos'.","subtitulo":"Una experiencia para conectar con la intuición, la naturaleza y la sabiduría interior","contexto":"Desde hace siglos, distintas culturas han utilizado el viaje interior como una forma de reconectar con la intuición, los símbolos y la relación profunda entre el ser humano y la naturaleza. Esta dinámica invita a los participantes a vivir una experiencia de visualización y exploración interior acompañada de sonidos, respiración y estados de mayor presencia.","fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y contenido, preferiblemente con iluminación tenue, elementos naturales y música rítmica suave como tambores, sonidos tribales o instrumentos ancestrales.","Invita al grupo a sentarse o recostarse cómodamente y comenzar con unas respiraciones profundas para relajar el cuerpo y aquietar la mente.","A medida que la experiencia avanza, guía una visualización donde cada participante imagine un recorrido simbólico a través de paisajes naturales, senderos, montañas o bosques.","Después de la visualización, deja unos minutos de silencio para integrar la experiencia antes de invitar al grupo a escribir, dibujar o compartir aquello que vivieron durante el recorrido interior."],"citas":["Permite que el viaje se revele a su propio ritmo.","Confía en aquello que aparece dentro de ti.","No necesitas entenderlo todo, solo observar."],"preguntas":[],"nota":"La intención no es dirigir exactamente lo que deben ver, sino abrir un espacio para que cada persona conecte con imágenes, emociones o sensaciones que aparezcan de forma espontánea. El objetivo no es interpretar literalmente las imágenes surgidas, sino favorecer un espacio de introspección, conexión y escucha interna."}]}],"fuentes":[{"archivo":"principal","paginas":[53,54],"rol":"principal"},{"archivo":"edicion2","paginas":[56,57],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Profundo; energía: Ancestral · Expandida."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":80},"orden":24},{"id":"escaneo-corporal","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Escaneo Corporal","subtitulo":"Una práctica de atención plena para reconectar con las señales y sensaciones del cuerpo","resumen":"Una práctica de atención plena para reconectar con las señales y sensaciones del cuerpo","contexto":"El cuerpo guarda información que la mente a veces no sabe procesar. Esta práctica invita a los participantes a llevar su atención de forma consciente y sistemática a cada zona del cuerpo, observando tensiones, sensaciones, emociones y mensajes que emergen desde el interior.","objetivo":"Desarrollar la conciencia corporal de los participantes a través de una práctica de atención plena que recorre el cuerpo de forma sistemática, favoreciendo la presencia y la escucha interior.","momentos":["apertura","integracion"],"temas":["cuerpo","atención plena","relajación"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Suave · Enraizante","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas, mantas o colchonetas","ids":["cojines-esterillas","mantas"],"opcional":false},{"texto":"Música suave o silencio","ids":["musica"],"opcional":false},{"texto":"Cojines de apoyo para cabeza y rodillas","ids":["cojines-esterillas"],"opcional":false},{"texto":"Temperatura agradable en el espacio","ids":[],"opcional":false}],"ambiente":["Temperatura agradable en el espacio"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Como apertura del día en un retiro: prepara el cuerpo y la mente para recibir lo que viene con más presencia.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["meditacion-respiracion-consciente","ritual-de-agradecimiento-al-cuerpo"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Recorrido del escaneo — de pies a cabeza","tipo":"lista","items":["Pies y piernas — Contacto con el suelo, peso, temperatura, tensión o calor","Pelvis y caderas — Apertura, bloqueo, fluidez o rigidez en esta zona","Abdomen — Movimiento con la respiración, tensión, emoción guardada","Pecho y corazón — Expansión o contracción, peso emocional, apertura o cierre","Hombros y cuello — Carga, tensión, bloqueos relacionados con la expresión","Rostro y mandíbula — Tensión en la frente, ojos, maxilar — emociones contenidas","Coronilla — Sensación de apertura, ligereza o expansión en la cima"]},{"titulo":"Frases para guiar la práctica","tipo":"frases","items":["Lleva tu atención a esta zona — sin intentar cambiar nada.","Observa lo que sientes sin juzgarlo ni forzarlo.","Respira hacia esa zona y permite que se relaje naturalmente."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a recostarse cómodamente con los ojos cerrados. Guía unas respiraciones lentas para soltar el ritmo del día y conectar con el cuerpo."],"citas":[],"preguntas":[],"nota":null},{"id":"escaneo-corporal","nombre":"Escaneo corporal","tipo":"desarrollo","tiempo":{"min":20,"max":30,"texto":"20 – 30 minutos"},"pasos":["Recorre las siete zonas de la tabla superior de forma pausada, dedicando 2 a 4 minutos a cada una. En cada zona invita a observar sensaciones, temperatura, tensión o emociones sin intentar cambiarlas."],"citas":[],"preguntas":[],"nota":"El ritmo es fundamental — no te apresures. Los participantes necesitan tiempo para realmente sentir cada zona. Si alguien se duerme, está bien — el cuerpo necesitaba ese descanso."},{"id":"retorno-y-silencio","nombre":"Retorno y silencio","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita a los participantes a tomar conciencia de todo el cuerpo a la vez — desde los pies hasta la coronilla — y a regresar lentamente al espacio antes de abrir los ojos."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen pueden compartir brevemente qué zona llamó más su atención y qué observaron. No es obligatorio — el silencio también integra."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Habla despacio y con pausas largas — el silencio entre frases es parte de la práctica, no un error a llenar.","origen":"fuente"},{"texto":"Dedica más tiempo al pecho y al abdomen — son las zonas donde más emociones se acumulan y más necesitan presencia.","origen":"fuente"},{"texto":"Esta práctica funciona excelente como apertura del día en un retiro — prepara el cuerpo y la mente para recibir lo que viene con más presencia.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[57,58],"rol":"principal"},{"archivo":"edicion2","paginas":[60,61],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Suave · Enraizante."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":35,"max":45},"orden":25},{"id":"circulo-de-compartir-intenciones","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Compartir Intenciones","subtitulo":"Un espacio sagrado para nombrar en voz alta aquello que deseamos crear y honrar","resumen":"Un espacio sagrado para nombrar en voz alta aquello que deseamos crear y honrar","contexto":"Nombrar una intención en voz alta, frente a otros, tiene un poder transformador que el pensamiento silencioso raramente alcanza. Esta dinámica invita al grupo a compartir sus intenciones desde la presencia y la autenticidad, creando un espacio de compromiso colectivo.","objetivo":"Crear un espacio sagrado donde cada participante pueda nombrar y sostener su intención personal frente al grupo, fortaleciendo el compromiso con su proceso a través del poder de la palabra compartida.","momentos":["apertura","cierre"],"temas":["intención","círculo","palabra"],"formato":["grupo"],"tipoFuente":"Grupal · Círculo","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Clara · Comprometida","momentoFuente":"Apertura o cierre","enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio en círculo con iluminación cálida","ids":[],"opcional":false},{"texto":"Vela central como foco de la intención","ids":["vela-central"],"opcional":false},{"texto":"Papel para escribir la intención antes de compartirla","ids":["papel"],"opcional":false},{"texto":"Objeto simbólico como bastón de la palabra","ids":["objeto-palabra"],"opcional":false}],"ambiente":["Espacio en círculo con iluminación cálida"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Al inicio del retiro siembra dirección; al cierre sella el compromiso personal con lo vivido.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["ceremonia-de-intenciones","ritual-de-intencion-al-amanecer"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Tipos de intención que pueden compartirse","tipo":"lista","items":["Algo que deseo comenzar a cultivar","Algo que estoy listo para soltar o dejar ir","Una cualidad o energía que deseo fortalecer","Una dirección o decisión que deseo honrar"]},{"titulo":"Acuerdos del círculo","tipo":"lista","items":["Escuchar cada intención en silencio y con presencia plena, sin interrumpir ni comentar.","Recibir cada intención con respeto — lo que se nombra aquí es sagrado y no sale del círculo.","No es necesario explicar ni justificar — la intención se nombra, se sostiene y se honra."],"cita":"Cuando nombramos algo en voz alta frente a otros, ya no es solo un deseo — se convierte en un compromiso con nosotros mismos."}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Crea el ambiente íntimo con vela central y disposición en círculo. Antes de abrir el espacio, comparte los tres acuerdos del círculo con el grupo y guía una breve respiración de conexión."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-escrita","nombre":"Reflexión escrita","tipo":"integracion","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Invita a cada participante a escribir en silencio su intención antes de compartirla. Esto permite clarificar y conectar emocionalmente con lo que desea expresar."],"citas":[],"preguntas":[],"nota":"Invita a que la intención sea concreta y personal — una frase que comience con \"Mi intención es…\" o \"Yo elijo…\" tiene más fuerza que una idea abstracta."},{"id":"compartir-en-circulo","nombre":"Compartir en círculo","tipo":"integracion","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["Pasa el objeto simbólico y cada persona comparte su intención en voz alta cuando lo recibe. El grupo escucha en silencio. Después de cada intención, puedes invitar a un breve momento de pausa antes de continuar."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Finaliza con una respiración colectiva o un gesto de cierre que honre las intenciones compartidas — puede ser un momento de silencio o una palabra de reconocimiento del grupo."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Comparte tú también una intención — modelas la vulnerabilidad y el compromiso que invitas al grupo a vivir.","origen":"fuente"},{"texto":"Guarda unos segundos de silencio después de cada intención — ese espacio honra lo que fue dicho y permite que resuene en el grupo.","origen":"fuente"},{"texto":"Esta dinámica funciona tanto al inicio como al cierre del retiro — al inicio siembra dirección; al cierre sella el compromiso personal con lo vivido.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[59,60],"rol":"principal"},{"archivo":"edicion2","paginas":[62,63],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Clara · Comprometida."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":48,"max":60},"orden":26},{"id":"meditacion-del-arbol","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Meditación del Árbol","subtitulo":"Una práctica de enraizamiento para conectar con la estabilidad, la calma y la sabiduría de la naturaleza","resumen":"Una práctica de enraizamiento para conectar con la estabilidad, la calma y la sabiduría de la naturaleza","contexto":"Los árboles llevan milenios siendo símbolos de sabiduría, estabilidad y conexión entre mundos. Esta meditación invita a los participantes a habitar la metáfora del árbol desde dentro — echando raíces profundas, permaneciendo firmes y expandiéndose hacia la luz.","objetivo":"Guiar a los participantes en una meditación de enraizamiento que conecta con la estabilidad interior, la presencia en el cuerpo y la sabiduría de la naturaleza a través de la imagen del árbol.","momentos":["apertura"],"temas":["naturaleza","enraizamiento","visualización"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Enraizante · Serena","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"ambos","texto":"Interior o exterior"},"participantes":null,"materiales":[{"texto":"Esterillas o sillas cómodas","ids":["cojines-esterillas","sillas"],"opcional":false},{"texto":"Música de naturaleza o silencio","ids":["musica"],"opcional":false},{"texto":"Espacio rodeado de árboles (si es posible)","ids":[],"opcional":true},{"texto":"Papel para reflexión escrita al finalizar (opcional)","ids":["papel"],"opcional":true}],"ambiente":["Espacio rodeado de árboles (si es posible)"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Como apertura del día: enraíza al grupo antes de cualquier actividad más intensa o emocionalmente profunda.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["escaneo-corporal","conexion-con-la-naturaleza"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Las tres partes del árbol — guía de la meditación","tipo":"lista","items":["Las raíces · Enraizamiento — Sientes cómo tus pies y piernas se hunden suavemente en la tierra. Raíces profundas te anclan, te sostienen y te conectan con la energía estable de la tierra bajo ti.","El tronco · Presencia — Tu columna es el tronco — firme, tranquilo, centrado. No rígido, sino vivo. Capaz de moverse con el viento sin perder su centro.","La copa · Expansión — Desde la coronilla, ramas de luz se expanden hacia el cielo. Recibes claridad, inspiración y conexión con algo más grande que tú mismo."]},{"titulo":"Frases para guiar la meditación","tipo":"frases","items":["Eres tan firme como un árbol antiguo — y tan flexible como sus ramas.","Cuanto más profundas son tus raíces, más alto puedes crecer.","Permite que la tierra te sostenga — no tienes que sostenerte solo."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse cómodamente con los pies apoyados en el suelo o recostarse. Guía unas respiraciones lentas para soltar tensiones y llegar al cuerpo."],"citas":[],"preguntas":[],"nota":null},{"id":"meditacion-del-arbol","nombre":"Meditación del árbol","tipo":"desarrollo","tiempo":{"min":20,"max":30,"texto":"20 – 30 minutos"},"pasos":["Recorre las tres partes del árbol de forma pausada — raíces, tronco y copa — usando los textos de la sección superior como guía narrativa. Deja pausas largas entre cada parte para que la imagen se instale en el cuerpo."],"citas":[],"preguntas":[],"nota":"Si la práctica es al aire libre, invita a los participantes a apoyar la espalda en un árbol real. La experiencia se vuelve mucho más visceral e inmediata."},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Invita a los participantes a regresar lentamente al espacio. Quienes lo deseen pueden compartir con qué parte del árbol conectaron más y qué les comunicó esa imagen."],"citas":["A veces, recordar que somos como un árbol es suficiente para volver al centro."],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Habla con voz lenta y profunda — el tono de tu voz es el ritmo del árbol que el grupo habitará durante la práctica.","origen":"fuente"},{"texto":"Si alguien prefiere estar de pie, permítelo — sentir el contacto real de los pies con la tierra enriquece la experiencia del enraizamiento.","origen":"fuente"},{"texto":"Esta práctica funciona muy bien como apertura del día en un retiro — enraíza al grupo antes de cualquier actividad más intensa o emocionalmente profunda.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[61,62],"rol":"principal"},{"archivo":"edicion2","paginas":[64,65],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Enraizante · Serena."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":30,"max":43},"orden":27},{"id":"viaje-de-las-emociones","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Viaje de las Emociones","subtitulo":"Una experiencia para explorar el universo emocional y navegar el mundo interior con más consciencia","resumen":"Una experiencia para explorar el universo emocional y navegar el mundo interior con más consciencia","contexto":"Las emociones no son problemas que resolver — son mensajes que escuchar. Esta dinámica invita a los participantes a explorar su mundo emocional desde adentro, visitando diferentes estados con presencia y curiosidad en lugar de resistencia o juicio.","objetivo":"Guiar a los participantes en un viaje meditativo que recorre diferentes estados emocionales, desarrollando la capacidad de observarlos, nombrarlos y habitarlos sin resistencia.","momentos":["exploracion"],"temas":["emociones","meditación","expresión creativa"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Intermedio","energiaFuente":"Receptiva · Profunda","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas, cojines o mantas","ids":["cojines-esterillas","mantas"],"opcional":false},{"texto":"Música instrumental suave y variada","ids":["musica"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false},{"texto":"Papel y lápices para integración creativa (opcional)","ids":["papel","boligrafos"],"opcional":true}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Si una imagen resulta incómoda, se puede abrir los ojos, volver a la respiración o dejar la visualización y descansar.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["jardin-de-las-emociones","el-poder-de-las-emociones"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles — algunas emociones, especialmente la tristeza y el enojo, pueden emerger con fuerza durante este viaje.","origen":"fuente"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"El mapa emocional del viaje","tipo":"lista","items":["Tristeza — Profundidad, necesidad de cuidado","Enojo — Energía, límites, protección","Miedo — Alerta, vulnerabilidad, necesidad","Confusión — Tránsito, búsqueda, apertura","Alegría — Expansión, gratitud, presencia","Calma — Integración, tierra, descanso"],"nota":"No es necesario recorrer todas las emociones. Elige aquellas que resonan con el momento del grupo o déjate guiar por lo que emerge durante la práctica."},{"titulo":"Preguntas de navegación emocional","tipo":"preguntas","items":["¿Dónde sientes esta emoción en tu cuerpo?","¿Qué necesita esta emoción para sentirse escuchada?","¿Qué mensaje trae consigo?"]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Invita al grupo a recostarse o sentarse cómodamente. Guía unas respiraciones profundas y presenta la intención: explorar las emociones como territorios que visitar, no como estados que evitar o corregir."],"citas":[],"preguntas":[],"nota":null},{"id":"viaje-emocional-guiado","nombre":"Viaje emocional guiado","tipo":"desarrollo","tiempo":{"min":30,"max":40,"texto":"30 – 40 minutos"},"pasos":["Recorre las emociones del mapa de forma pausada. En cada una, invita a sentir dónde aparece en el cuerpo y qué necesita ser escuchado, usando las tres preguntas de navegación."],"citas":["Ninguna emoción es permanente. Todas son visitantes que traen información valiosa sobre lo que necesitamos."],"preguntas":[],"nota":null},{"id":"integracion-creativa","nombre":"Integración creativa","tipo":"integracion","tiempo":{"min":10,"max":12,"texto":"10 – 12 minutos"},"pasos":["Invita a los participantes a expresar lo que vivieron — a través de escritura, dibujo o color — sin estructura ni expectativas. Lo que emerge en este momento tiene su propio lenguaje."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Regresa al cuerpo con una respiración consciente. Quienes lo deseen pueden compartir qué emoción fue la más reveladora y qué mensaje recibieron de ella."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Presenta cada emoción como un territorio a explorar, no como un problema — ese encuadre cambia completamente la disposición del grupo.","origen":"fuente"},{"texto":"La integración creativa al final es clave — no la omitas aunque el tiempo apriete; es donde el viaje se transforma en aprendizaje concreto.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[63,64],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Intermedio; energía: Receptiva · Profunda."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":53,"max":65},"orden":28},{"id":"circulo-de-silencio-consciente","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Silencio Consciente","subtitulo":"Una experiencia para habitar el silencio como práctica de presencia y conexión interior","resumen":"Una experiencia para habitar el silencio como práctica de presencia y conexión interior","contexto":"En un mundo saturado de palabras e información, el silencio consciente se ha convertido en una práctica radical. Esta dinámica invita al grupo a habitar juntos el silencio — no como ausencia, sino como una forma activa de presencia, escucha y conexión interior.","objetivo":"Crear un espacio de silencio compartido donde los participantes puedan descansar del lenguaje, conectar con su mundo interior y descubrir lo que el silencio tiene para decirles.","momentos":["integracion","apertura"],"temas":["silencio","presencia","círculo"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Quieta · Profunda","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio íntimo en círculo","ids":[],"opcional":false},{"texto":"Vela central como foco de presencia","ids":["vela-central"],"opcional":false},{"texto":"Sin música — el silencio es el sonido","ids":["musica"],"opcional":false},{"texto":"Papel para escritura posterior (opcional)","ids":["papel"],"opcional":true}],"ambiente":["Espacio íntimo en círculo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["circulo-de-presencia","meditacion-respiracion-consciente"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Los tres niveles del silencio","tipo":"lista","items":["Silencio exterior · Primer nivel — Callar el ruido externo. Dejar de hablar, de moverse, de producir sonido. El silencio como pausa del mundo.","Silencio mental · Segundo nivel — Observar los pensamientos sin seguirlos. No silenciar la mente — solo no alimentar cada pensamiento que aparece.","Silencio interior · Tercer nivel — El espacio entre pensamientos. La quietud que existe debajo de toda agitación. Donde la escucha interior se vuelve posible."]},{"titulo":"Frases para introducir el silencio","tipo":"frases","items":["El silencio no está vacío — está lleno de respuestas.","No necesitas hacer nada — solo estar.","Permite que el silencio te encuentre."]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Reúne al grupo en círculo con una vela al centro. Introduce los tres niveles del silencio y presenta la intención: habitar juntos el silencio como práctica consciente y no como incomodidad a evitar."],"citas":[],"preguntas":[],"nota":null},{"id":"silencio-compartido","nombre":"Silencio compartido","tipo":"desarrollo","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["Después de las frases de entrada, el grupo permanece en silencio colectivo. No hay guía verbal — solo la vela, la respiración y la presencia compartida."],"citas":["Estar en silencio junto a otros sin necesidad de llenarlo — eso también es una forma profunda de conexión."],"preguntas":[],"nota":"Si alguien siente incomodidad o necesita moverse, está bien: avísales antes del silencio que eso también es parte de la práctica. No existe un silencio perfecto."},{"id":"salida-gradual","nombre":"Salida gradual","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Marca el regreso con un sonido suave — una campana, el cuenco o simplemente tu voz suave. Invita a los participantes a respirar profundo y regresar poco a poco al espacio compartido."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Abre un pequeño espacio para compartir — desde el silencio hacia las palabras — qué surgió, qué se escuchó o qué se sintió durante la práctica."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Normaliza la incomodidad del silencio antes de comenzar — muchas personas nunca han estado en silencio consciente con otros y pueden sentir ansiedad al inicio.","origen":"fuente"},{"texto":"Tú también entra en el silencio — no lo observes desde afuera. Tu presencia silenciosa sostiene el espacio mejor que cualquier palabra.","origen":"fuente"},{"texto":"Cuanto más experiencia tenga el grupo con la meditación, más larga puede ser la fase de silencio — ajusta el tiempo según el nivel del grupo.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[65,66],"rol":"principal"},{"archivo":"edicion2","paginas":[68,69],"rol":"contraste"}],"correcciones":[{"campo":"desarrollo.silencio-compartido.nota","original":"Si alguien siente incomodidad o necesita moverse, está bien — animales antes del silencio a que eso también es parte de la práctica.","corregido":"Si alguien siente incomodidad o necesita moverse, está bien: avísales antes del silencio que eso también es parte de la práctica.","motivo":"Redacción defectuosa en la fuente («animales antes del silencio a que»); se corrige conservando el sentido."}],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Quieta · Profunda."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":58},"orden":29},{"id":"camino-de-la-confianza","version":1,"estado":"revision","motivoEstado":"Requiere revisión especializada: incluye desplazamiento con ojos cubiertos y una «caída de confianza» (variante C) con riesgo de lesión.","titulo":"Camino de la Confianza","subtitulo":"Una experiencia para cultivar la confianza en uno mismo, en los demás y en el proceso de la vida","resumen":"Una experiencia para cultivar la confianza en uno mismo, en los demás y en el proceso de la vida","contexto":"Confiar es uno de los actos más valientes que podemos practicar. Esta dinámica invita a los participantes a explorar la confianza desde una experiencia corporal y relacional — aprendiendo a guiar y a dejarse guiar, a sostener y a ser sostenido.","objetivo":"Desarrollar la confianza interpersonal y la autoconfianza a través de experiencias corporales de guiar y ser guiado, cultivando presencia, responsabilidad y vulnerabilidad consciente.","momentos":["conexion"],"temas":["confianza","parejas","movimiento"],"formato":["parejas","grupo"],"tipoFuente":"Parejas · Movimiento","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Vincular · Transformadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"ambos","amplio":true,"texto":"Amplio · Despejado"},"participantes":null,"materiales":[{"texto":"Espacio amplio y despejado de obstáculos","ids":[],"opcional":false},{"texto":"Vendas o pañuelos para cubrir los ojos","ids":["vendas"],"opcional":false},{"texto":"Música suave de fondo (instrumental)","ids":["musica"],"opcional":false},{"texto":"Espacio exterior con naturaleza (opcional)","ids":[],"opcional":true}],"ambiente":["Espacio amplio y despejado de obstáculos","Espacio exterior con naturaleza (opcional)"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien no quiera trabajar en pareja puede hacer la práctica de forma individual o acompañar como observador.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Detén el recorrido si alguien con los ojos cubiertos muestra miedo o pierde el equilibrio; puede seguir con los ojos abiertos.","origen":"adaptacion"},{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["el-puente-de-la-confianza","respiracion-en-pareja"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Inspecciona el espacio antes — retira todo lo que pueda representar un tropiezo o peligro para quienes caminan con los ojos cubiertos.","origen":"fuente"}],"experiencia":"avanzada","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Variantes del ejercicio","tipo":"lista","items":["A · Guía con venda — Una persona con los ojos cubiertos es guiada por la otra solo con el contacto suave de su mano u hombro. Sin palabras.","B · Guía con voz — La persona con los ojos cubiertos es guiada únicamente por la voz pausada de su compañero, sin contacto físico.","C · Caída de confianza — En círculo, una persona cae hacia atrás con los ojos cerrados y el grupo la sostiene. Experiencia de confiar en el colectivo."],"nota":"Puedes usar una sola variante o combinarlas según el tiempo y el nivel de confianza del grupo. La Variante C requiere mayor cohesión grupal previa."},{"titulo":"Frases para acompañar","tipo":"frases","items":["Guiar también es una responsabilidad de cuidado.","Dejarse guiar es una forma de valentía.","La confianza no es ausencia de miedo — es elegir avanzar de todas formas."]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Presenta la intención y explica la dinámica con claridad. Forma las parejas o el círculo. Refuerza las instrucciones de seguridad — el que guía es completamente responsable del que es guiado."],"citas":[],"preguntas":[],"nota":null},{"id":"ejercicio-de-confianza","nombre":"Ejercicio de confianza","tipo":"desarrollo","tiempo":{"min":20,"max":30,"texto":"20 – 30 minutos"},"pasos":["Realiza la variante elegida durante varios minutos. Luego invita a intercambiar roles para que ambas personas experimenten guiar y ser guiados."],"citas":["Observa lo que surge en ti al guiar. Observa lo que surge en ti al entregarte."],"preguntas":[],"nota":null},{"id":"reflexion-en-parejas","nombre":"Reflexión en parejas","tipo":"integracion","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Invita a cada pareja a compartir brevemente entre sí cómo se sintieron en cada rol — qué fue más fácil, qué generó resistencia y qué descubrieron sobre su relación con la confianza."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre-grupal","nombre":"Cierre grupal","tipo":"cierre","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Reúne al grupo para compartir las reflexiones más significativas. Cierra con una pregunta integradora: ¿en qué área de tu vida necesitas cultivar más confianza?"],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Recuerda antes de comenzar: quien guía tiene responsabilidad total sobre la seguridad de quien es guiado. Eso también es parte del aprendizaje.","origen":"fuente"},{"texto":"Si alguien tiene dificultad física o emocional para participar, ofrece siempre la opción de observar — la observación consciente también enseña sobre la confianza.","origen":"fuente"}],"variantes":[{"id":"ed2-32","titulo":"Versión de un solo formato, sin caída de confianza (Edición 2)","tituloFuente":"Camino de la Confianza","estado":"revision","fuente":{"archivo":"edicion2","paginas":[70,71]},"nota":"Versión con un único formato: recorrido corto con ojos cerrados acompañado por la pareja; sin caída de confianza.","subtitulo":null,"contexto":null,"fases":[]}],"fuentes":[{"archivo":"principal","paginas":[67,68],"rol":"principal"},{"archivo":"edicion2","paginas":[70,71],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Vincular · Transformadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":44,"max":56},"orden":30},{"id":"ceremonia-de-la-luz-interior","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Ceremonia de la Luz Interior","subtitulo":"Un espacio sagrado para reconocer, honrar y celebrar la luz que cada persona lleva dentro","resumen":"Un espacio sagrado para reconocer, honrar y celebrar la luz que cada persona lleva dentro","contexto":"A veces necesitamos que alguien más vea nuestra luz para comenzar a creer en ella. Esta ceremonia invita al grupo a crear un espacio de reconocimiento mutuo donde cada persona pueda ser vista, honrada y celebrada por la luz que aporta al mundo.","objetivo":"Crear un espacio ceremonial donde cada participante pueda ser reconocido y celebrado por el grupo, fortaleciendo la autoestima, la conexión y el sentido de pertenencia al finalizar el retiro.","momentos":["cierre"],"temas":["reconocimiento","ritual","velas"],"formato":["grupo"],"tipoFuente":"Grupal · Ritual","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Celebratoria · Sagrada","momentoFuente":"Cierre del retiro","enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Una vela por participante","ids":["velas-individuales"],"opcional":false},{"texto":"Vela central más grande como foco","ids":["vela-central"],"opcional":false},{"texto":"Papeles o tarjetas para mensajes escritos","ids":["papel","tarjetas"],"opcional":false},{"texto":"Música suave o cuenco tibetano para marcar momentos","ids":["cuenco-campana","musica"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien prefiera no recibir reconocimiento en voz alta puede pedir recibirlo en silencio o por escrito.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Al cierre del retiro, cuando el grupo ya se conoce lo suficiente para que el reconocimiento sea genuino y profundo.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["circulo-de-reconocimiento-y-alabanza","circulo-de-cierre-del-retiro"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Actos de reconocimiento de la ceremonia","tipo":"lista","items":["Encendido de vela personal — Cada participante enciende su vela desde la vela central como símbolo de llevar la luz propia hacia afuera.","Reconocimiento verbal — El grupo comparte en voz alta qué luz vio brillar en cada persona durante el retiro — una cualidad, un momento, un gesto.","Carta de luz — Cada participante escribe un mensaje breve a otro integrante del grupo reconociendo algo que vio brillar en él o ella durante la experiencia."],"nota":"Puedes combinar los tres actos o elegir solo uno según el tiempo disponible. El reconocimiento verbal en círculo suele ser el más poderoso e impactante."},{"titulo":"Frases para acompañar la ceremonia","tipo":"frases","items":["Cada uno de nosotros lleva una luz que el mundo necesita.","Ser visto por otros también es una forma de reconocerte a ti mismo.","La luz que honramos en los demás también vive en nosotros."]}],"fases":[{"id":"apertura-ceremonial","nombre":"Apertura ceremonial","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Prepara el espacio con las velas apagadas distribuidas en círculo. Enciende la vela central y guía unas respiraciones profundas. Introduce la intención: crear un espacio donde cada persona sea vista y celebrada."],"citas":[],"preguntas":[],"nota":null},{"id":"actos-de-reconocimiento","nombre":"Actos de reconocimiento","tipo":"desarrollo","tiempo":{"min":35,"max":45,"texto":"35 – 45 minutos"},"pasos":["Recorre los actos elegidos de forma pausada. En el reconocimiento verbal, da tiempo suficiente para que cada persona reciba las palabras del grupo en silencio y desde la presencia."],"citas":["Recibir el reconocimiento de los demás sin desviarlo también es un acto de amor propio."],"preguntas":[],"nota":"Invita a quien recibe el reconocimiento a simplemente escuchar y respirar — sin minimizar ni desviar lo que el grupo ve en ellos. Recibir también es una práctica."},{"id":"cierre-de-la-ceremonia","nombre":"Cierre de la ceremonia","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Finaliza con todas las velas encendidas en círculo. Guía un momento de silencio para contemplar la luz colectiva. Cierra con una respiración compartida y una palabra de gratitud grupal."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Comienza tú el reconocimiento verbal — modela cómo se hace: específico, sincero y desde lo que realmente observaste en esa persona durante el retiro.","origen":"fuente"},{"texto":"Invita a quien recibe a no desviar ni minimizar lo que escucha — muchas personas tienden a hacerlo por incomodidad con el reconocimiento. Esa también es una práctica.","origen":"fuente"},{"texto":"Esta ceremonia funciona mejor al cierre del retiro — cuando el grupo ya se conoce lo suficiente para que el reconocimiento sea genuino y profundo.","origen":"fuente"}],"variantes":[{"id":"ed2-33","titulo":"Variante de luz propia (Edición 2)","tituloFuente":"Ceremonia de la Luz Interior","estado":"revision","fuente":{"archivo":"edicion2","paginas":[72,73]},"nota":"Enfoque distinto: cada persona enciende su vela y nombra su propia luz; el principal propone reconocimiento del grupo hacia cada persona.","subtitulo":null,"contexto":null,"fases":[]}],"fuentes":[{"archivo":"principal","paginas":[69,70],"rol":"principal"},{"archivo":"edicion2","paginas":[72,73],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Celebratoria · Sagrada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":65},"orden":31},{"id":"respiracion-en-pareja","version":1,"estado":"revision","motivoEstado":"Requiere revisión especializada: incluye un ritmo con retención (4·2·6), respiración alternada y una postura con la mano en el pecho del compañero. La Edición 2 trae una versión sin retención ni contacto (variante pendiente).","titulo":"Respiración en Pareja","subtitulo":"Una práctica de sincronía, presencia y conexión profunda a través del aliento compartido","resumen":"Una práctica de sincronía, presencia y conexión profunda a través del aliento compartido","contexto":"La respiración es lo primero que compartimos al nacer y lo último que soltamos. Esta práctica invita a dos personas a sincronizar su aliento conscientemente, creando un momento de conexión profunda que va más allá de las palabras y los pensamientos.","objetivo":"Desarrollar la presencia, la sincronía y la conexión interpersonal a través de la respiración consciente compartida, cultivando un estado de apertura y confianza mutua.","momentos":["conexion"],"temas":["respiración","parejas","presencia"],"formato":["parejas"],"tipoFuente":"Parejas · Respiración","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Vincular · Presencial","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas o cojines para las parejas","ids":["cojines-esterillas"],"opcional":false},{"texto":"Música suave sin letra (instrumental)","ids":["musica"],"opcional":false},{"texto":"Espacio íntimo con suficiente distancia entre parejas","ids":[],"opcional":false},{"texto":"Campana o cuenco para marcar transiciones","ids":["cuenco-campana"],"opcional":false}],"ambiente":["Espacio íntimo con suficiente distancia entre parejas"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien no quiera trabajar en pareja puede hacer la práctica de forma individual o acompañar como observador.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien se marea o se incomoda con la respiración, vuelvan a la respiración natural antes de continuar.","origen":"adaptacion"},{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["circulo-de-espejos","camino-de-la-confianza"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"avanzada","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Posturas posibles para la práctica","tipo":"lista","items":["Espalda con espalda · Más accesible — Sentados espalda contra espalda, sintiendo el movimiento de la respiración del otro a través del contacto físico.","Frente a frente · Más íntimo — Sentados frente a frente con los ojos cerrados o abiertos, sincronizando la respiración desde la observación mutua.","Mano en el pecho · Más visceral — Cada persona coloca su mano en el pecho del otro, sintiendo directamente el movimiento de su respiración."]},{"titulo":"Ritmos de respiración para explorar","tipo":"lista","items":["Respiración natural · 4 · 4 — Inhalar 4 — exhalar 4. Simple y calmante para comenzar.","Respiración profunda · 4 · 2 · 6 — Inhalar 4 — retener 2 — exhalar 6. Calma el sistema nervioso.","Respiración alternada · ↑↓↑↓ — Una persona inhala mientras la otra exhala. Crea sincronía complementaria."]},{"titulo":"Frases para acompañar la práctica","tipo":"frases","items":["Permite que tu respiración se encuentre con la del otro.","No es necesario hacer nada — solo respirar juntos.","Siente la presencia del otro a través de tu aliento."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Forma las parejas y elige la postura. Invita a cada persona a conectar primero con su propia respiración individual durante un par de minutos antes de comenzar a sincronizar con su compañero."],"citas":[],"preguntas":[],"nota":null},{"id":"respiracion-sincronizada","nombre":"Respiración sincronizada","tipo":"desarrollo","tiempo":{"min":15,"max":25,"texto":"15 – 25 minutos"},"pasos":["Guía al grupo a través de los ritmos de respiración elegidos. Permite que cada ritmo dure entre 3 y 5 minutos antes de transicionar al siguiente."],"citas":["A veces, compartir la respiración con otro ser humano es suficiente para sentirse menos solos en el mundo."],"preguntas":[],"nota":"Si alguien siente mareo o incomodidad, anímale a volver a su respiración natural y a sentarse erguido. Esto es completamente normal al inicio."},{"id":"cierre-en-silencio","nombre":"Cierre en silencio","tipo":"cierre","tiempo":{"min":3,"max":5,"texto":"3 – 5 minutos"},"pasos":["Deja unos minutos de silencio al finalizar para que la pareja permanezca en contacto antes de volver al espacio grupal. No hay prisa por separarse."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Reúne al grupo para compartir brevemente qué surgió durante la práctica — sensaciones, emociones, descubrimientos sobre la conexión con el otro."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Forma las parejas con intención — personas que no se conocen bien pueden vivir una conexión especialmente significativa en esta práctica.","origen":"fuente"},{"texto":"Comienza siempre con el ritmo más simple (4·4) y aumenta la complejidad progresivamente — no empieces con la respiración alternada.","origen":"fuente"},{"texto":"Deja espacio suficiente entre las parejas para que la intimidad de la práctica no se vea interrumpida por la proximidad de otros.","origen":"fuente"}],"variantes":[{"id":"ed2-34","titulo":"Versión sin retención ni contacto (Edición 2)","tituloFuente":"Respiración en Pareja","estado":"revision","fuente":{"archivo":"edicion2","paginas":[74,75]},"nota":"Versión sin retención ni contacto: parejas frente a frente que observan la respiración del otro y encuentran un ritmo compartido de forma natural.","subtitulo":"Una experiencia para conectar con la presencia, la empatía y el ritmo compartido","contexto":"La respiración también puede convertirse en una forma de conexión. Esta dinámica invita a los participantes a compartir un momento de presencia consciente junto a otra persona, favoreciendo la escucha, la calma y la sincronía emocional.","fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Invita al grupo a formar parejas y sentarse frente a frente en una posición cómoda y relajada. Crea un ambiente tranquilo, acompañado de música suave o silencio consciente para favorecer la concentración y la conexión.","Comienza guiando unas respiraciones lentas y profundas para ayudar a relajar el cuerpo y entrar en el momento presente.","Después, invita a las parejas a observar suavemente la respiración del otro sin necesidad de hablar. Poco a poco, permite que encuentren un ritmo compartido de manera natural, sin forzarlo.","Después de algunos minutos, invita a las parejas a cerrar los ojos y continuar respirando juntos desde la escucha y la tranquilidad.","Al finalizar, abre un pequeño espacio para compartir cómo se sintieron durante la experiencia y qué emociones o sensaciones aparecieron."],"citas":["Respira sin prisa.","Permite que el momento se vuelva más simple.","A veces, la conexión también ocurre en silencio."],"preguntas":[],"nota":"La intención no es “respirar perfecto”, sino experimentar cómo cambia la conexión cuando realmente prestamos atención al otro desde la calma y la presencia."}]}],"fuentes":[{"archivo":"principal","paginas":[71,72],"rol":"principal"},{"archivo":"edicion2","paginas":[74,75],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Vincular · Presencial."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":28,"max":46},"orden":32},{"id":"red-de-la-vida","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Red de la Vida","subtitulo":"Una experiencia para descubrir y celebrar la interdependencia que nos une a todos","resumen":"Una experiencia para descubrir y celebrar la interdependencia que nos une a todos","contexto":"Nada existe de forma aislada. Cada persona, cada experiencia y cada relación forma parte de una red invisible que nos conecta y nos sostiene. Esta dinámica invita al grupo a descubrir y celebrar visualmente esa interdependencia que nos une como seres humanos.","objetivo":"Hacer visible la red de conexiones, influencias y vínculos que une al grupo, cultivando el sentido de pertenencia, gratitud e interdependencia consciente.","momentos":["conexion","cierre"],"temas":["interdependencia","grupo","gratitud"],"formato":["grupo"],"tipoFuente":"Grupal · Vivencial","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Unificadora · Celebratoria","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior","amplio":true},"participantes":null,"materiales":[{"texto":"Un ovillo de lana o hilo resistente","ids":["ovillo"],"opcional":false},{"texto":"Espacio amplio en círculo de pie o sentados","ids":[],"opcional":false},{"texto":"Música suave de fondo","ids":["musica"],"opcional":false},{"texto":"Papel para reflexión escrita al finalizar (opcional)","ids":["papel"],"opcional":true}],"ambiente":["Espacio amplio en círculo de pie o sentados"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["mandala-colectivo","dinamica-de-conexion-humana"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Usa un hilo resistente y de color visible — preferiblemente dorado, blanco o rojo para que la red sea hermosa de contemplar cuando esté completa.","origen":"fuente"}],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Lo que se comparte al pasar el hilo","tipo":"lista","items":["Algo que aprendiste de alguien presente aquí","Una cualidad que admiras en quien recibe el hilo","Un momento compartido durante el retiro","Cómo esa persona contribuyó a tu experiencia"],"nota":"No es necesario usar siempre el mismo tipo de mensaje — el facilitador puede elegir una categoría para toda la ronda o dejar que cada persona elija libremente."},{"titulo":"Preguntas de integración","tipo":"preguntas","items":["¿Qué sientes al ver la red que construyeron juntos?","¿A qué otras redes de tu vida te recuerda esta imagen?","¿Qué responsabilidad sientes hacia las conexiones que sostienes en tu vida?"]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Organiza al grupo en círculo. Presenta el ovillo y explica que cada vez que alguien lo lanza a otra persona, sostiene una parte del hilo y comparte algo de las opciones de la tabla superior."],"citas":[],"preguntas":[],"nota":null},{"id":"tejiendo-la-red","nombre":"Tejiendo la red","tipo":"desarrollo","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["El primer participante sostiene el extremo del hilo y lanza el ovillo a quien desee dentro del círculo, compartiendo algo de las opciones. Quien recibe sostiene su porción y lanza a otra persona. Así se va tejiendo la red visible del grupo."],"citas":["Observen la red que han creado juntos — cada hilo es una conexión real que existió durante este retiro."],"preguntas":[],"nota":null},{"id":"contemplacion-de-la-red","nombre":"Contemplación de la red","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Cuando todos estén conectados, invita al grupo a observar la red en silencio. Luego pide que una persona tire suavemente del hilo — todos sentirán el movimiento. Así se hace visible la interdependencia."],"citas":[],"preguntas":[],"nota":"Este momento de tirar suavemente del hilo suele ser el más impactante de toda la dinámica — el grupo descubre físicamente que están conectados."},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Invita a compartir qué sintieron al ver la red y al sentir el movimiento del hilo. Cierra con las preguntas de integración de la sección inferior."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Asegúrate de que todos reciban el hilo al menos una vez — si alguien queda sin ser elegido, genera exclusión justo en la dinámica de conexión.","origen":"fuente"},{"texto":"No cortes el hilo al finalizar — invita al grupo a enrollarlo juntos como acto de cierre consciente de la red que construyeron.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[73,74],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Unificadora · Celebratoria."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":58},"orden":33},{"id":"meditacion-del-sonido-interior","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Meditación del Sonido Interior","subtitulo":"Una práctica de vocalización consciente para reconectar con la vibración propia del ser","resumen":"Una práctica de vocalización consciente para reconectar con la vibración propia del ser","contexto":"La voz es uno de los instrumentos más poderosos y menos utilizados conscientemente. Esta práctica invita a los participantes a explorar el sonido que emerge desde su propio interior — no para cantar bien, sino para vibrar auténticamente y conectar con la resonancia de su propio ser.","objetivo":"Desarrollar la conciencia sobre la voz como herramienta de sanación y expresión, liberando bloqueos emocionales a través de la vocalización consciente y la resonancia corporal.","momentos":["exploracion","apertura"],"temas":["voz","sonido","mantras"],"formato":["grupo"],"tipoFuente":"Grupal · Vocalización","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Vibrante · Liberadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio con buena acústica o en naturaleza","ids":[],"opcional":false},{"texto":"Cojines o esterillas para sentarse","ids":["cojines-esterillas"],"opcional":false},{"texto":"Sin música — el sonido del grupo es el ambiente","ids":["musica"],"opcional":false},{"texto":"Papel para reflexión escrita al finalizar (opcional)","ids":["papel"],"opcional":true}],"ambiente":["Espacio con buena acústica o en naturaleza"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien prefiera no vocalizar puede escuchar en silencio y respirar con el grupo.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["bano-de-sonido-y-relajacion"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Busca un espacio con buena acústica — una sala con paredes de piedra, madera o un espacio al aire libre amplifica la experiencia de resonancia colectiva.","origen":"fuente"}],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Capas de escucha del sonido interior","tipo":"lista","items":["El silencio interior · Primer nivel — Antes del sonido, el silencio. Observar el espacio interior antes de emitir cualquier vocalización.","La respiración sonora · Segundo nivel — Dejar que la exhalación tenga sonido natural — sin forzar, sin modelar. El sonido que emerge espontáneamente.","La vocalización plena · Tercer nivel — Emitir sonidos vocálicos o mantras conscientes, permitiendo que el cuerpo resuene con la vibración propia.","El sonido colectivo · Cuarto nivel — Las voces del grupo se encuentran y crean una resonancia compartida. La voz individual se convierte en algo mayor."]},{"titulo":"Vocalizaciones y mantras para explorar","tipo":"lista","items":["OM · Conexión · Todo el cuerpo","AH · Apertura · Pecho y corazón","HU · Elevación · Coronilla"],"nota":"No es necesario conocer la tradición de cada mantra — lo importante es la intención y la resonancia física que produce en el cuerpo al vocalizarlo."},{"titulo":"Frases para acompañar la práctica","tipo":"frases","items":["No se trata de cantar bien — se trata de vibrar auténticamente.","Permite que el sonido emerja sin censura ni corrección.","Siente la vibración de tu voz resonando dentro de ti."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Invita al grupo a sentarse en círculo y cerrar los ojos. Explica que no hay una manera correcta de vocalizarse — solo una manera auténtica. Guía unas respiraciones para soltar la vergüenza y el juicio."],"citas":[],"preguntas":[],"nota":null},{"id":"recorrido-por-las-capas","nombre":"Recorrido por las capas","tipo":"desarrollo","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["Guía al grupo a través de las cuatro capas de la tabla superior: silencio interior, respiración sonora, vocalización plena y sonido colectivo. Dedica varios minutos a cada una antes de avanzar."],"citas":["Tu voz no necesita ser perfecta para sanar — necesita ser tuya."],"preguntas":[],"nota":null},{"id":"mantras-colectivos","nombre":"Mantras colectivos","tipo":"desarrollo","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Guía al grupo a vocalizar juntos los mantras del grid superior. Empieza con OM durante varios minutos, luego AH y finalmente HU. Permite que el sonido colectivo llene el espacio."],"citas":[],"preguntas":[],"nota":"Al finalizar cada mantra, invita al grupo a permanecer en silencio unos instantes escuchando el eco que permanece en el espacio — esa pausa también es parte del sonido."},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Regresa al silencio antes de abrir los ojos. Quienes lo deseen pueden compartir cómo se sintieron al vocalizar — qué surgió, qué se liberó, qué descubrieron de su propia voz."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Vocaliza tú primero — tu disposición a usar tu propia voz sin vergüenza abre el permiso para que el grupo haga lo mismo.","origen":"fuente"},{"texto":"Recuerda antes de comenzar que no se trata de cantar bien — esa liberación del juicio es el primer y más importante paso de toda la práctica.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[75,76],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"separador","severidad":"media","detalle":"El separador de la página 75 dice «36. Red de la Vida», pero la ficha desarrolla «Meditación del Sonido Interior». Se usa el título de la ficha."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Vibrante · Liberadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":61},"orden":34},{"id":"ley-de-la-atraccion-consciente","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Ley de la Atracción Consciente","subtitulo":"Una experiencia para aprender a crear realidad desde la intención, la emoción y la acción alineada","resumen":"Una experiencia para aprender a crear realidad desde la intención, la emoción y la acción alineada","contexto":"Más allá de las interpretaciones populares, la ley de la atracción tiene un núcleo poderoso: aquello en lo que ponemos nuestra atención, energía y acción consistente tiende a expandirse en nuestra vida. Esta dinámica invita a los participantes a trabajar con esa ley desde la consciencia, la emoción y la responsabilidad personal.","objetivo":"Invitar a los participantes a explorar cómo sus pensamientos habituales, creencias y estados emocionales influyen en las experiencias que crean, desarrollando una relación más consciente con su poder creador.","momentos":["exploracion","integracion"],"temas":["intención","creencias","acción"],"formato":["individual"],"tipoFuente":"Individual · Reflexión","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Expansiva · Creadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Música inspiradora de fondo","ids":["musica"],"opcional":false},{"texto":"Tarjetas o cartulinas para escribir intenciones","ids":["papel-grande","tarjetas"],"opcional":false},{"texto":"Espacio cómodo e íntimo","ids":[],"opcional":false}],"ambiente":["Espacio cómodo e íntimo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["mapa-de-suenos-e-intenciones","neurociencia-de-la-transformacion"],"notasAdmin":["La recomendación 01 sugiere presentarla «desde la psicología y la neurociencia»: conviene revisar que el encuadre no se presente como evidencia científica."],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Los 3 pilares de la atracción consciente","tipo":"lista","items":["Pilar 01 · Claridad — Saber con precisión qué deseas crear. La mente atrae lo que ve con nitidez, no lo que imagina vagamente.","Pilar 02 · Emoción — Sentir como si ya existiera. La emoción es el combustible que activa el proceso creador y da energía a la intención.","Pilar 03 · Acción — Moverse en la dirección de lo que se desea. La atracción no reemplaza la acción — la orienta y la amplifica."]},{"titulo":"Áreas de vida para explorar","tipo":"lista","items":["Bienestar emocional","Relaciones y vínculos","Crecimiento personal","Propósito y trabajo","Abundancia y recursos","Espiritualidad y sentido"]},{"titulo":"Preguntas guía para la reflexión","tipo":"preguntas","items":["¿En qué pongo más energía, atención y pensamiento de forma habitual?","¿Qué creencias tengo sobre lo que merezco o puedo crear?","¿Qué pequeña acción podría tomar hoy que esté alineada con lo que deseo crear?"],"nota":"La segunda pregunta suele ser la más reveladora — muchas personas descubren creencias limitantes que operan por debajo de sus intenciones conscientes."}],"fases":[{"id":"marco-conceptual","nombre":"Marco conceptual","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Presenta los tres pilares de forma clara y accesible, sin misticismo innecesario. Enfatiza que la atracción consciente es un proceso activo — no pasivo — que combina pensamiento, emoción y acción."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-individual","nombre":"Reflexión individual","tipo":"integracion","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a cada participante a elegir una o dos áreas de vida y explorarlas con las preguntas guía. Anima a escribir con honestidad — especialmente sobre las creencias que pueden estar limitando el proceso."],"citas":["Lo que creemos que merecemos suele ser más limitante que lo que el mundo está dispuesto a ofrecernos."],"preguntas":[],"nota":null},{"id":"intencion-escrita","nombre":"Intención escrita","tipo":"desarrollo","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Invita a cada participante a escribir en una tarjeta una intención clara, en tiempo presente, con la emoción de quien ya la está viviendo — como punto de anclaje después del retiro."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Quienes lo deseen comparten su intención con el grupo. Cierra recordando que la atracción consciente comienza con la primera acción alineada que tomemos después del retiro."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Presenta el tema desde la psicología y la neurociencia — el enfoque en creencias, estados emocionales y comportamientos hace la dinámica accesible y creíble para todos los perfiles.","origen":"fuente"},{"texto":"Evita el misticismo excesivo — la dinámica pierde credibilidad y excluye a participantes más racionales si se presenta como magia en lugar de como proceso consciente.","origen":"fuente"},{"texto":"Enfatiza siempre el tercer pilar — la acción. Sin ella, la atracción se convierte en pensamiento mágico. Con ella, se convierte en una herramienta real de transformación.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[77,78],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Expansiva · Creadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":60},"orden":35},{"id":"el-poder-de-las-emociones","version":1,"estado":"publicado","motivoEstado":null,"titulo":"El Poder de las Emociones","subtitulo":"Una experiencia para reconocer, comprender y transformar el mensaje de cada emoción","resumen":"Una experiencia para reconocer, comprender y transformar el mensaje de cada emoción","contexto":"Las emociones no son obstáculos — son información. Cada emoción lleva un mensaje sobre lo que necesitamos, lo que valoramos o lo que estamos viviendo. Esta dinámica invita a los participantes a aprender el lenguaje de sus emociones y a usarlas como brújula interior en lugar de temerlas o suprimirlas.","objetivo":"Desarrollar la inteligencia emocional de los participantes ayudándoles a reconocer, comprender y transformar el mensaje de sus emociones en información útil para su bienestar y crecimiento.","momentos":["exploracion"],"temas":["emociones","inteligencia emocional","escritura"],"formato":["individual"],"tipoFuente":"Individual · Reflexión","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Reveladora · Integradora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Música suave de fondo","ids":["musica"],"opcional":false},{"texto":"Espacio tranquilo e íntimo","ids":[],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":["Espacio tranquilo e íntimo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["jardin-de-las-emociones","viaje-de-las-emociones"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles — la culpa, el miedo y la tristeza son las emociones que con más frecuencia emergen con intensidad durante esta dinámica.","origen":"fuente"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"El poder de cada emoción — guía de referencia","tipo":"lista","items":["Tristeza — Mensaje: algo que importa ha cambiado o se ha perdido. Acción que invita: permitir el duelo, buscar apoyo.","Enojo — Mensaje: un límite ha sido cruzado o un valor, irrespetado. Acción que invita: establecer límites, tomar acción.","Miedo — Mensaje: hay una amenaza real o percibida que pide atención. Acción que invita: evaluar el riesgo, prepararse.","Alegría — Mensaje: estás alineado con algo que valoras profundamente. Acción que invita: amplificar, agradecer, compartir.","Culpa — Mensaje: hay algo que puede repararse o aprenderse. Acción que invita: reparar, aprender, soltar.","Calma — Mensaje: hay equilibrio y aceptación en este momento. Acción que invita: sostener, disfrutar, integrar."]},{"titulo":"Preguntas de reflexión personal","tipo":"preguntas","items":["¿Qué emoción aparece con más frecuencia en tu vida? ¿Qué mensaje lleva?","¿Qué emoción sueles reprimir o ignorar? ¿Qué podría estar tratando de decirte?","¿Qué cambiaría en tu vida si usaras tus emociones como información en lugar de resistirlas?"],"nota":"La segunda pregunta es la que más trabajo interior genera — la emoción que ignoramos suele ser la que más información importante guarda para nosotros."}],"fases":[{"id":"marco-conceptual","nombre":"Marco conceptual","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Presenta la idea central: las emociones no son problemas sino mensajeras. Introduce la tabla de referencia como un mapa para leer el lenguaje emocional con más claridad."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-individual","nombre":"Reflexión individual","tipo":"integracion","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a explorar las preguntas guía usando la tabla de referencia como apoyo. Permite el silencio y la música suave como compañía durante la escritura."],"citas":["Aprender el lenguaje de nuestras emociones es una de las habilidades más transformadoras que podemos desarrollar."],"preguntas":[],"nota":null},{"id":"practica-de-integracion","nombre":"Práctica de integración","tipo":"integracion","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Guía al grupo a identificar una emoción presente en este momento, localizarla en el cuerpo, reconocer su mensaje y explorar qué acción o cambio invita a tomar."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Quienes lo deseen comparten una reflexión o descubrimiento. Cierra recordando que cada emoción — incluso la más incómoda — lleva información valiosa para quien sabe escucharla."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Normaliza todas las emociones desde el inicio — no hay emociones \"buenas\" o \"malas\", solo mensajes más o menos incómodos de recibir.","origen":"fuente"},{"texto":"Si alguien se emociona durante la reflexión, recíbelo con calma — la emoción que aparece durante la práctica suele ser la que más necesitaba ser vista.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[79,80],"rol":"principal"}],"correcciones":[{"campo":"recomendaciones.1","original":"la emoción que aparece durante la práctica suele ser que más necesitaba ser vista.","corregido":"la emoción que aparece durante la práctica suele ser la que más necesitaba ser vista.","motivo":"Falta de artículo en la fuente."}],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Reveladora · Integradora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":53,"max":65},"orden":36},{"id":"circulo-de-reconocimiento-y-alabanza","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Reconocimiento y Alabanza","subtitulo":"Un espacio para ver, nombrar y celebrar lo que cada persona aporta al mundo","resumen":"Un espacio para ver, nombrar y celebrar lo que cada persona aporta al mundo","contexto":"Pocas cosas tienen el poder de transformar la autopercepción de una persona como ser visto y reconocido genuinamente por otros. Esta dinámica invita al grupo a crear un espacio de alabanza sincera — no de elogios vacíos, sino de reconocimiento real y específico de lo que cada persona aporta.","objetivo":"Crear un espacio de reconocimiento mutuo profundo y genuino donde cada participante pueda ser celebrado por el grupo a través de palabras específicas, sinceras y desde la presencia.","momentos":["cierre"],"temas":["reconocimiento","círculo","palabra"],"formato":["grupo"],"tipoFuente":"Grupal · Círculo","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Celebratoria · Vincular","momentoFuente":"Cierre del retiro","enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio en círculo con iluminación cálida","ids":[],"opcional":false},{"texto":"Vela central como foco de presencia","ids":["vela-central"],"opcional":false},{"texto":"Tarjetas o papeles para mensajes escritos (opcional)","ids":["papel","tarjetas"],"opcional":true},{"texto":"Música suave solo para la apertura","ids":["musica"],"opcional":false}],"ambiente":["Espacio en círculo con iluminación cálida"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien prefiera no recibir reconocimiento en voz alta puede pedir recibirlo en silencio o por escrito.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Cuando el grupo ha compartido al menos dos días juntos: el reconocimiento genuino requiere tiempo y experiencias vividas en conjunto.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["ceremonia-de-la-luz-interior","circulo-de-cierre-del-retiro"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Formas de reconocimiento posibles","tipo":"lista","items":["A · Reconocimiento verbal en círculo — El grupo comparte en voz alta lo que vio brillar en cada persona durante el retiro. Específico, sincero y desde la presencia.","B · Cartas de reconocimiento escritas — Cada persona escribe una carta breve a otro integrante del grupo nombrando algo concreto que admira o que le aportó durante la experiencia.","C · Una palabra para cada persona — Cada participante recibe una sola palabra de cada miembro del grupo — la que mejor capture su esencia o lo que aportó al colectivo."],"nota":"La Forma A es la más impactante emocionalmente cuando el grupo ya tiene confianza. La Forma C es la más accesible para grupos que aún están construyendo vínculos."},{"titulo":"Acuerdos del círculo","tipo":"lista","items":["El reconocimiento debe ser específico y sincero — no genérico ni por cumplir.","Quien recibe escucha sin desviar ni minimizar lo que le dicen — recibir también es una práctica.","El silencio después de cada reconocimiento honra lo que fue dicho — no hay prisa por continuar."]}],"fases":[{"id":"apertura-ceremonial","nombre":"Apertura ceremonial","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Crea el ambiente íntimo con vela encendida. Lee los tres acuerdos del círculo antes de comenzar. Guía una respiración de apertura para preparar tanto al que da como al que recibe."],"citas":[],"preguntas":[],"nota":null},{"id":"reconocimiento","nombre":"Reconocimiento","tipo":"desarrollo","tiempo":{"min":40,"max":50,"texto":"40 – 50 minutos"},"pasos":["Recorre al grupo con la forma elegida. Da tiempo suficiente a cada persona para recibir el reconocimiento en silencio antes de pasar a la siguiente."],"citas":["A veces necesitamos que otros nombren lo que nosotros aún no podemos ver de nosotros mismos."],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Finaliza con un momento de silencio contemplativo y una respiración colectiva. Invita a cada persona a llevarse consigo el reconocimiento recibido como parte de lo que vivió en el retiro."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Sé el primero en dar el ejemplo — modela cómo se da un reconocimiento específico y genuino, no genérico.","origen":"fuente"},{"texto":"Invita explícitamente a quien recibe a no minimizar ni desviar con humor — muchas personas hacen esto por incomodidad con el reconocimiento propio.","origen":"fuente"},{"texto":"Esta dinámica es más poderosa cuando el grupo ha compartido al menos dos días juntos — el reconocimiento genuino requiere tiempo y experiencias reales vividas en conjunto.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[81,82],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Celebratoria · Vincular."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":56,"max":66},"orden":37},{"id":"ritual-de-autoperdon","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Ritual de Autoperdón","subtitulo":"Una experiencia para soltar la culpa, honrar la propia humanidad y comenzar de nuevo","resumen":"Una experiencia para soltar la culpa, honrar la propia humanidad y comenzar de nuevo","contexto":"La culpa que cargamos hacia nosotros mismos suele ser la más pesada y la más silenciosa. Esta dinámica invita a los participantes a explorar el perdón más difícil — el autoperdón — como un acto de amor, responsabilidad y liberación personal.","objetivo":"Crear un espacio íntimo y seguro donde los participantes puedan explorar el autoperdón como un proceso de compasión hacia sí mismos, soltando la culpa que ya no sirve como aprendizaje.","momentos":["exploracion"],"temas":["autoperdón","culpa","ritual","escritura"],"formato":["individual"],"tipoFuente":"Individual · Ritual","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Profundo","energiaFuente":"Compasiva · Liberadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Velas e iluminación íntima","ids":["velas"],"opcional":false},{"texto":"Música suave de cuencos o piano","ids":["musica"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Ofrece siempre una alternativa sin fuego (romper, enterrar o guardar el papel) para quien prefiera no usarlo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"},{"texto":"Si el fuego se vuelve difícil de controlar (viento, chispas), suspende el acto con fuego y pasa a la alternativa sin fuego.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ritual-del-perdon","ritual-de-liberacion"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles y visibles — el autoperdón es la dinámica que con mayor frecuencia mueve lágrimas profundas e inesperadas.","origen":"fuente"},{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Las 3 capas del autoperdón","tipo":"lista","items":["Reconocer · Primera capa — Nombrar honestamente aquello que hiciste, dijiste o dejaste de hacer y que aún genera culpa o arrepentimiento en ti.","Comprender · Segunda capa — Reconocer el contexto, la etapa y los recursos que tenías en ese momento. Hiciste lo que pudiste con lo que sabías entonces.","Soltar · Tercera capa — Elegir conscientemente dejar de castigarte. El autoperdón no borra lo ocurrido — libera el peso que ya no necesitas cargar."]},{"titulo":"Preguntas para acompañar la reflexión","tipo":"preguntas","items":["¿Qué me has estado repitiendo sobre algo que hiciste o no hiciste?","¿Qué tenías disponible entonces — en recursos, conciencia y apoyo?","¿Qué necesitaría escuchar esa versión de ti para comenzar a soltar el peso?"],"nota":"La segunda pregunta es la más liberadora — comprender que en ese momento no tenías los mismos recursos o consciencia que hoy es el puente hacia el autoperdón genuino."},{"titulo":"Gestos simbólicos del ritual","tipo":"lista","items":["Colocar las manos sobre el corazón mientras se pronuncia internamente las palabras del autoperdón","Escribir una carta de autoperdón y luego romperla, quemarla o guardarla según lo que resuene","Una larga exhalación consciente — soltar el peso con cada respiración que se libera"]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Crea un ambiente íntimo y seguro. Introduce las tres capas del autoperdón y distingue claramente que perdonarse no es justificarse — es dejar de castigarse por algo que ya no puede cambiarse."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-y-escritura","nombre":"Reflexión y escritura","tipo":"integracion","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a explorar las tres preguntas guía en silencio y desde la escritura. Permite que el proceso ocurra a su propio ritmo — sin interrupciones ni presión."],"citas":["Perdonarte no significa que lo que pasó estuvo bien — significa que ya no estás dispuesto a seguir pagando por ello."],"preguntas":[],"nota":null},{"id":"gesto-ritual","nombre":"Gesto ritual","tipo":"desarrollo","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Invita al grupo a realizar el gesto simbólico que resuene con su proceso. Acompaña con música suave y presencia. Este es el momento de mayor intimidad de toda la dinámica."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion-y-cierre","nombre":"Integración y cierre","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Guía unas respiraciones profundas colectivas. Quienes lo deseen pueden compartir una reflexión. Cierra recordando que el autoperdón es un proceso — no una decisión que se toma una sola vez."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Distingue desde el inicio entre autoperdón y justificación — esa diferencia es el corazón de toda la dinámica y libera a los participantes para entrar sin culpa adicional.","origen":"fuente"},{"texto":"Recuerda al finalizar que el autoperdón es un proceso, no un evento — lo que comenzó hoy necesita ser cultivado con paciencia y compasión en los días siguientes.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[83,84],"rol":"principal"},{"archivo":"edicion2","paginas":[84,85],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Profundo; energía: Compasiva · Liberadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":60},"orden":38},{"id":"viaje-hindu-de-la-sabiduria-interior","version":1,"estado":"publicado","motivoEstado":null,"titulo":"El Viaje Hindú de la Sabiduría Interior","subtitulo":"Una exploración de Dharma, Karma y Moksha como guías del camino del alma","resumen":"Una exploración de Dharma, Karma y Moksha como guías del camino del alma","contexto":"La filosofía védica ofrece tres conceptos que, más allá de su origen espiritual, contienen una sabiduría profundamente aplicable a la vida contemporánea. Esta dinámica invita a los participantes a explorar su propio camino a través de la lente del Dharma, el Karma y el Moksha.","objetivo":"Invitar a los participantes a reflexionar sobre su propósito, sus patrones y su proceso de liberación interior a través de tres conceptos filosóficos de la sabiduría hindú.","momentos":["exploracion"],"temas":["propósito","filosofía","reflexión"],"formato":["individual","grupo"],"tipoFuente":"Individual · Reflexión","duracion":{"min":60,"max":90,"texto":"60 – 90 minutos"},"notaDuracion":null,"nivelFuente":"Intermedio","energiaFuente":"Filosófica · Expansiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Música india suave o cuencos de cristal","ids":["cuenco-campana","musica"],"opcional":false},{"texto":"Incienso o aromas naturales (opcional)","ids":["incienso"],"opcional":true},{"texto":"Espacio íntimo y tranquilo","ids":[],"opcional":false}],"ambiente":["Espacio íntimo y tranquilo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Quien prefiera no vocalizar puede escuchar en silencio y respirar con el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["mesa-redonda-sobre-valores","meditacion-del-sonido-interior"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Estudia brevemente los tres conceptos antes de facilitarlos — conocerlos en profundidad te permite responder preguntas del grupo con autenticidad.","origen":"fuente"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Los tres pilares de la sabiduría hindú","tipo":"lista","items":["Dharma · El propósito — La ley de la naturaleza propia. Aquello para lo que estamos aquí — nuestro propósito, vocación y contribución única al mundo. ¿Cuál es mi propósito más auténtico en esta vida?","Karma · La acción — La ley de causa y efecto. Cada acción, pensamiento e intención genera consecuencias que moldean nuestra experiencia presente y futura. ¿Qué patrones de acción necesito transformar?","Moksha · La liberación — La liberación del sufrimiento innecesario. El estado de paz que surge cuando dejamos de resistir la realidad y nos alineamos con lo que es. ¿De qué necesito liberarme para encontrar más paz?"]},{"titulo":"Preguntas de reflexión personal","tipo":"preguntas","items":["¿Estoy viviendo de acuerdo con mi Dharma — mi propósito más auténtico?","¿Qué patrones de Karma — de pensamiento, emoción o acción — sigo repitiendo?","¿Qué me impide alcanzar Moksha — esa paz interior que ya existe dentro de mí?"],"nota":"Presenta estos conceptos como herramientas de autoconocimiento, no como dogmas religiosos. Su valor está en las preguntas que generan, no en la creencia que requieren."}],"fases":[{"id":"marco-filosofico","nombre":"Marco filosófico","tipo":"apertura","tiempo":{"min":15,"max":15,"texto":"15 minutos"},"pasos":["Presenta los tres conceptos de forma accesible y sin dogmatismo. Usa la tabla de referencia y enfatiza que se trata de herramientas de reflexión, no de prácticas religiosas que requieran creencia."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-individual","nombre":"Reflexión individual","tipo":"integracion","tiempo":{"min":30,"max":40,"texto":"30 – 40 minutos"},"pasos":["Invita a cada participante a explorar los tres conceptos a través de las preguntas guía, dedicando tiempo similar a cada uno antes de avanzar al siguiente."],"citas":["El camino hacia el Moksha no pasa por alcanzar la perfección — pasa por aceptar la propia humanidad con compasión."],"preguntas":[],"nota":null},{"id":"compartir-en-circulo","nombre":"Compartir en círculo","tipo":"integracion","tiempo":{"min":15,"max":20,"texto":"15 – 20 minutos"},"pasos":["Quienes lo deseen comparten qué concepto resonó más con ellos y qué descubrimiento surgió durante la reflexión. El grupo escucha desde la presencia."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre-meditativo","nombre":"Cierre meditativo","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Cierra con una breve meditación de silencio o la vocalización del sonido OM — el mantra de conexión que representa la unidad de todo en la filosofía hindú."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"No es necesario presentarlos desde un enfoque religioso — su valor como herramientas de autoconocimiento es independiente de cualquier creencia espiritual.","origen":"fuente"},{"texto":"El cierre con OM es opcional — úsalo si el grupo tiene apertura a la práctica. Si no, una respiración colectiva en silencio cumple la misma función de cierre ceremonial.","origen":"fuente"}],"variantes":[{"id":"ed2-41","titulo":"Variante sin marco filosófico hindú (Edición 2, «El Viaje de la Sabiduría Interior»)","tituloFuente":"El Viaje de la Sabiduría Interior","estado":"revision","fuente":{"archivo":"edicion2","paginas":[88,89]},"nota":"Versión sin el marco de Dharma, Karma y Moksha: reflexión general sobre propósito, decisiones y equilibrio.","subtitulo":"Una experiencia para reflexionar sobre el propósito, el equilibrio y el camino personal","contexto":null,"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y contemplativo, acompañado de música suave, iluminación cálida o elementos naturales. Comienza guiando unas respiraciones conscientes para desacelerar y conectar con el momento presente.","Introduce una breve reflexión sobre cómo cada persona vive su propio camino de crecimiento y aprendizaje, atravesando desafíos, cambios y descubrimientos internos.","Invita a los participantes a escribir, reflexionar en silencio o compartir algunas ideas con el grupo si así lo desean.","Al finalizar, puedes cerrar con unos minutos de silencio consciente o una breve meditación guiada enfocada en la gratitud y la presencia."],"citas":[],"preguntas":["¿Qué le da verdadero sentido a mi vida hoy?","¿Qué decisiones me acercan a una vida más auténtica?","¿Qué necesito soltar para avanzar con mayor claridad?","¿Qué parte de mí busca más equilibrio y propósito?"],"nota":null}]}],"fuentes":[{"archivo":"principal","paginas":[85,86],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Intermedio; energía: Filosófica · Expansiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":65,"max":80},"orden":39},{"id":"danza-de-la-conciencia-corporal","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Danza de la Conciencia Corporal","subtitulo":"Una experiencia de movimiento libre para reconectar con el cuerpo, la emoción y la expresión auténtica","resumen":"Una experiencia de movimiento libre para reconectar con el cuerpo, la emoción y la expresión auténtica","contexto":"El cuerpo guarda lo que la mente no siempre puede expresar con palabras. Esta experiencia invita a los participantes a moverse libremente — sin coreografía ni expectativas — usando el movimiento como lenguaje de exploración, presencia y autoconocimiento.","objetivo":"Liberar tensiones físicas y emocionales a través del movimiento consciente, permitiendo que el cuerpo se exprese auténticamente y desarrollando la escucha corporal como práctica de autoconocimiento.","momentos":["integracion","exploracion"],"temas":["danza","movimiento","cuerpo"],"formato":["grupo"],"tipoFuente":"Grupal · Movimiento","duracion":{"min":45,"max":75,"texto":"45 – 75 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Liberadora · Expresiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior","amplio":true,"texto":"Amplio · Despejado"},"participantes":null,"materiales":[{"texto":"Espacio amplio y despejado de obstáculos","ids":[],"opcional":false},{"texto":"Playlist de música variada en 5 ritmos","ids":["musica"],"opcional":false},{"texto":"Ropa cómoda que permita moverse libremente","ids":["ropa-comoda"],"opcional":false},{"texto":"Descalzos si el espacio lo permite","ids":[],"opcional":true}],"ambiente":["Espacio amplio y despejado de obstáculos","Descalzos si el espacio lo permite"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Cada persona elige su ritmo: moverse suavemente, quedarse sentada o acompañar desde la quietud también es participar.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Pausa la música si hay riesgo de choque, caída o mareo, y retoma cuando el espacio vuelva a ser seguro.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["danza-extatica","escaneo-corporal"],"notasAdmin":["La ficha menciona que los cinco ritmos están inspirados en el método de Gabrielle Roth; verificar cómo se presenta esa referencia a un método de terceros."],"propuestas":[],"preparacion":[{"texto":"Prepara la playlist con anticipación — la calidad y transición entre la música de cada ritmo impacta directamente en la profundidad de la experiencia.","origen":"fuente"},{"texto":"Despeja el espacio, marca sus límites y deja agua disponible.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Los 5 ritmos del movimiento consciente","tipo":"lista","items":["Fluir · Suave · Receptivo — Movimientos lentos y continuos, sin pausa. El cuerpo fluye como agua sin resistencia.","Staccato · Definido · Presente — Movimientos con pausa y definición. El cuerpo marca el espacio con claridad y fuerza.","Caos · Libre · Liberador — Movimiento sin forma, sin control. El cuerpo suelta lo que ya no necesita guardar.","Lírico · Liviano · Gozoso — Movimientos que emergen tras el caos. Ligereza, juego y alegría reaparecen en el cuerpo.","Quietud · Inmóvil · Integradora — El movimiento se aquieta. El cuerpo integra en silencio todo lo que vivió durante la danza."],"nota":"Estos cinco ritmos están inspirados en el método de Gabrielle Roth. No es necesario seguirlos estrictamente — úsalos como guía para la playlist y el ritmo general de la sesión."},{"titulo":"Frases para acompañar el movimiento","tipo":"frases","items":["No hay una forma correcta de moverse — hay solo tu forma.","Deja que el cuerpo hable lo que las palabras no pueden decir.","El movimiento auténtico siempre comienza desde adentro."]}],"fases":[{"id":"apertura-corporal","nombre":"Apertura corporal","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Invita al grupo a ponerse de pie y comenzar con movimientos suaves de calentamiento — sacudir las manos, rotar el cuello, mover los hombros — para despertar el cuerpo antes de la danza."],"citas":[],"preguntas":[],"nota":null},{"id":"recorrido-por-los-5-ritmos","nombre":"Recorrido por los 5 ritmos","tipo":"desarrollo","tiempo":{"min":35,"max":50,"texto":"35 – 50 minutos"},"pasos":["Guía al grupo a través de los cinco ritmos con música que acompañe cada estado. Dedica entre 6 y 10 minutos a cada ritmo, transicionando suavemente entre ellos."],"citas":["En el caos, el cuerpo suelta. En el silencio, el cuerpo integra. Ambos son igual de sagrados."],"preguntas":[],"nota":null},{"id":"quietud-e-integracion","nombre":"Quietud e integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Permite que el grupo permanezca en quietud — de pie, sentado o recostado — integrando la experiencia corporal en silencio antes de volver al espacio compartido."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Quienes lo deseen comparten brevemente cómo se sintieron durante la danza — qué ritmo les generó más resistencia, cuál los sorprendió o qué emergió durante el movimiento."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Muévete tú también — tu presencia en la danza modela la libertad y la autenticidad que invitas al grupo a vivir.","origen":"fuente"},{"texto":"Recuerda antes de comenzar que no se trata de bailar bien — sino de moverse auténticamente. Esa liberación del juicio abre el espacio para la experiencia real.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[87,88],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Liberadora · Expresiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":53,"max":74},"orden":40},{"id":"integracion-sombra-luz","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Integración Sombra-Luz","subtitulo":"Una experiencia para abrazar la totalidad del ser — lo que brilla y lo que se esconde","resumen":"Una experiencia para abrazar la totalidad del ser — lo que brilla y lo que se esconde","contexto":"La integración no significa que todo lo oscuro se vuelva luminoso. Significa que aprendemos a sostener ambas partes de nuestra humanidad sin rechazar ninguna. Esta dinámica invita a los participantes a explorar sus dualidades internas y descubrir el poder que existe en la integración de lo que somos en su totalidad.","objetivo":"Invitar a los participantes a explorar y reconocer sus polaridades internas — luz y sombra — como partes complementarias de una misma totalidad, cultivando la integración en lugar de la supresión.","momentos":["exploracion","integracion"],"temas":["sombra","autoconocimiento","escritura"],"formato":["individual"],"tipoFuente":"Individual · Escritura","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Profundo","energiaFuente":"Integradora · Honesta","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel dividido en dos columnas","ids":["papel"],"opcional":false},{"texto":"Bolígrafos y lápices de colores (opcional)","ids":["boligrafos","colores"],"opcional":true},{"texto":"Iluminación tenue y música suave","ids":["musica"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["espejo-de-las-sombras","viaje-de-los-arquetipos"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles — reconocer el propio potencial escondido en la sombra suele mover emociones inesperadamente profundas.","origen":"fuente"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"El mapa de dualidades — ejemplos para explorar","tipo":"lista","items":["El miedo que me paraliza ↔ La precaución que me cuida","El enojo que explota ↔ La fuerza que pone límites","La tristeza que me detiene ↔ La sensibilidad que me conecta","La autoexigencia que me agota ↔ La dedicación que me mueve","La soledad que me pesa ↔ La independencia que me libera"],"nota":"La tabla es solo un mapa de referencia. Invita a cada participante a encontrar sus propias dualidades — las que más resuenan con su experiencia personal."},{"titulo":"Preguntas integradoras","tipo":"preguntas","items":["¿Qué parte de mi sombra guarda en realidad una fortaleza que no he reconocido?","¿Qué parte de mi luz necesito expresar con más valentía?","¿Qué cambiaría en mi vida si dejara de rechazar cualquiera de mis dos partes?"]}],"fases":[{"id":"marco-conceptual","nombre":"Marco conceptual","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Presenta el concepto de integración sombra-luz usando la tabla como referencia. Enfatiza que ninguna parte es negativa en esencia — todas tienen un origen, una función y un potencial cuando se integran conscientemente."],"citas":[],"preguntas":[],"nota":null},{"id":"mapeo-personal","nombre":"Mapeo personal","tipo":"desarrollo","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a los participantes a crear su propio mapa de dualidades en papel dividido en dos columnas. Para cada sombra, buscan la fortaleza o luz que vive en ella."],"citas":["No se trata de eliminar la sombra — se trata de dejar de temerla y comenzar a escucharla."],"preguntas":[],"nota":null},{"id":"reflexion-con-preguntas","nombre":"Reflexión con preguntas","tipo":"integracion","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Invita a explorar las tres preguntas integradoras como profundización del mapeo. Permite el silencio y el tiempo necesario para cada una."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Quienes lo deseen comparten un descubrimiento sobre una de sus dualidades. Cierra recordando que la integración es un camino continuo — no una meta que se alcanza de una vez."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Comparte un ejemplo tuyo antes de que el grupo comience — modelar tu propia dualidad con honestidad abre el espacio para que otros hagan lo mismo.","origen":"fuente"},{"texto":"Recuerda al grupo que la sombra no es el enemigo — es la parte que más necesita ser vista. Ese reencuadre transforma toda la experiencia.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[89,90],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Profundo; energía: Integradora · Honesta."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":55,"max":65},"orden":41},{"id":"taller-de-mandalas","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Taller de Mandalas","subtitulo":"Una experiencia creativa de geometría sagrada para conectar con el centro interior","resumen":"Una experiencia creativa de geometría sagrada para conectar con el centro interior","contexto":"El mandala — que en sánscrito significa \"círculo sagrado\" — es una de las formas de arte contemplativo más antiguas del mundo. Esta experiencia invita a los participantes a crear su propio mandala como práctica meditativa, expresiva y de conexión con el orden interior.","objetivo":"Crear un espacio de expresión creativa meditativa donde cada participante pueda conectar con su mundo interior a través de la creación de un mandala personal — sin expectativas de perfección artística.","momentos":["exploracion","integracion"],"temas":["arte","mandala","meditación"],"formato":["individual"],"tipoFuente":"Individual · Arte","duracion":{"min":90,"max":120,"texto":"90 – 120 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Meditativa · Creativa","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel blanco grueso o cartulina circular","ids":["papel-grande"],"opcional":false},{"texto":"Lápices de colores, acuarelas o rotuladores","ids":["colores"],"opcional":false},{"texto":"Compás, regla y lápiz HB para la estructura base","ids":["boligrafos","compas-regla"],"opcional":false},{"texto":"Música instrumental meditativa de fondo","ids":["musica"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["mandala-colectivo"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Prepara los materiales con anticipación y dispónlos de forma atractiva — la presentación visual del espacio creativo impacta en la energía de la sesión.","origen":"fuente"}],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Las 4 capas del mandala como símbolo interior","tipo":"lista","items":["Centro · El punto de origen — El ser esencial. Lo que eres en tu núcleo más auténtico, más allá de roles y máscaras.","Primer anillo · El mundo interior — Emociones, creencias y experiencias que moldean tu forma de ver y sentir la vida.","Segundo anillo · Las relaciones — Los vínculos, comunidades y conexiones que forman parte de tu mundo y te sostienen.","Borde exterior · El mundo externo — El entorno, la naturaleza, la sociedad y el universo del que formas parte."]},{"titulo":"Intenciones para crear el mandala","tipo":"frases","items":["Crea desde la intuición, no desde la perfección artística.","Deja que cada color y forma emerja espontáneamente.","El proceso importa más que el resultado final."],"nota":"Si alguien se bloquea con el dibujo libre, ofrece plantillas de mandala ya impresas para colorear — igualmente válidas como práctica meditativa."}],"fases":[{"id":"apertura-e-intencion","nombre":"Apertura e intención","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Presenta el significado del mandala y las cuatro capas como guía simbólica. Invita a cada participante a conectar con una intención antes de comenzar a crear."],"citas":[],"preguntas":[],"nota":null},{"id":"creacion-meditativa","nombre":"Creación meditativa","tipo":"desarrollo","tiempo":{"min":60,"max":80,"texto":"60 – 80 minutos"},"pasos":["El grupo crea en silencio con música meditativa de fondo. El facilitador sostiene el espacio con presencia — sin dirigir ni comentar lo que cada persona crea."],"citas":["El mandala no es solo un dibujo — es un mapa de tu mundo interior en este momento."],"preguntas":[],"nota":null},{"id":"contemplacion","nombre":"Contemplación","tipo":"integracion","tiempo":{"min":5,"max":10,"texto":"5 – 10 minutos"},"pasos":["Invita a cada persona a observar su mandala terminado en silencio. ¿Qué ves? ¿Qué te sorprende? ¿Qué parte no esperabas crear?"],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Quienes lo deseen comparten su mandala y lo que emergió durante la creación. Cierra invitando a guardar el mandala como mapa del estado interior de este momento del retiro."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Nunca interpretes el mandala de otra persona — su significado pertenece únicamente a quien lo creó desde su mundo interior.","origen":"fuente"},{"texto":"Crea tú también tu mandala durante la sesión — tu presencia creativa sostiene el espacio y modela la libertad que invitas al grupo a vivir.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[91,92],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"maquetacion","severidad":"baja","detalle":"La parte inferior de la página 92 usa un formato distinto al resto (texto plano); el contenido es completo."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Meditativa · Creativa."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":85,"max":115},"orden":42},{"id":"meditacion-de-la-compasion-universal","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Meditación de la Compasión Universal","subtitulo":"Una práctica de amor bondadoso para expandir el corazón hacia uno mismo y hacia todos los seres","resumen":"Una práctica de amor bondadoso para expandir el corazón hacia uno mismo y hacia todos los seres","contexto":"La compasión no es solo un sentimiento — es una práctica que puede cultivarse conscientemente. Esta meditación, inspirada en la tradición budista del Metta Bhavana o \"amor bondadoso\", invita a expandir el corazón en círculos concéntricos — desde uno mismo hasta todos los seres.","objetivo":"Cultivar el amor bondadoso y la compasión de forma consciente y progresiva, expandiendo el círculo de cuidado desde uno mismo hacia personas cercanas, conocidas y finalmente hacia todos los seres.","momentos":["exploracion","conexion"],"temas":["compasión","meditación","bondad"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Amorosa · Expansiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Cojines o esterillas para sentarse","ids":["cojines-esterillas"],"opcional":false},{"texto":"Música suave o silencio","ids":["musica"],"opcional":false},{"texto":"Iluminación tenue y cálida","ids":[],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":["Iluminación tenue y cálida"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["meditacion-del-corazon-abierto","ritual-del-perdon"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles — el primer círculo (hacia uno mismo) suele ser el que más emociones mueve, especialmente en personas con baja autoestima o mucha autoexigencia.","origen":"fuente"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Los 5 círculos de la compasión","tipo":"lista","items":["1 · Uno mismo — Que yo sea feliz. Que yo esté en paz. Que yo esté libre de sufrimiento.","2 · Seres queridos — Que quienes amo sean felices. Que estén en paz y libres de dolor.","3 · Personas neutras — Que quienes me son indiferentes también encuentren paz y bienestar.","4 · Personas difíciles — Que incluso quienes me han causado dolor puedan encontrar paz interior.","5 · Todos los seres — Que todos los seres en este mundo sean felices y estén libres de sufrimiento."]},{"titulo":"Las frases Metta para guiar la meditación (repite internamente para cada círculo)","tipo":"frases","items":["Que seas feliz.","Que estés en paz.","Que estés libre de sufrimiento.","Que tu vida esté llena de amor."],"nota":"El círculo 4 (personas difíciles) suele ser el más resistido. Recuerda al grupo que no se trata de aprobar lo que esa persona hizo — sino de liberar el propio corazón del peso del resentimiento."}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse cómodamente, cerrar los ojos y colocar las manos sobre el corazón. Guía unas respiraciones suaves para conectar con el pecho antes de comenzar."],"citas":[],"preguntas":[],"nota":null},{"id":"los-5-circulos","nombre":"Los 5 círculos","tipo":"desarrollo","tiempo":{"min":20,"max":30,"texto":"20 – 30 minutos"},"pasos":["Guía al grupo a través de cada círculo con las frases Metta. Dedica 3 a 5 minutos a cada uno, permitiendo que las palabras resuenen antes de pasar al siguiente."],"citas":["La compasión que no comienza por uno mismo difícilmente puede alcanzar a los demás."],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Deja unos minutos de silencio después del quinto círculo. Invita a regresar lentamente y a permanecer con la sensación en el pecho antes de abrir los ojos."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen comparten qué círculo fue el más difícil y qué sintieron al enviar compasión hacia sí mismos y hacia los demás."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Empieza siempre por uno mismo — es el paso que más resistencia genera y el más importante. Sin compasión propia, los siguientes círculos quedan vacíos.","origen":"fuente"},{"texto":"Cuando llegues al círculo de personas difíciles, recuerda al grupo que no se les pide que aprueben o perdonen — solo que liberen el propio corazón del peso.","origen":"fuente"}],"variantes":[{"id":"ed2-42","titulo":"Versión breve (Edición 2, «Meditación de la Compasión»)","tituloFuente":"Meditación de la Compasión","estado":"revision","fuente":{"archivo":"edicion2","paginas":[90,91]},"nota":"Versión simplificada de la Meditación de la Compasión Universal (frases de amabilidad que se expanden hacia otras personas).","subtitulo":null,"contexto":null,"fases":[]}],"fuentes":[{"archivo":"principal","paginas":[93,94],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Amorosa · Expansiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":35,"max":48},"orden":43},{"id":"el-templo-del-utero","version":1,"estado":"publicado","motivoEstado":null,"titulo":"El Templo del Útero","subtitulo":"Una experiencia para reconectar con el centro creador, la intuición y la sabiduría femenina interior","resumen":"Una experiencia para reconectar con el centro creador, la intuición y la sabiduría femenina interior","contexto":"El útero — ya sea físico o energético — representa el centro creador del ser. Esta experiencia invita a reconectar con esa fuente interior de intuición, creatividad y sabiduría que todas las personas llevamos dentro, independientemente del género.","objetivo":"Reconectar a los participantes con su centro energético creador — el espacio interior de intuición, gestación y fuerza vital — a través de la meditación, la visualización y la exploración simbólica.","momentos":["exploracion"],"temas":["centro creador","intuición","meditación"],"formato":["individual"],"tipoFuente":"Individual · Meditación","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":"La fuente indica 60–75 min; las fases descritas suman 53–58 min.","nivelFuente":null,"energiaFuente":"Sagrada · Intuitiva","momentoFuente":null,"enfoqueFuente":"Energía femenina","espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas, cojines o mantas","ids":["cojines-esterillas","mantas"],"opcional":false},{"texto":"Música de cuencos o sonidos de agua","ids":["musica"],"opcional":false},{"texto":"Velas rojas, rosas o blancas","ids":["velas"],"opcional":false},{"texto":"Elementos naturales: flores, cristales, tierra","ids":["elementos-naturales"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Si una imagen resulta incómoda, se puede abrir los ojos, volver a la respiración o dejar la visualización y descansar.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["meditacion-del-corazon-abierto","conexion-con-el-nino-interior"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos disponibles — reconectar con el centro creador puede despertar memorias, duelos o emociones profundas relacionadas con la creatividad, la maternidad o el cuerpo.","origen":"fuente"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Las 4 energías del centro creador","tipo":"lista","items":["La creadora · Dar vida a lo nuevo — La capacidad de gestar, crear y dar forma a ideas, proyectos, relaciones y versiones de uno mismo.","La intuitiva · Saber sin explicar — La sabiduría que no necesita justificarse. El conocimiento que llega desde adentro antes de que la mente lo procese.","La nutricia · Sostener y cuidar — La capacidad de cuidar, contener y nutrir — a los demás y, sobre todo, a uno mismo.","La transformadora · Morir y renacer — El poder de soltar lo que ya no sirve y abrir espacio para algo nuevo — como lo hacen los ciclos de la naturaleza."]},{"titulo":"Preguntas para la reflexión interior","tipo":"preguntas","items":["¿Qué estoy gestando o deseando crear en este momento de mi vida?","¿Qué intuición he estado ignorando o posponiendo escuchar?","¿Cómo puedo nutrir mejor mi propio centro creador?"],"nota":"Esta dinámica es poderosa para cualquier género — la energía del útero es simbólica y universal. Preséntala como reconexión con el centro creador interior, no exclusivamente como práctica femenina."}],"fases":[{"id":"preparacion-sagrada","nombre":"Preparación sagrada","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Crea un ambiente íntimo y ceremonial. Presenta las cuatro energías y el concepto del centro creador. Invita al grupo a recostarse o sentarse con las manos sobre el vientre."],"citas":[],"preguntas":[],"nota":null},{"id":"meditacion-guiada","nombre":"Meditación guiada","tipo":"desarrollo","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Guía una visualización hacia el centro energético — imaginar una llama, un lago o una flor en el vientre. Invita a explorar cada una de las cuatro energías con pausas largas entre cada una."],"citas":["Tu centro creador no necesita permiso para existir — solo necesita ser recordado y habitado."],"preguntas":[],"nota":null},{"id":"reflexion-escrita","nombre":"Reflexión escrita","tipo":"integracion","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Invita a explorar las tres preguntas de reflexión en silencio, escribiendo desde la intuición y sin censurar lo que emerge."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre-ceremonial","nombre":"Cierre ceremonial","tipo":"cierre","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Cierra con un gesto de honrar el propio centro creador — una mano sobre el vientre, una respiración profunda o una palabra de gratitud hacia esa parte de uno mismo."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Presenta desde el inicio que esta práctica es universal — la energía del útero como centro creador trasciende el género y es accesible a todos.","origen":"fuente"},{"texto":"Crea el ambiente con más cuidado que en otras dinámicas — flores, velas, aromas y elementos naturales enriquecen significativamente esta experiencia.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[95,96],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"tiempos","severidad":"media","detalle":"La ficha indica 60–75 min, pero sus fases suman 53–58 min."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Sagrada · Intuitiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":53,"max":58},"orden":44},{"id":"danza-extatica","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Danza Extática","subtitulo":"Una experiencia de movimiento libre, gozoso y consciente para liberar el cuerpo y elevar el espíritu","resumen":"Una experiencia de movimiento libre, gozoso y consciente para liberar el cuerpo y elevar el espíritu","contexto":"La danza extática no es una coreografía ni una performance — es un estado de presencia plena en el cuerpo en movimiento. Esta experiencia invita al grupo a bailar libremente, sin pasos correctos, dejando que el cuerpo exprese lo que las palabras no pueden y que el gozo emerja sin permiso.","objetivo":"Liberar tensiones físicas, emocionales y mentales a través del movimiento gozoso y libre, conectando con la alegría del cuerpo como práctica espiritual y de presencia plena.","momentos":["integracion","cierre"],"temas":["danza","movimiento","gozo"],"formato":["grupo"],"tipoFuente":"Grupal · Movimiento","duracion":{"min":60,"max":90,"texto":"60 – 90 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Gozosa · Liberadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior","amplio":true,"texto":"Amplio · Despejado"},"participantes":null,"materiales":[{"texto":"Espacio amplio, suelo limpio, sin obstáculos","ids":[],"opcional":false},{"texto":"Sistema de sonido con buena calidad","ids":["musica"],"opcional":false},{"texto":"Playlist de música variada — 60 a 90 min.","ids":["musica"],"opcional":false},{"texto":"Agua disponible para los participantes","ids":["agua"],"opcional":false}],"ambiente":["Espacio amplio, suelo limpio, sin obstáculos"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Cada persona elige su ritmo: moverse suavemente, quedarse sentada o acompañar desde la quietud también es participar.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Pausa la música si hay riesgo de choque, caída o mareo, y retoma cuando el espacio vuelva a ser seguro.","origen":"adaptacion"},{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["danza-de-la-conciencia-corporal"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Prepara la playlist con antelación y pruébala — el arco musical es el facilitador invisible de toda la sesión. Una transición abrupta puede romper el estado de la danza.","origen":"fuente"},{"texto":"Sitúa el agua en un lugar accesible pero sin interrumpir el espacio de danza — los participantes necesitan hidratarse sin salir del estado de presencia corporal.","origen":"fuente"},{"texto":"Despeja el espacio, marca sus límites y deja agua disponible.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Acuerdos sagrados de la danza","tipo":"lista","items":["Sin alcohol ni sustancias — la danza extática es un estado natural de presencia, no de alteración.","Sin hablar durante la danza — el cuerpo comunica, la mente descansa.","Respetar el espacio personal — si hay contacto, siempre con consentimiento.","No hay movimiento correcto ni incorrecto — solo el que emerge auténticamente del cuerpo."]},{"titulo":"El arco musical de la sesión","tipo":"lista","items":["1 · Despertar · Lento y suave — Música tranquila para despertar el cuerpo. Movimientos lentos que recorren desde los pies hasta la cabeza.","2 · Activación · Ritmo creciente — La música sube de intensidad. El cuerpo comienza a moverse con más energía y libertad.","3 · Éxtasis · Pico de la sesión — La música alcanza su punto de mayor intensidad. El cuerpo se libera completamente — sin control, sin censura.","4 · Integración · Descenso suave — La música desciende gradualmente. El cuerpo encuentra calma, contacto con el suelo y presencia."]},{"titulo":"Frases para acompañar","tipo":"frases","items":["Deja que el cuerpo baile — y que la mente simplemente observe.","No hay un paso correcto — hay solo un cuerpo presente.","El gozo también es una práctica espiritual."]}],"fases":[{"id":"apertura-y-acuerdos","nombre":"Apertura y acuerdos","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Presenta los cuatro acuerdos antes de comenzar. Invita al grupo a quitarse los zapatos, sacudir el cuerpo y conectar con la respiración para llegar presentes antes de que comience la música."],"citas":[],"preguntas":[],"nota":null},{"id":"la-danza","nombre":"La danza","tipo":"desarrollo","tiempo":{"min":50,"max":70,"texto":"50 – 70 minutos"},"pasos":["Deja que la música guíe los cuatro momentos del arco. Tu rol durante la danza es sostener el espacio y bailar también — no dirigir ni corregir movimientos."],"citas":["A veces, el cuerpo sabe exactamente lo que necesita — solo necesitamos darle permiso para expresarlo."],"preguntas":[],"nota":"Algunos participantes pueden sentarse, llorar o simplemente observar durante la danza — todo es válido. La presencia consciente también es una forma de participar."},{"id":"cierre-en-el-suelo","nombre":"Cierre en el suelo","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Invita al grupo a recostarse en el suelo y dejar que el cuerpo descanse completamente. Unos minutos de silencio y respiración para integrar la experiencia antes de volver al espacio compartido."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Baila tú también durante toda la sesión — tu movimiento libre da permiso al grupo para soltar el juicio sobre el propio cuerpo.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[97,98],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Gozosa · Liberadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":66,"max":88},"orden":45},{"id":"neurociencia-de-la-transformacion","version":1,"estado":"revision","motivoEstado":"Requiere revisión especializada: presenta afirmaciones científicas que deben verificarse (reconsolidación de la memoria como «reescribir la historia», neuronas espejo, «recablear tu cerebro», «el retiro es un estado óptimo para el cambio real»).","titulo":"Neurociencia de la Transformación","subtitulo":"Una experiencia para comprender cómo el cerebro cambia y cómo podemos participar en ese proceso","resumen":"Una experiencia para comprender cómo el cerebro cambia y cómo podemos participar en ese proceso","contexto":"La neurociencia ha confirmado lo que muchas tradiciones espirituales intuían — el cerebro puede cambiar. No estamos atrapados en nuestros patrones. Cada nueva experiencia, pensamiento consciente y hábito que cultivamos está literalmente recableando nuestra biología.","objetivo":"Comprender desde la neurociencia cómo funciona el cambio cerebral y usar ese conocimiento para diseñar intencionalmente nuevos patrones de pensamiento, emoción y comportamiento.","momentos":["integracion"],"temas":["hábitos","cambio","reflexión"],"formato":["grupo","individual"],"tipoFuente":"Grupal · Reflexión","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Racional · Esperanzadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos","ids":["papel","boligrafos"],"opcional":false},{"texto":"Pizarra o papel grande para el marco conceptual","ids":["papel-grande","pizarra"],"opcional":false},{"texto":"Música suave de fondo","ids":["musica"],"opcional":false},{"texto":"Espacio cómodo e íntimo","ids":[],"opcional":false}],"ambiente":["Espacio cómodo e íntimo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ley-de-la-atraccion-consciente"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Los 4 conceptos científicos clave","tipo":"lista","items":["Neuroplasticidad · Neurociencia — El cerebro puede crear nuevas conexiones neuronales a cualquier edad en respuesta a nuevas experiencias y aprendizajes. → Cambiar es biológicamente posible — siempre.","Memoria de reconsolidación · Neurociencia cognitiva — Cada vez que recordamos algo, esa memoria se vuelve temporalmente modificable. Podemos resignificar el pasado. → Reescribir la historia desde el presente es real.","Neuronas espejo · Neurociencia social — El cerebro aprende imitando — observar a alguien realizar algo activa las mismas zonas neurales que hacerlo uno mismo. → El entorno y los modelos que elegimos nos forman.","Estados y etapas · Psicología del desarrollo — Los estados de apertura emocional facilitan el aprendizaje. Las experiencias intensas dejan huellas neuronales más profundas. → El retiro es un estado óptimo para el cambio real."]},{"titulo":"Preguntas de aplicación personal","tipo":"preguntas","items":["¿Qué patrón mental o emocional deseo reprogramar conscientemente?","¿Qué hábito nuevo, si lo repitiera 30 días, podría cambiar mi cerebro?","¿Qué entorno, personas o experiencias están moldeando mis neuronas sin que me dé cuenta?"],"nota":"La segunda pregunta suele ser la más transformadora — diseñar un hábito concreto de 30 días convierte el insight del retiro en una acción real que continúa después."}],"fases":[{"id":"marco-conceptual","nombre":"Marco conceptual","tipo":"apertura","tiempo":{"min":15,"max":20,"texto":"15 – 20 minutos"},"pasos":["Presenta los cuatro conceptos de forma clara y accesible — sin jerga científica excesiva. Usa ejemplos cotidianos y conecta cada concepto con la experiencia del retiro que están viviendo."],"citas":["No estás aquí solo para sentirte mejor — estás aquí para literalmente recablear tu cerebro."],"preguntas":[],"nota":null},{"id":"reflexion-individual","nombre":"Reflexión individual","tipo":"integracion","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Invita a explorar las tres preguntas de aplicación personal en silencio y por escrito. Enfatiza la importancia de que el hábito elegido sea concreto, pequeño y realista."],"citas":[],"preguntas":[],"nota":null},{"id":"diseno-del-habito","nombre":"Diseño del hábito","tipo":"desarrollo","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Invita a cada participante a escribir en una tarjeta su hábito de 30 días: qué harán, cuándo y cómo lo medirán. Esta tarjeta es el puente entre el retiro y la vida cotidiana."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Quienes lo deseen comparten su hábito elegido. Cierra recordando que el cerebro cambia cada vez que repiten la nueva conducta — la coherencia es la herramienta."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Usa el lenguaje de la neurociencia con humildad — presenta los conceptos como marcos útiles, no como verdades absolutas o recetas mágicas.","origen":"fuente"},{"texto":"Conecta cada concepto con algo que el grupo ya vivió durante el retiro — eso hace la neurociencia tangible y emocionalmente relevante.","origen":"fuente"},{"texto":"Insiste en que el hábito sea pequeño y concreto — un hábito demasiado grande nunca se implementa. Mejor 5 minutos diarios que una hora imposible de mantener.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[99,100],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Racional · Esperanzadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":58,"max":70},"orden":46},{"id":"circulo-de-vulnerabilidad","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Vulnerabilidad","subtitulo":"Un espacio para mostrarse tal como se es — y descubrir que en eso estamos todos juntos","resumen":"Un espacio para mostrarse tal como se es — y descubrir que en eso estamos todos juntos","contexto":"La vulnerabilidad no es debilidad — es el terreno donde nacen las conexiones más reales. Esta dinámica invita a los participantes a abrirse desde la honestidad, compartiendo desde un lugar más humano y consciente, y descubrir que al mostrarnos tal como somos, nos acercamos a los demás en lugar de alejarnos.","objetivo":"Crear un espacio de expresión auténtica donde los participantes puedan mostrarse tal como se sienten en este momento, profundizando la confianza y la conexión humana dentro del grupo.","momentos":["conexion","exploracion"],"temas":["vulnerabilidad","círculo","escucha"],"formato":["grupo"],"tipoFuente":"Grupal · Círculo","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":"Profundo","energiaFuente":"Honesta · Vincular","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio en círculo con iluminación cálida","ids":[],"opcional":false},{"texto":"Vela central como foco de presencia","ids":["vela-central"],"opcional":false},{"texto":"Pañuelos disponibles y visibles","ids":["panuelos"],"opcional":false},{"texto":"Música suave solo para la apertura","ids":["musica"],"opcional":false}],"ambiente":["Espacio en círculo con iluminación cálida"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[{"texto":"En la primera sesión del retiro: requiere que el grupo tenga un nivel mínimo de confianza previo.","origen":"fuente"}],"relacionadas":["circulo-de-historias-de-vida","circulo-de-escucha-consciente"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Acuerdos del círculo","tipo":"lista","items":["Lo que se comparte aquí permanece aquí — confidencialidad absoluta dentro del grupo.","Escuchamos sin interrumpir, sin aconsejar y sin intentar \"arreglar\" lo que el otro siente.","Nadie está obligado a compartir — el silencio también es una forma válida de presencia."]},{"titulo":"Preguntas para abrir el espacio","tipo":"preguntas","items":["¿Qué parte de mí suelo ocultar por miedo a ser juzgado?","¿Qué emoción necesito expresar hoy con más honestidad?","¿Qué me cuesta mostrar cuando estoy con otras personas?"],"nota":"No es obligatorio responder las tres preguntas. Invita a compartir desde donde cada persona se sienta lista — incluso una sola frase auténtica puede ser más poderosa que un discurso largo."},{"titulo":"Frases para acompañar el círculo","tipo":"frases","items":["La vulnerabilidad no es debilidad — es la puerta hacia la conexión real.","Mostrarte tal como eres es un acto de valentía que inspira a los demás a hacer lo mismo.","Sentirse escuchado sin necesidad de \"arreglarse\" también puede transformar."]}],"fases":[{"id":"apertura-y-acuerdos","nombre":"Apertura y acuerdos","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Crea el ambiente íntimo con vela encendida. Lee los tres acuerdos del círculo con calma y asegúrate de que el grupo los comprenda y acepte antes de comenzar."],"citas":[],"preguntas":[],"nota":null},{"id":"espacio-de-apertura","nombre":"Espacio de apertura","tipo":"apertura","tiempo":{"min":30,"max":40,"texto":"30 – 40 minutos"},"pasos":["Comparte tú primero desde la vulnerabilidad — modela el nivel de apertura que invitas. Luego abre el espacio para que quienes lo deseen compartan desde las preguntas guía."],"citas":["A veces, sentirse escuchado sin necesidad de cambiar nada es exactamente lo que más necesitamos."],"preguntas":[],"nota":null},{"id":"cierre","nombre":"Cierre","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Cierra con una respiración colectiva o unos minutos de silencio consciente. Puedes invitar a una palabra de cierre de cada persona — algo que se llevan de este espacio."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Comparte tú primero y con autenticidad real — el nivel de apertura del facilitador establece el permiso para que el grupo vaya a esa misma profundidad.","origen":"fuente"},{"texto":"Nunca interrumpas ni intentes consolar mientras alguien habla — tu presencia silenciosa y receptiva es la forma más poderosa de sostener el espacio.","origen":"fuente"},{"texto":"Esta dinámica requiere que el grupo tenga un nivel mínimo de confianza previo — no la uses en la primera sesión del retiro.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[101,102],"rol":"principal"},{"archivo":"edicion2","paginas":[92,93],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Profundo; energía: Honesta · Vincular."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":58},"orden":47},{"id":"conexion-con-los-cuatro-elementos","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Conexión con los Cuatro Elementos","subtitulo":"Una experiencia sensorial para reconectar con las energías primordiales de la naturaleza","resumen":"Una experiencia sensorial para reconectar con las energías primordiales de la naturaleza","contexto":"La tierra, el agua, el fuego y el aire han sido símbolos de transformación y equilibrio en tradiciones de todo el mundo. Esta experiencia invita a los participantes a explorar la relación entre los elementos de la naturaleza y su propio mundo interior a través de la presencia sensorial y la reflexión.","objetivo":"Reconectar a los participantes con las cuatro energías elementales como espejo de su mundo interior, desarrollando presencia sensorial y autoconocimiento a través de la naturaleza.","momentos":["exploracion","apertura"],"temas":["naturaleza","elementos","estaciones"],"formato":["grupo","individual"],"tipoFuente":"Grupal · Vivencial","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Sensorial · Enraizante","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"ambos","texto":"Interior o exterior"},"participantes":null,"materiales":[{"texto":"Vela encendida — fuego","ids":["vela-central"],"opcional":false},{"texto":"Cuenco con agua — agua","ids":["recipiente-agua-tierra"],"opcional":false},{"texto":"Tierra, piedra o plantas — tierra","ids":["elementos-naturales"],"opcional":false},{"texto":"Incienso, pluma o ventilación natural — aire","ids":["incienso"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["conexion-con-la-naturaleza","meditacion-del-arbol"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Prepara las estaciones con cuidado y belleza — la calidad visual y sensorial de cada espacio elemental comunica antes que el participante llegue.","origen":"fuente"},{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Los cuatro elementos y su mundo interior","tipo":"lista","items":["Fuego · Pasión · Voluntad — La fuerza que impulsa, la pasión que mueve y la voluntad que sostiene el camino. Pregunta: ¿Dónde arde mi fuego en este momento?","Agua · Emoción · Fluidez — Las emociones que fluyen, se estancan o desbordan, y la capacidad de adaptarse. Pregunta: ¿Dónde necesito más fluidez en mi vida?","Tierra · Estabilidad · Cuerpo — El enraizamiento, la seguridad y la presencia física que sostiene todo lo demás. Pregunta: ¿Dónde necesito más estabilidad o arraigo?","Aire · Mente · Claridad — El pensamiento, la comunicación y la libertad de expandirse más allá de los límites conocidos. Pregunta: ¿Qué aspecto de mi vida pide más ligereza?"]},{"titulo":"Preguntas integradoras","tipo":"preguntas","items":["¿Qué elemento representa mejor tu energía en este momento?","¿Qué elemento sientes que más te falta o más necesitas cultivar?","¿Cómo podrías traer ese elemento de forma más consciente a tu vida cotidiana?"],"nota":"Anima a los participantes a conectar más con la experiencia sensorial que con el análisis racional. El cuerpo siente los elementos antes de que la mente los interprete."}],"fases":[{"id":"preparacion-del-espacio","nombre":"Preparación del espacio","tipo":"apertura","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Dispone las cuatro estaciones elementales en el espacio — cada una con su objeto representativo. Preséntalo brevemente y explica la intención de recorrerlas de forma consciente y lenta."],"citas":[],"preguntas":[],"nota":null},{"id":"recorrido-sensorial","nombre":"Recorrido sensorial","tipo":"desarrollo","tiempo":{"min":30,"max":40,"texto":"30 – 40 minutos"},"pasos":["Invita al grupo a recorrer cada estación de manera individual y pausada, observando las sensaciones, emociones y pensamientos que aparecen en cada espacio elemental."],"citas":["La naturaleza también puede ser un espejo de nuestro proceso interno — si aprendemos a escucharla."],"preguntas":[],"nota":null},{"id":"reflexion-escrita","nombre":"Reflexión escrita","tipo":"integracion","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Después del recorrido, invita a explorar las tres preguntas integradoras en silencio y por escrito."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir-y-cierre","nombre":"Compartir y cierre","tipo":"cierre","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Reúne al grupo para compartir qué elemento resonó más y qué descubrieron sobre sí mismos. Cierra con una respiración colectiva honrando los cuatro elementos."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Si el espacio exterior lo permite, realiza la dinámica en la naturaleza — el contacto directo con los elementos amplifica enormemente la experiencia.","origen":"fuente"},{"texto":"Deja tiempo generoso en cada estación — no menos de 6 a 8 minutos por elemento para que la experiencia sea realmente sensorial y no solo conceptual.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[103,104],"rol":"principal"},{"archivo":"edicion2","paginas":[94,95],"rol":"contraste"}],"correcciones":[{"campo":"secciones.0.items.1","original":"Las emociones que fluyen, se estancan o desbordandepen y la capacidad de adaptarse.","corregido":"Las emociones que fluyen, se estancan o desbordan, y la capacidad de adaptarse.","motivo":"Palabras unidas por error en la fuente."}],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Sensorial · Enraizante."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":60,"max":70},"orden":48},{"id":"danza-de-liberacion-emocional","version":1,"estado":"revision","motivoEstado":"La recomendación 02 afirma que el llanto es señal de que la dinámica funciona y pide no intervenir; contradice los límites del brief y necesita reescritura aprobada. La versión de la Edición 2 no incluye esa frase.","titulo":"Danza de Liberación Emocional","subtitulo":"Una experiencia de movimiento consciente para expresar y liberar lo que el cuerpo lleva guardado","resumen":"Una experiencia de movimiento consciente para expresar y liberar lo que el cuerpo lleva guardado","contexto":"El cuerpo muchas veces expresa aquello que las palabras no alcanzan a decir. Esta dinámica invita a los participantes a liberar tensión, emociones y energía acumulada a través del movimiento consciente — sin técnica, sin coreografía, solo presencia y permiso.","objetivo":"Permitir que los participantes expresen y liberen emociones acumuladas a través del movimiento corporal libre y consciente, restaurando la conexión entre el cuerpo, la emoción y la presencia.","momentos":["exploracion"],"temas":["danza","emociones","movimiento"],"formato":["grupo"],"tipoFuente":"Grupal · Movimiento","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Expresiva · Catártica","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior","amplio":true,"texto":"Amplio · Despejado"},"participantes":null,"materiales":[{"texto":"Espacio amplio libre de obstáculos","ids":[],"opcional":false},{"texto":"Música progresiva e instrumental variada","ids":["musica"],"opcional":false},{"texto":"Agua disponible para los participantes","ids":["agua"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":["Espacio amplio libre de obstáculos"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Cada persona elige su ritmo: moverse suavemente, quedarse sentada o acompañar desde la quietud también es participar.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Pausa la música si hay riesgo de choque, caída o mareo, y retoma cuando el espacio vuelva a ser seguro.","origen":"adaptacion"},{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["danza-de-la-conciencia-corporal","danza-extatica"],"notasAdmin":[],"propuestas":[{"campo":"recomendaciones.1","texto":"Si alguien llora o se emociona durante el movimiento, sostén el espacio con presencia tranquila y ofrécele la posibilidad de pausar, sentarse o tomar agua; no hace falta interrumpir si la persona está bien acompañada.","motivo":"Reescritura propuesta, pendiente de aprobación."}],"preparacion":[{"texto":"Despeja el espacio, marca sus límites y deja agua disponible.","origen":"adaptacion"},{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"avanzada","intensidad":"profunda","adaptaciones":[],"secciones":[{"titulo":"Emociones que el movimiento puede liberar","tipo":"lista","items":["Tristeza — Movimientos lentos, pesados, hacia el suelo","Enojo — Movimientos fuertes, percusivos, hacia afuera","Miedo — Movimientos pequeños que crecen gradualmente","Tensión — Sacudir el cuerpo, soltar, vibrar","Alegría — Movimientos expansivos, ligeros, hacia arriba","Calma — Movimientos circulares, fluidos, integradores"],"nota":"No es necesario decir al grupo qué emoción liberar — la música y el movimiento libre llevan naturalmente al cuerpo a lo que necesita expresar."},{"titulo":"Frases para acompañar","tipo":"frases","items":["Deja que el cuerpo encuentre su propia forma de expresarse.","No te preocupes por cómo se ve — solo por cómo se siente.","El movimiento auténtico siempre lleva algo hacia afuera."]}],"fases":[{"id":"apertura-corporal","nombre":"Apertura corporal","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Guía al grupo a conectar con el cuerpo desde la quietud — respiraciones profundas, sacudir las manos, rotar el cuello. Introduce la intención: no hay movimiento correcto, solo movimiento honesto."],"citas":[],"preguntas":[],"nota":null},{"id":"movimiento-libre","nombre":"Movimiento libre","tipo":"desarrollo","tiempo":{"min":30,"max":40,"texto":"30 – 40 minutos"},"pasos":["Pon la música y deja que el grupo se mueva libremente. Comienza con música lenta y deja que la energía suba gradualmente con el ritmo. Muévete tú también — tu presencia sostiene el espacio."],"citas":["El cuerpo sabe exactamente qué necesita liberar — nuestra tarea es darle permiso para hacerlo."],"preguntas":[],"nota":null},{"id":"aterrizaje","nombre":"Aterrizaje","tipo":"integracion","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["La música desciende lentamente hasta el silencio. Invita al grupo a recostarse, llevar las manos al corazón y respirar conscientemente, integrando lo que el movimiento liberó."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen comparten qué surgió durante el movimiento — qué emoción emergió, qué se liberó o qué se descubrió. No hay análisis — solo compartir desde la experiencia."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Recuerda al inicio que no es una clase de baile — es un espacio de expresión. Esa diferencia libera a quienes se sienten \"malos bailarines\".","origen":"fuente"},{"texto":"Si alguien llora durante el movimiento, es señal de que la dinámica está funcionando — no intervengas, solo sostén el espacio con tu presencia tranquila.","origen":"fuente"},{"texto":"La fase de aterrizaje es tan importante como el movimiento — no la omitas nunca. Sin ella, el grupo puede quedar en un estado de alta energía sin integrar.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[105,106],"rol":"principal"},{"archivo":"edicion2","paginas":[96,97],"rol":"contraste"}],"correcciones":[],"incidencias":[{"tipo":"contenido","severidad":"alta","detalle":"La recomendación 02 equipara llanto con eficacia de la dinámica y sugiere no intervenir: el brief prohíbe afirmar que llorar demuestra que una actividad funciona y que siempre hay que abstenerse de intervenir. Requiere reescritura editorial antes de publicar."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Expresiva · Catártica."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":51,"max":63},"orden":49},{"id":"meditacion-de-la-gratitud","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Meditación de la Gratitud","subtitulo":"Una práctica de presencia consciente para reconectar con la abundancia que ya existe","resumen":"Una práctica de presencia consciente para reconectar con la abundancia que ya existe","contexto":"La gratitud cambia la manera en que observamos nuestra vida. Cuando hacemos una pausa para reconocer aquello que sí está presente, aparece una sensación más profunda de calma, conexión y plenitud. Esta práctica invita a los participantes a entrar en un estado de presencia consciente a través de la gratitud genuina.","objetivo":"Cultivar un estado de presencia y apertura emocional a través de la gratitud consciente, conectando con personas, experiencias y aspectos de la vida que sostienen y enriquecen el camino.","momentos":["apertura","integracion"],"temas":["gratitud","meditación","presencia"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Luminosa · Receptiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Cojines o esterillas para sentarse","ids":["cojines-esterillas"],"opcional":false},{"texto":"Música suave e instrumental","ids":["musica"],"opcional":false},{"texto":"Iluminación cálida o velas","ids":["velas"],"opcional":false},{"texto":"Papel para escribir al finalizar (opcional)","ids":["papel"],"opcional":true}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Como apertura del día: la gratitud pone al grupo en un estado receptivo y abierto para lo que viene.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["circulo-de-gratitud","ritual-de-gratitud-colectiva"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Áreas de gratitud para explorar","tipo":"lista","items":["Personas que me sostienen y quieren","Aprendizajes y crecimiento personal","Momentos que cambiaron algo en mí","La salud, el cuerpo y la naturaleza","Las pequeñas cosas que dan sentido al día","El hogar y el espacio que me sostiene"],"nota":"La intención no es \"pensar positivo\" — sino permitir que la gratitud se convierta en una experiencia genuina y sentida en el cuerpo, no solo en la mente."},{"titulo":"Frases para guiar la meditación","tipo":"frases","items":["Permite que la gratitud expanda tu atención más allá de lo que te preocupa.","Reconoce aquello que hoy sostiene tu vida — aunque sea pequeño.","A veces, lo más valioso ya está presente."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse o recostarse cómodamente. Guía unas respiraciones lentas para relajar el cuerpo y aquietar la mente antes de entrar en la meditación."],"citas":[],"preguntas":[],"nota":null},{"id":"meditacion-de-gratitud","nombre":"Meditación de gratitud","tipo":"desarrollo","tiempo":{"min":15,"max":25,"texto":"15 – 25 minutos"},"pasos":["Guía al grupo a través de las áreas de gratitud usando las frases suaves. Dedica unos minutos a cada área, invitando a conectar no solo con pensamientos sino también con las emociones y sensaciones que aparecen."],"citas":["La gratitud no es negación del dolor — es la capacidad de ver también lo que sostiene, incluso cuando duele."],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Deja unos minutos de silencio para integrar. Puedes invitar a escribir una palabra, una frase o una reflexión breve sobre lo que emergió durante la práctica."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen comparten una palabra o momento de gratitud. Cierra con una respiración colectiva de reconocimiento hacia lo que cada uno lleva en la vida."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Diferencia gratitud de pensamiento positivo — la gratitud genuina puede coexistir con el dolor y no lo niega.","origen":"fuente"},{"texto":"Habla lento y deja pausas largas — la gratitud necesita tiempo para descender de la mente al corazón y al cuerpo.","origen":"fuente"},{"texto":"Esta dinámica funciona muy bien como apertura del día — la gratitud pone al grupo en un estado receptivo y abierto para lo que viene.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[107,108],"rol":"principal"},{"archivo":"edicion2","paginas":[98,99],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Luminosa · Receptiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":30,"max":43},"orden":50},{"id":"el-puente-de-la-confianza","version":1,"estado":"revision","motivoEstado":"Requiere revisión: la recomendación 02 está cortada en la fuente y la dinámica propone recorridos con vendas opcionales y «sostener» al compañero sin precisar la técnica.","titulo":"El Puente de la Confianza","subtitulo":"Una experiencia para fortalecer la entrega, el apoyo y la conexión humana dentro del grupo","resumen":"Una experiencia para fortalecer la entrega, el apoyo y la conexión humana dentro del grupo","contexto":"Confiar implica, muchas veces, permitirnos sostener y ser sostenidos por otros. Esta dinámica invita a los participantes a explorar la confianza desde la presencia, el cuidado mutuo y la experiencia compartida — fortaleciendo la conexión humana dentro del grupo.","objetivo":"Explorar la confianza interpersonal a través de ejercicios cooperativos donde los participantes practican sostener y ser sostenidos, acompañar y dejarse acompañar.","momentos":["conexion"],"temas":["confianza","cooperación","parejas"],"formato":["parejas"],"tipoFuente":"Parejas · Vivencial","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Vincular · Presencial","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"ambos","amplio":true,"texto":"Amplio · Seguro"},"participantes":null,"materiales":[{"texto":"Espacio amplio sin obstáculos","ids":[],"opcional":false},{"texto":"Pañuelos o vendas para los ojos (opcional)","ids":["vendas"],"opcional":true},{"texto":"Música suave de fondo","ids":["musica"],"opcional":false},{"texto":"Agua disponible","ids":["agua"],"opcional":false}],"ambiente":["Espacio amplio sin obstáculos"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien no quiera trabajar en pareja puede hacer la práctica de forma individual o acompañar como observador.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Detén el recorrido si alguien con los ojos cubiertos muestra miedo o pierde el equilibrio; puede seguir con los ojos abiertos.","origen":"adaptacion"},{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["camino-de-la-confianza"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Inspecciona el espacio antes — retira todo obstáculo que pueda representar un riesgo para quienes se mueven con atención reducida.","origen":"fuente"}],"experiencia":"avanzada","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Las 4 experiencias de la confianza","tipo":"lista","items":["Confiar · Soltar el control — Permitirse ser guiado, sostenido o acompañado sin necesitar controlar cada paso del camino.","Recibir apoyo · Aceptar el cuidado — Observar cómo se siente cuando alguien más sostiene el camino — sin minimizarlo ni desviarlo.","Acompañar · Sostener al otro — La responsabilidad y el cuidado de guiar desde la presencia y la atención consciente.","Soltar el control · Entregarse al proceso — Dejar que la experiencia ocurra sin necesidad de dirigirla, predecirla ni protegerse de ella."]},{"titulo":"Preguntas de integración","tipo":"preguntas","items":["¿Cómo se sintió confiar en otra persona — qué apareció en ti?","¿Qué emergió cuando tuviste que sostener o acompañar a alguien más?","¿Qué aprendiste sobre tu relación con el control y la vulnerabilidad?"],"nota":"La intención no es \"superar una prueba\" — sino observar lo que surge al confiar, recibir apoyo, acompañar y soltar el control. Todo eso es información valiosa."},{"titulo":"Frases para acompañar","tipo":"frases","items":["Confía en el ritmo de la experiencia — no necesitas saber adónde va.","Permite que el apoyo también forme parte del camino.","A veces, la confianza se construye en los momentos más simples."]}],"fases":[{"id":"presentacion-y-seguridad","nombre":"Presentación y seguridad","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Presenta la intención y forma las parejas. Recuerda la importancia de respetar los límites físicos y emocionales de cada participante en todo momento."],"citas":[],"preguntas":[],"nota":null},{"id":"ejercicios-cooperativos","nombre":"Ejercicios cooperativos","tipo":"desarrollo","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["Realiza recorridos guiados, movimientos sincronizados o pequeños desafíos cooperativos donde una persona acompaña y sostiene a la otra. Intercambia los roles después de cada ejercicio."],"citas":["Ser sostenido por otro también requiere valentía — la valentía de soltar el control."],"preguntas":[],"nota":null},{"id":"reflexion-en-parejas","nombre":"Reflexión en parejas","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Invita a cada pareja a compartir brevemente entre sí cómo se sintieron en cada rol antes de regresar al grupo."],"citas":[],"preguntas":[],"nota":null},{"id":"cierre-grupal","nombre":"Cierre grupal","tipo":"cierre","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Reúne al grupo para compartir desde las preguntas de integración. Cierra con una respiración colectiva de reconocimiento hacia la confianza que se cultivó juntos."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Forma las parejas con intención — a veces, la confianza más significativa emerge entre personas que aún no se [texto cortado en la fuente]","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[109,110],"rol":"principal"},{"archivo":"edicion2","paginas":[100,101],"rol":"contraste"}],"correcciones":[],"incidencias":[{"tipo":"texto_cortado","severidad":"media","detalle":"La recomendación 02 termina a mitad de frase («…personas que aún no se») y no hay recomendación 03. La Edición 2 (p. 101) trae el cierre completo de la dinámica."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Vincular · Presencial."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":59},"orden":51},{"id":"ritual-de-renacimiento","version":1,"estado":"revision","motivoEstado":"La ficha del PDF principal termina tras las preguntas de reflexión. El desarrollo se recuperó de la Edición 2 (pp. 102–103), sin tiempos por fase: pendiente de aprobación.","titulo":"Ritual de Renacimiento","subtitulo":"Una experiencia simbólica para cerrar etapas y abrir espacio para nuevos comienzos","resumen":"Una experiencia simbólica para cerrar etapas y abrir espacio para nuevos comienzos","contexto":"Hay momentos en la vida donde sentimos que algo dentro de nosotros está listo para cambiar. Esta dinámica invita a los participantes a reconocer aquello que desean dejar atrás y conectar con una nueva etapa desde la intención, la presencia y la transformación consciente.","objetivo":"Crear un espacio ceremonial para cerrar conscientemente lo que ya no sirve y abrir intención hacia una nueva etapa, usando el simbolismo del renacimiento como marco de transformación personal.","momentos":["cierre","exploracion"],"temas":["renacimiento","soltar","ritual","fuego"],"formato":["individual","grupo"],"tipoFuente":"Individual · Ritual","duracion":{"min":60,"max":75,"texto":"60 – 75 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Transformadora · Sagrada","momentoFuente":"Cierre del retiro","enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Papel, bolígrafos y tarjetas","ids":["papel","boligrafos","tarjetas"],"opcional":false},{"texto":"Velas e iluminación íntima","ids":["velas"],"opcional":false},{"texto":"Música suave y ceremonial","ids":["musica"],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Ofrece siempre una alternativa sin fuego (romper, enterrar o guardar el papel) para quien prefiera no usarlo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"},{"texto":"Si el fuego se vuelve difícil de controlar (viento, chispas), suspende el acto con fuego y pasa a la alternativa sin fuego.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ritual-de-liberacion","circulo-de-cierre-del-retiro"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Lo que se suelta · Lo que se abre","tipo":"lista","items":["Un hábito que me limita → Un hábito que me expande","Un miedo que me frena → Una valentía que me mueve","Una creencia que me contrae → Una posibilidad que me libera","Una relación que me pesa → Un vínculo que me nutre"],"nota":"La tabla es una guía — cada participante encuentra sus propios pares de soltar y abrir. No es necesario trabajar todos los ejemplos."},{"titulo":"Preguntas para la reflexión","tipo":"preguntas","items":["¿Qué parte de mi vida está pidiendo un nuevo comienzo?","¿Qué necesito dejar atrás para avanzar con más claridad?","¿Qué versión de mí quiero comenzar a construir desde hoy?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo (recuperado de la Edición 2)","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente íntimo y significativo, acompañado de velas, música suave, elementos naturales o iluminación tenue que favorezca la introspección y la conexión emocional.","Comienza guiando unas respiraciones profundas para ayudar al grupo a relajarse y conectar con el momento presente.","Después, invita a cada participante a reflexionar sobre aquello que sienten listo para finalizar: hábitos, miedos, creencias, emociones o etapas personales que ya no desean seguir sosteniendo.","Entrega papel y bolígrafos para que cada persona pueda escribir aquello que desea soltar y aquello que desea abrir en esta nueva etapa.","La experiencia puede cerrarse con un gesto simbólico: quemar el papel de forma segura, enterrarlo, guardarlo en un espacio especial o simplemente sostenerlo durante unos minutos de silencio consciente.","Al finalizar, invita al grupo a respirar profundamente y conectar con la sensación de apertura, renovación y posibilidad."],"citas":[],"preguntas":["¿Qué parte de mi vida está pidiendo un nuevo comienzo?","¿Qué necesito dejar atrás para avanzar con más claridad?","¿Qué versión de mí quiero comenzar a construir?"],"nota":"La intención no es “convertirse en alguien diferente”, sino reconocer que el cambio también forma parte natural del crecimiento personal.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[111,112],"rol":"principal"},{"archivo":"edicion2","paginas":[102,103],"rol":"recuperacion"}],"correcciones":[],"incidencias":[{"tipo":"incompleta","severidad":"alta","detalle":"Página 112: faltan desarrollo, integración, cierre y recomendaciones en el PDF principal."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Transformadora · Sagrada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente-ed2","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":52},{"id":"circulo-de-presencia","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Presencia","subtitulo":"Una experiencia para reconectar con el momento presente y la energía compartida del grupo","resumen":"Una experiencia para reconectar con el momento presente y la energía compartida del grupo","contexto":"Muchas veces, el simple hecho de detenernos y estar realmente presentes ya transforma la manera en que vivimos una experiencia. Esta dinámica invita a los participantes a desacelerar, observar y compartir un espacio de conexión consciente sin necesidad de hacer demasiado.","objetivo":"Crear un espacio de reconexión con el momento presente a través de la observación consciente, el silencio compartido y la conexión grupal sin necesidad de llenar el espacio con palabras o actividad.","momentos":["apertura","integracion"],"temas":["presencia","silencio","atención plena"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Quieta · Conectora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio en círculo con iluminación suave","ids":[],"opcional":false},{"texto":"Vela central o elemento natural","ids":["vela-central"],"opcional":false},{"texto":"Sin música — el silencio es el ambiente","ids":["musica"],"opcional":false},{"texto":"Esterillas o cojines para sentarse","ids":["cojines-esterillas"],"opcional":false}],"ambiente":["Espacio en círculo con iluminación suave"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Como transición entre dinámicas intensas: devuelve al grupo al cuerpo y al presente cuando la mente se ha activado demasiado.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["circulo-de-silencio-consciente","meditacion-respiracion-consciente"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Los 4 focos de la presencia consciente","tipo":"lista","items":["La respiración — El ritmo natural del aliento — la señal más directa de que estamos vivos en este instante.","Las sensaciones — Lo que el cuerpo siente — temperatura, contacto, peso, tensión o ligereza.","Los sonidos — Lo que llega sin buscarlo — el entorno que existe independientemente del pensamiento.","La energía del grupo — La presencia de los demás — sentir que no estamos solos en este momento compartido."],"nota":"La intención no es llegar a un estado perfecto de meditación — sino permitir que cada participante vuelva al presente desde una experiencia simple y humana."},{"titulo":"Frases para guiar la presencia","tipo":"frases","items":["No necesitas hacer más de lo que ya estás haciendo.","Permite que este momento exista tal como es.","La presencia no es una técnica — es una elección que se renueva en cada respiración."]}],"fases":[{"id":"apertura","nombre":"Apertura","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse en círculo con los ojos cerrados. Presenta los cuatro focos de observación y guía unas respiraciones lentas para llegar al presente antes de comenzar."],"citas":[],"preguntas":[],"nota":null},{"id":"silencio-de-presencia","nombre":"Silencio de presencia","tipo":"desarrollo","tiempo":{"min":15,"max":25,"texto":"15 – 25 minutos"},"pasos":["Guía al grupo suavemente a través de los cuatro focos — respiración, sensaciones, sonidos y energía compartida — con voz muy pausada y largas pausas de silencio entre cada uno."],"citas":["Estar presente juntos, sin necesidad de llenar el silencio, es una de las formas más profundas de conexión humana."],"preguntas":[],"nota":null},{"id":"retorno-suave","nombre":"Retorno suave","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita a regresar lentamente — mover los dedos, abrir los ojos despacio. Unos momentos de silencio consciente antes de que el grupo empiece a hablar."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Quienes lo deseen comparten una palabra o sensación que se llevan del espacio de presencia. Cierra con una respiración colectiva de gratitud por el momento compartido."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Esta es una de las dinámicas más simples del libro — y por eso también una de las más poderosas. No la \"enriquezcas\" demasiado con contenido adicional.","origen":"fuente"},{"texto":"Habla más lento de lo que crees necesario — la presencia necesita espacio y silencio para instalarse, no instrucciones constantes.","origen":"fuente"},{"texto":"Funciona excelente como transición entre dinámicas intensas — devuelve al grupo al cuerpo y al presente cuando la mente se ha activado demasiado.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[113,114],"rol":"principal"},{"archivo":"edicion2","paginas":[104,105],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Quieta · Conectora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":30,"max":43},"orden":53},{"id":"meditacion-del-corazon-abierto","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Meditación del Corazón Abierto","subtitulo":"Una práctica para conectar con la empatía, la sensibilidad y la apertura emocional","resumen":"Una práctica para conectar con la empatía, la sensibilidad y la apertura emocional","contexto":"Cuando nos permitimos bajar las defensas por un momento, también aparece la posibilidad de conectar de manera más auténtica con nosotros mismos y con los demás. Esta meditación invita a abrir un espacio de calma y presencia enfocado en el corazón — favoreciendo la empatía, la compasión y la conexión interior.","objetivo":"Guiar a los participantes hacia una apertura emocional consciente, conectando con el corazón como centro de empatía, compasión y conexión auténtica con uno mismo y con los demás.","momentos":["exploracion","conexion"],"temas":["corazón","empatía","meditación"],"formato":["grupo"],"tipoFuente":"Grupal · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Suave · Receptiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Cojines o esterillas para sentarse","ids":["cojines-esterillas"],"opcional":false},{"texto":"Música suave e instrumental","ids":["musica"],"opcional":false},{"texto":"Iluminación cálida y tenue","ids":[],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":["Iluminación cálida y tenue"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Como preparación para dinámicas de mayor profundidad emocional: abre el terreno de la receptividad antes del trabajo más intenso.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["meditacion-de-la-compasion-universal","el-templo-del-utero"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Las capas de apertura del corazón","tipo":"lista","items":["Relajar las defensas · Primer movimiento — Soltar la tensión del pecho. Dejar que los hombros bajen, que la respiración se haga más lenta y amplia.","Conectar con el corazón · Segundo movimiento — Llevar la atención y quizás la mano al pecho. Observar lo que hay allí — emociones, recuerdos, sensaciones.","Expandir la apertura · Tercer movimiento — Desde el corazón, conectar con personas o experiencias que despiertan amor, gratitud o compasión."],"nota":"La intención no es forzar emociones intensas — sino permitir que aparezca una sensación más profunda de apertura y conexión. Lo que emerge, aunque sea sutil, es suficiente."},{"titulo":"Frases para guiar la meditación","tipo":"frases","items":["Respira con suavidad y permite que el corazón se abra sin esfuerzo.","No necesitas protegerte de todo en este momento.","La sensibilidad también puede ser una forma de fortaleza."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse cómodamente y comenzar con respiraciones lentas y profundas para aquietar la mente y relajar el cuerpo antes de guiar la atención al corazón."],"citas":[],"preguntas":[],"nota":null},{"id":"meditacion-del-corazon","nombre":"Meditación del corazón","tipo":"desarrollo","tiempo":{"min":20,"max":30,"texto":"20 – 30 minutos"},"pasos":["Guía las tres capas de apertura de forma suave y pausada. Invita a observar las emociones, recuerdos o sensaciones que aparecen desde el centro del pecho sin juzgarlas ni forzarlas."],"citas":["Un corazón abierto no es un corazón sin protección — es un corazón que elige confiar en este momento."],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Deja unos minutos de silencio para integrar. Invita a regresar lentamente, manteniendo la mano en el pecho si lo desean."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen comparten una palabra o sensación que se llevan. Cierra con una respiración colectiva de apertura y gratitud."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Habla con una voz especialmente suave en esta meditación — el tono del facilitador es el primer modelo de apertura que el grupo recibe.","origen":"fuente"},{"texto":"Si alguien llora, es bienvenido — el corazón que se abre también puede soltar lo que estaba guardado. Ten pañuelos disponibles y sostén el espacio con calma.","origen":"fuente"},{"texto":"Esta práctica funciona como preparación para dinámicas de mayor profundidad emocional — abre el terreno de la receptividad antes de que llegue el trabajo más intenso.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[115,116],"rol":"principal"},{"archivo":"edicion2","paginas":[112,113],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Suave · Receptiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":35,"max":48},"orden":54},{"id":"circulo-de-reflexion-nocturna","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Reflexión Nocturna","subtitulo":"Un espacio para integrar emociones, aprendizajes y conversaciones al final del día","resumen":"Un espacio para integrar emociones, aprendizajes y conversaciones al final del día","contexto":"Las noches dentro de un retiro suelen abrir momentos de mayor sensibilidad, honestidad y conexión emocional. Esta dinámica invita al grupo a cerrar el día desde la calma y la reflexión compartida, permitiendo que las experiencias vividas encuentren un espacio de integración consciente.","objetivo":"Crear un espacio de cierre consciente al final de cada día del retiro, donde el grupo pueda compartir reflexiones, emociones y aprendizajes desde la calma y la autenticidad.","momentos":["integracion","cierre"],"temas":["reflexión","noche","círculo"],"formato":["grupo"],"tipoFuente":"Grupal · Círculo","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Calmada · Integradora","momentoFuente":"Cierre del día","enfoqueFuente":null,"espacio":{"tipo":"ambos"},"participantes":null,"materiales":[{"texto":"Velas, fogata o iluminación muy tenue","ids":["velas","fogata"],"opcional":false},{"texto":"Espacio en círculo íntimo","ids":[],"opcional":false},{"texto":"Sin música o música muy suave de fondo","ids":["musica"],"opcional":false},{"texto":"Mantas o ropa abrigada si es exterior","ids":["mantas","ropa-abrigo"],"opcional":false}],"ambiente":["Espacio en círculo íntimo"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"Al final de cada día del retiro; es un cierre, no una apertura.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["meditacion-de-reconexion-interior","circulo-de-cierre-del-retiro"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"}],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Lo que el grupo puede compartir esta noche","tipo":"lista","items":["Un aprendizaje importante que emergió durante el día","Una emoción presente que necesita ser nombrada","Una experiencia o momento que dejó huella","Aquello que desean llevar consigo mañana"]},{"titulo":"Preguntas para abrir la reflexión","tipo":"preguntas","items":["¿Qué momento del día dejó más huella en ti?","¿Qué emoción necesitas reconocer esta noche?","¿Qué descubriste hoy sobre ti mismo?"],"nota":"La intención no es analizar ni debatir — sino permitir que las palabras aparezcan desde la autenticidad y la presencia. Una o dos frases honestas son suficientes."}],"fases":[{"id":"desaceleracion","nombre":"Desaceleración","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse en círculo y comenzar con unos minutos de silencio o respiración consciente para desacelerar después de las actividades del día."],"citas":[],"preguntas":[],"nota":null},{"id":"reflexion-compartida","nombre":"Reflexión compartida","tipo":"integracion","tiempo":{"min":20,"max":30,"texto":"20 – 30 minutos"},"pasos":["Abre el espacio de conversación relajada usando las preguntas guía o las categorías de compartir. Cada persona habla cuando siente que quiere — sin turno forzado."],"citas":["Cerrar el día con presencia transforma la manera en que integramos lo vivido — y lo que dormimos también digiere."],"preguntas":[],"nota":null},{"id":"cierre-nocturno","nombre":"Cierre nocturno","tipo":"cierre","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Cierra con unos minutos de silencio, una respiración colectiva o una breve meditación relajante para preparar el cuerpo y la mente para el descanso."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Mantén la energía baja y relajada — esta dinámica es un cierre, no una apertura. El objetivo es calmar, no activar.","origen":"fuente"},{"texto":"Si la fogata o el exterior son posibles, úsalos — el fuego y el cielo nocturno crean de forma natural la atmósfera perfecta para este tipo de conversación.","origen":"fuente"},{"texto":"No alargues demasiado esta dinámica — 30 a 40 minutos es suficiente. El grupo necesita descanso para integrar lo vivido durante el sueño.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[117,118],"rol":"principal"},{"archivo":"edicion2","paginas":[114,115],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Calmada · Integradora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":30,"max":43},"orden":55},{"id":"ritual-de-agradecimiento-al-cuerpo","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Ritual de Agradecimiento al Cuerpo","subtitulo":"Una experiencia para reconectar con el cuerpo desde el cuidado, la presencia y la gratitud","resumen":"Una experiencia para reconectar con el cuerpo desde el cuidado, la presencia y la gratitud","contexto":"Muchas veces atravesamos la vida exigiéndole demasiado al cuerpo y escuchándolo muy poco. Esta dinámica invita a los participantes a detenerse y reconocer todo aquello que el cuerpo sostiene, expresa y acompaña cada día — desde la gratitud y sin exigencia.","objetivo":"Desarrollar una relación más amorosa y consciente con el propio cuerpo, reconociendo todo lo que sostiene y expresa cada día, y cultivando un vínculo de cuidado, respeto y gratitud hacia uno mismo.","momentos":["integracion","exploracion"],"temas":["cuerpo","gratitud","autocuidado"],"formato":["individual"],"tipoFuente":"Individual · Meditación","duracion":{"min":40,"max":55,"texto":"40 – 55 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Tierna · Sanadora","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Esterillas o mantas para recostarse","ids":["cojines-esterillas","mantas"],"opcional":false},{"texto":"Música suave e instrumental","ids":["musica"],"opcional":false},{"texto":"Iluminación cálida y tenue","ids":[],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":["Iluminación cálida y tenue"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[{"texto":"Con grupos de alta autoexigencia (deportistas, profesionales del cuidado o personas en procesos de recuperación física o emocional).","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["escaneo-corporal","meditacion-del-corazon-abierto"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Ten pañuelos y un rincón tranquilo aparte para quien necesite una pausa.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Zonas del cuerpo y lo que han sostenido","tipo":"lista","items":["La mente y la cabeza · Pensar, decidir, recordar — Gracias por procesar, por buscar soluciones, por no rendirse.","El pecho y el corazón · Sentir, amar, resistir — Gracias por latir, por abrirse, por seguir eligiendo amar.","Los pulmones y la respiración · Respirar sin ser pedido — Gracias por respirar sin descanso, por sostener la vida en cada instante.","Las manos y los brazos · Crear, dar, abrazar — Gracias por todo lo que has construido, sostenido y ofrecido.","Los pies y las piernas · Caminar, sostenerse, avanzar — Gracias por llevarme hasta aquí — por cada paso dado incluso en los momentos difíciles."]},{"titulo":"Frases para guiar la meditación","tipo":"frases","items":["Agradece a tu cuerpo por todo lo que ha sostenido hasta hoy.","Escucha tu cuerpo sin exigencia ni juicio — solo presencia.","Tu cuerpo también merece descanso, cuidado y compasión."]},{"titulo":"Variantes para enriquecer la práctica","tipo":"lista","items":["A · Escritura — al finalizar la meditación, escribir una carta breve de agradecimiento al propio cuerpo.","B · Automasaje consciente — invitar a los participantes a acariciar o masajear suavemente sus propias manos, brazos o pies mientras agradecen.","C · Silencio integrador — simplemente permanecer en quietud con las manos sobre el corazón unos minutos finales."],"nota":"Personas con relaciones difíciles con su cuerpo — trastornos alimentarios, enfermedades, traumas físicos — pueden sentir emociones intensas. Sostén el espacio con especial cuidado y sin forzar la experiencia."}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a recostarse o sentarse cómodamente. Guía unas respiraciones lentas para comenzar a soltar la tensión del cuerpo antes de dirigir la atención hacia él desde la gratitud."],"citas":[],"preguntas":[],"nota":null},{"id":"recorrido-corporal","nombre":"Recorrido corporal","tipo":"desarrollo","tiempo":{"min":25,"max":30,"texto":"25 – 30 minutos"},"pasos":["Guía al grupo a través de cada zona del cuerpo usando las frases de gratitud. Dedica 4 a 5 minutos a cada zona — más tiempo en las que percibas mayor necesidad de atención en el grupo."],"citas":["El cuerpo no es un obstáculo que superar — es el hogar desde donde vivimos cada experiencia."],"preguntas":[],"nota":null},{"id":"variante-e-integracion","nombre":"Variante e integración","tipo":"integracion","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Elige una de las tres variantes según el grupo y el tiempo disponible. Permite que cada persona conecte con una sensación de mayor cuidado y respeto hacia sí misma."],"citas":[],"preguntas":[],"nota":null},{"id":"compartir","nombre":"Compartir","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Quienes lo deseen comparten qué zona o emoción emergió con más fuerza. Cierra con una respiración colectiva de gratitud hacia el propio cuerpo."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Habla desde la ternura — el tono de esta dinámica es el más suave y cuidadoso de todo el retiro. No hay espacio para ningún mensaje de exigencia o mejora personal.","origen":"fuente"},{"texto":"Incluye en la guía momentos de silencio largos donde el participante pueda simplemente sentir sin seguir instrucciones — la escucha sin dirección también es parte de agradecer.","origen":"fuente"},{"texto":"Esta dinámica es especialmente poderosa para grupos con alta autoexigencia — deportistas, profesionales del cuidado o personas en procesos de recuperación física o emocional.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[119,120],"rol":"principal"},{"archivo":"edicion2","paginas":[118,119],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Tierna · Sanadora."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":43,"max":50},"orden":56},{"id":"circulo-de-cierre-del-retiro","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Círculo de Cierre del Retiro","subtitulo":"Una experiencia para honrar el proceso vivido y despedirse desde la conexión, la gratitud y la presencia","resumen":"Una experiencia para honrar el proceso vivido y despedirse desde la conexión, la gratitud y la presencia","contexto":"Todo retiro deja algo dentro de quienes lo viven. Conversaciones, emociones, aprendizajes y momentos compartidos que muchas veces continúan transformándose incluso después de que la experiencia termina. Esta dinámica invita al grupo a cerrar desde un espacio de integración consciente — reconociendo lo vivido y despidiéndose con gratitud y humanidad.","objetivo":"Crear un espacio ceremonial de cierre que permita al grupo honrar el proceso vivido, compartir desde la autenticidad y despedirse desde la presencia — llevando consigo lo más significativo de la experiencia.","momentos":["cierre"],"temas":["cierre","gratitud","despedida","círculo"],"formato":["grupo"],"tipoFuente":"Grupal · Círculo","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Gratitud · Conexión","momentoFuente":"Cierre del retiro","enfoqueFuente":null,"espacio":{"tipo":"ambos"},"participantes":null,"materiales":[{"texto":"Velas, fogata o iluminación íntima","ids":["velas","fogata"],"opcional":false},{"texto":"Música suave o silencio ceremonial","ids":["musica"],"opcional":false},{"texto":"Tarjetas o papel para escribir (opcional)","ids":["papel","tarjetas"],"opcional":true},{"texto":"Elementos simbólicos del retiro","ids":["elementos-simbolicos"],"opcional":false}],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Pide permiso antes de cualquier contacto físico y ofrece una alternativa sin contacto (una mano en el propio pecho, una inclinación de cabeza o una mirada).","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ritual-de-gratitud-colectiva","circulo-de-reconocimiento-y-alabanza"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Lo que cada persona puede ofrecer al círculo","tipo":"lista","items":["Un aprendizaje importante que emerge de la experiencia del retiro","Una emoción presente en este momento de cierre","Algo que agradece del grupo o del proceso compartido","Aquello que desea llevar consigo más allá del retiro"]},{"titulo":"Gestos de cierre posibles","tipo":"lista","items":["Abrazo grupal — cerrar físicamente el círculo que se abrió al inicio del retiro","Apagar juntos la vela central — el fuego del retiro se apaga, pero la luz sigue dentro","Carta de cierre — escribir una palabra o frase que se llevan como recordatorio","Respiración colectiva final — inhalar juntos lo vivido, exhalar juntos la despedida"],"nota":"No hay palabras perfectas para cerrar un retiro — permite que los silencios, las lágrimas y la emoción también formen parte del cierre. Todo eso es integración."},{"titulo":"Frases para acompañar el cierre","tipo":"frases","items":["Todo proceso necesita tiempo para integrarse — lo vivido aquí seguirá transformándote.","A veces, los encuentros más simples dejan las transformaciones más profundas.","Lo vivido aquí puede seguir acompañándote mucho más allá del retiro."]}],"fases":[{"id":"apertura-ceremonial","nombre":"Apertura ceremonial","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Reúne al grupo en círculo y crea el ambiente íntimo. Comienza con unos minutos de silencio compartido o respiración consciente para desacelerar y llegar presentes al cierre."],"citas":[],"preguntas":[],"nota":null},{"id":"el-circulo-de-ofrendas","nombre":"El círculo de ofrendas","tipo":"desarrollo","tiempo":{"min":25,"max":35,"texto":"25 – 35 minutos"},"pasos":["Invita a cada persona a compartir desde las cuatro categorías — aprendizaje, emoción, gratitud e intención. No hay turno forzado — cada quien habla cuando siente que es su momento."],"citas":["Un retiro no termina cuando el grupo se despide — termina cuando lo vivido se integra en la vida de cada uno."],"preguntas":[],"nota":null},{"id":"gesto-de-cierre","nombre":"Gesto de cierre","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Elige uno de los cuatro gestos de cierre según el espíritu del grupo y del retiro. Permite que el silencio, la emoción y la gratitud coexistan sin intentar llenarlos."],"citas":[],"preguntas":[],"nota":null},{"id":"despedida","nombre":"Despedida","tipo":"cierre","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Cierra con una última respiración colectiva. Quienes lo deseen se abrazan, se miran o simplemente permanecen un momento más en presencia antes de salir."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Cuida especialmente tu propio estado en este cierre — los grupos tienden a espejear la emoción del facilitador. Tu presencia tranquila y gratitud genuina sostiene el espacio de todos.","origen":"fuente"},{"texto":"No apures el cierre — deja que el tiempo necesario fluya. Un cierre apresurado deja al grupo sin integrar lo más importante.","origen":"fuente"},{"texto":"Recuerda al grupo que la integración continúa después del retiro — los sueños, las conversaciones y los días siguientes también son parte del proceso.","origen":"fuente"}],"variantes":[{"id":"ed2-60","titulo":"Versión narrativa (Edición 2, «Cierre de Integración Colectiva»)","tituloFuente":"Cierre de Integración Colectiva","estado":"revision","fuente":{"archivo":"edicion2","paginas":[126,127]},"nota":"Versión narrativa del Círculo de Cierre del Retiro: mismo texto de apertura y mismas cuatro categorías para compartir.","subtitulo":null,"contexto":null,"fases":[]},{"id":"ed2-65","titulo":"Versión narrativa (Edición 2, «Ceremonia de Cierre Final»)","tituloFuente":"Ceremonia de Cierre Final","estado":"revision","fuente":{"archivo":"edicion2","paginas":[136,137]},"nota":"Prácticamente la misma propuesta que el Círculo de Cierre del Retiro y el Cierre de Integración Colectiva (apertura en círculo, compartir aprendizaje/emoción/gratitud/intención, gesto simbólico colectivo).","subtitulo":null,"contexto":null,"fases":[]},{"id":"ed2-30","titulo":"Variante de cierre y renacimiento (Edición 2, «Ritual de Cierre y Renacimiento»)","tituloFuente":"Ritual de Cierre y Renacimiento","estado":"revision","fuente":{"archivo":"edicion2","paginas":[66,67]},"nota":"Comparte la estructura central del Círculo de Cierre del Retiro (círculo, reflexión sobre lo vivido, compartir una palabra o intención, gesto colectivo). Se registra como variante.","subtitulo":"Un momento para integrar la experiencia vivida y abrir espacio para una nueva etapa","contexto":"Todo proceso profundo merece un cierre consciente. Esta dinámica invita a los participantes a reconocer lo vivido durante el retiro, integrar los aprendizajes obtenidos y despedir esta etapa desde la gratitud, la presencia y la intención de continuar creciendo.","fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente cálido y simbólico, acompañado de velas, música suave o elementos naturales que ayuden a crear una atmósfera íntima y significativa.","Invita al grupo a sentarse en círculo y comenzar con unos minutos de silencio o respiración consciente para conectar con la experiencia compartida.","Después, guía una breve reflexión sobre todo aquello que cada persona descubrió, soltó o transformó durante el retiro.","Invita a cada participante a compartir una palabra, intención o reflexión que represente aquello que hoy desean integrar en sus vidas.","Puedes finalizar la experiencia con un pequeño ritual colectivo: encender una vela, realizar una respiración grupal, un abrazo consciente o unos segundos de silencio compartido."],"citas":[],"preguntas":["¿Qué aprendizaje deseas llevar contigo después de esta experiencia?","¿Qué parte de ti sientes más despierta o fortalecida?","¿Qué nueva etapa deseas comenzar a construir?"],"nota":"La intención no es cerrar “perfectamente”, sino reconocer que algo dentro de cada persona ya comenzó a transformarse."}]}],"fuentes":[{"archivo":"principal","paginas":[121,122],"rol":"principal"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Gratitud · Conexión."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":58},"orden":57},{"id":"ritual-de-intencion-al-amanecer","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Ritual de Intención al Amanecer","subtitulo":"Una experiencia para comenzar una nueva etapa desde la claridad, la presencia y la intención consciente","resumen":"Una experiencia para comenzar una nueva etapa desde la claridad, la presencia y la intención consciente","contexto":"El amanecer simboliza nuevos comienzos. La calma de las primeras horas puede convertirse en un momento poderoso para conectar con aquello que deseamos cultivar, transformar o atraer a nuestra vida de manera más consciente. Esta dinámica invita a los participantes a iniciar el día desde la introspección y la intención.","objetivo":"Crear un espacio de conexión interior al amanecer donde los participantes puedan clarificar y sembrar intenciones conscientes para la nueva etapa que comienza — ya sea el día, el retiro o la vida posterior a él.","momentos":["apertura","cierre"],"temas":["intención","amanecer","naturaleza"],"formato":["individual","grupo"],"tipoFuente":"Individual · Naturaleza","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":null,"energiaFuente":"Clara · Intencional","momentoFuente":"Inicio o cierre del retiro","enfoqueFuente":null,"espacio":{"tipo":"exterior"},"participantes":null,"materiales":[{"texto":"Papel y bolígrafos para escribir la intención","ids":["papel","boligrafos"],"opcional":false},{"texto":"Espacio al aire libre con vista al horizonte","ids":[],"opcional":false},{"texto":"Ropa abrigada — las madrugadas suelen ser frías","ids":["ropa-abrigo"],"opcional":false},{"texto":"Silencio como ambiente principal","ids":[],"opcional":false}],"ambiente":["Espacio al aire libre con vista al horizonte","Silencio como ambiente principal"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Si alguien no puede o no quiere caminar o salir, ofrece un lugar cómodo desde donde participar.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Acorta o suspende el recorrido ante frío, calor intenso, terreno inseguro o cansancio del grupo.","origen":"adaptacion"}],"cuandoUtilizar":[{"texto":"Al inicio del retiro orienta el proceso; al final lo consolida y lo lleva de regreso a la vida cotidiana.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["ceremonia-de-intenciones","circulo-de-compartir-intenciones"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Recorre el lugar antes de la actividad: terreno, sombra, abrigo y un punto de reunión claro.","origen":"adaptacion"}],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Las tres preguntas de intención","tipo":"preguntas","items":["¿Qué energía quiero cultivar en esta nueva etapa de mi vida?","¿Qué intención deseo sostener después de este retiro?","¿Cómo quiero comenzar a relacionarme conmigo y con mi vida a partir de ahora?"]},{"titulo":"Formas de sostener la intención","tipo":"lista","items":["Escribirla en un papel y guardarla en un lugar visible al regresar a casa","Compartirla brevemente con el grupo como compromiso colectivo","Conservarla en silencio — íntima y sagrada, sin compartir","Depositar el papel en la tierra o en la naturaleza como ofrenda simbólica"],"nota":"Una intención no es un objetivo a lograr — es una dirección a habitar. La diferencia es importante: los objetivos se evalúan, las intenciones se viven."},{"titulo":"Frases para acompañar la práctica","tipo":"frases","items":["La intención no es un destino — es la forma en que eliges caminar.","Permite que este amanecer sea el primer día de la versión de ti que estás eligiendo ser.","La claridad no siempre llega con palabras — a veces llega como una sensación que ya sabes que es verdad."]}],"fases":[{"id":"silencio-contemplativo","nombre":"Silencio contemplativo","tipo":"desarrollo","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["El grupo permanece en silencio observando cómo aparece la luz del amanecer. Sin instrucciones — solo presencia. El silencio compartido es el primer gesto de intención."],"citas":[],"preguntas":[],"nota":null},{"id":"respiracion-e-introspeccion","nombre":"Respiración e introspección","tipo":"desarrollo","tiempo":{"min":10,"max":10,"texto":"10 minutos"},"pasos":["Guía unas respiraciones conscientes e invita a cada persona a dirigir la atención hacia adentro — observando qué emerge naturalmente antes de hacer la pregunta de intención."],"citas":["El amanecer no pregunta si estás listo — simplemente llega. La intención también puede ser así."],"preguntas":[],"nota":null},{"id":"escritura-de-la-intencion","nombre":"Escritura de la intención","tipo":"desarrollo","tiempo":{"min":10,"max":15,"texto":"10 – 15 minutos"},"pasos":["Entrega papel y bolígrafos. Invita a responder las tres preguntas en silencio — o simplemente a escribir una palabra, frase o imagen que represente su nueva dirección."],"citas":[],"preguntas":[],"nota":null},{"id":"gesto-y-compartir","nombre":"Gesto y compartir","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Cada persona elige cómo sostener su intención según las cuatro opciones. Quienes lo deseen comparten. Cierra con una respiración colectiva de apertura hacia el nuevo comienzo."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Cuida la distinción entre intención y objetivo desde el inicio — esta diferencia libera a los participantes de la presión del logro y los conecta con el proceso.","origen":"fuente"},{"texto":"El silencio contemplativo inicial es sagrado — no lo interrumpas con explicaciones. Cuanto menos hables tú en los primeros 15 minutos, más profunda será la intención que emerge.","origen":"fuente"},{"texto":"Esta dinámica funciona tanto al inicio como al final del retiro — al inicio, la intención orienta el proceso; al final, la consolida y la lleva de regreso a la vida cotidiana.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[123,124],"rol":"principal"},{"archivo":"edicion2","paginas":[128,129],"rol":"contraste"}],"correcciones":[],"incidencias":[],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: Clara · Intencional."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":38,"max":50},"orden":58},{"id":"meditacion-de-reconexion-interior","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Meditación de Reconexión Interior","subtitulo":"Una experiencia para volver al centro y escuchar lo que hoy necesita tu mundo interno","resumen":"Una experiencia para volver al centro y escuchar lo que hoy necesita tu mundo interno","contexto":"En medio del ruido, las responsabilidades y las emociones acumuladas, muchas personas terminan desconectándose de sí mismas sin darse cuenta. Esta meditación invita a hacer una pausa consciente para reconectar con la respiración, las emociones y aquello que realmente necesitan en este momento de sus vidas.","objetivo":"Crear un espacio de escucha interior profunda donde los participantes puedan reconectar con sus emociones, pensamientos y necesidades reales — sin intentar cambiar nada, solo observar con presencia y compasión.","momentos":["integracion"],"temas":["escucha interior","meditación","calma"],"formato":["individual","grupo"],"tipoFuente":"Individual · Meditación","duracion":{"min":30,"max":45,"texto":"30 – 45 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Quieta · Receptiva","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Cojines o esterillas para sentarse","ids":["cojines-esterillas"],"opcional":false},{"texto":"Música suave, sonidos naturales o silencio","ids":["musica"],"opcional":false},{"texto":"Iluminación tenue y cálida","ids":[],"opcional":false},{"texto":"Papel para escribir al finalizar (opcional)","ids":["papel"],"opcional":true}],"ambiente":["Iluminación tenue y cálida"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[{"texto":"En momentos de alta carga emocional del retiro, cuando el grupo necesita desacelerar y volver a sí mismo antes de continuar.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["circulo-de-presencia","meditacion-templo-interior"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Las 4 capas de observación interior","tipo":"lista","items":["Las emociones · El clima interior — ¿Qué emociones están presentes ahora mismo? Sin nombrarlas ni analizarlas — solo sentirlas.","Los pensamientos · El ruido de fondo — Observar qué está ocupando la mente — sin juzgarlo como bueno o malo, solo como información.","Las sensaciones · El cuerpo que habla — Tensión, ligereza, calor, peso — el cuerpo siempre está comunicando algo sobre el estado interior.","Las necesidades · Lo que pide ser atendido — ¿Qué necesita realmente tu mundo interno en este momento? Descanso, claridad, conexión, tiempo..."],"nota":"La intención no es alcanzar un estado perfecto de calma — sino crear un espacio de escucha más consciente. Lo que se observa sin juzgar, por sí solo, comienza a transformarse."},{"titulo":"Frases para guiar la meditación","tipo":"frases","items":["Permite que este momento sea un espacio para volver a ti.","No necesitas resolverlo todo ahora — solo observarlo.","Escucha aquello que tu interior lleva tiempo intentando decirte."]}],"fases":[{"id":"preparacion","nombre":"Preparación","tipo":"apertura","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita al grupo a sentarse o recostarse. Guía unas respiraciones lentas y profundas para liberar tensión y entrar en el momento presente antes de dirigir la atención hacia el interior."],"citas":[],"preguntas":[],"nota":null},{"id":"meditacion-de-escucha","nombre":"Meditación de escucha","tipo":"desarrollo","tiempo":{"min":20,"max":28,"texto":"20 – 28 minutos"},"pasos":["Guía al grupo a través de las cuatro capas de observación interior. Dedica 4 a 5 minutos a cada capa con pausas largas. No hay análisis — solo observación suave y receptiva."],"citas":["Volver a uno mismo no requiere llegar a ningún lugar — solo dejar de huir del lugar donde ya estás."],"preguntas":[],"nota":null},{"id":"transicion-lenta","nombre":"Transición lenta","tipo":"integracion","tiempo":{"min":5,"max":5,"texto":"5 minutos"},"pasos":["Invita a regresar muy despacio — sin prisa, sin abrir los ojos de golpe. Unos momentos de quietud antes de volver al espacio compartido."],"citas":[],"preguntas":[],"nota":null},{"id":"integracion","nombre":"Integración","tipo":"integracion","tiempo":{"min":5,"max":8,"texto":"5 – 8 minutos"},"pasos":["Quienes lo deseen escriben o comparten algo que emergió de la escucha interior. Cierra con una respiración colectiva de gratitud hacia el propio mundo interno."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Esta meditación funciona especialmente bien en momentos de alta carga emocional del retiro — cuando el grupo necesita desacelerar y volver a sí mismo antes de continuar.","origen":"fuente"},{"texto":"No dirijas hacia lo que crees que el grupo necesita sentir — confía en el proceso de cada persona. Tu rol es crear el espacio, no llenar el interior de nadie.","origen":"fuente"},{"texto":"La transición lenta al finalizar es esencial — no cierres la meditación con música fuerte ni con palabras apresuradas. El interior necesita tiempo para volver al exterior.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[125,126],"rol":"principal"},{"archivo":"edicion2","paginas":[130,131],"rol":"contraste"}],"correcciones":[],"incidencias":[{"tipo":"separador","severidad":"media","detalle":"El separador de la página 125 dice «61 Y 62», pero solo existe una dinámica (61). No hay dinámica 62 en el PDF principal."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Quieta · Receptiva."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":35,"max":46},"orden":59},{"id":"dinamica-de-conexion-humana","version":1,"estado":"publicado","motivoEstado":null,"titulo":"Dinámica de Conexión Humana","subtitulo":"Una experiencia para fortalecer la empatía, la cercanía y la autenticidad dentro del grupo","resumen":"Una experiencia para fortalecer la empatía, la cercanía y la autenticidad dentro del grupo","contexto":"Muchas veces, las conexiones más profundas nacen de momentos simples donde las personas se sienten verdaderamente vistas y escuchadas. Esta dinámica invita a crear un espacio de encuentro más humano y consciente, favoreciendo conversaciones auténticas y presencia emocional real.","objetivo":"Profundizar la conexión humana dentro del grupo a través de conversaciones auténticas que van más allá de la superficie — creando encuentros donde cada persona se siente genuinamente vista, escuchada y acompañada.","momentos":["conexion","cierre"],"temas":["conexión","conversación","parejas"],"formato":["parejas","grupo"],"tipoFuente":"Parejas · Grupos","duracion":{"min":45,"max":60,"texto":"45 – 60 minutos"},"notaDuracion":null,"nivelFuente":"Todos los niveles","energiaFuente":"Humana · Vincular","momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[{"texto":"Espacio cálido con iluminación íntima","ids":[],"opcional":false},{"texto":"Música suave o silencio de fondo","ids":["musica"],"opcional":false},{"texto":"Disposición en parejas o grupos pequeños","ids":[],"opcional":false},{"texto":"Pañuelos disponibles","ids":["panuelos"],"opcional":false}],"ambiente":["Espacio cálido con iluminación íntima","Disposición en parejas o grupos pequeños"],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Quien no quiera trabajar en pareja puede hacer la práctica de forma individual o acompañar como observador.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[{"texto":"También puede cerrar cualquier retiro.","origen":"fuente"}],"cuandoEvitar":[],"relacionadas":["circulo-de-espejos","circulo-de-historias-de-vida"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Preguntas de conexión profunda","tipo":"preguntas","items":["¿Qué momento de tu vida te transformó más profundamente?","¿Qué valoras realmente en una conexión humana auténtica?","¿Qué necesitas más en esta etapa de tu vida?","¿Qué parte de ti deseas mostrar con más autenticidad?"],"nota":"No es necesario responder todas las preguntas — una sola pregunta explorada con honestidad y tiempo puede crear una conexión más profunda que cuatro respondidas superficialmente."},{"titulo":"Formatos posibles para la dinámica","tipo":"lista","items":["Parejas rotativas — cada persona conversa con diferentes integrantes del grupo durante turnos de 8 a 10 minutos","Grupos de tres — una persona habla, otra escucha y la tercera observa en silencio. Luego rotan los roles","Parejas fijas — una sola pareja durante toda la sesión para mayor profundidad e intimidad en la conexión"]}],"fases":[{"id":"apertura-y-formato","nombre":"Apertura y formato","tipo":"apertura","tiempo":{"min":8,"max":8,"texto":"8 minutos"},"pasos":["Presenta la intención y el formato elegido. Recuerda el acuerdo de escuchar sin interrumpir, sin aconsejar y sin intentar solucionar. Forma las parejas o grupos con intención."],"citas":[],"preguntas":[],"nota":null},{"id":"conversaciones","nombre":"Conversaciones","tipo":"desarrollo","tiempo":{"min":30,"max":40,"texto":"30 – 40 minutos"},"pasos":["Las parejas o grupos exploran las preguntas desde la autenticidad y la escucha presente. Tu rol es sostener el espacio, no dirigir las conversaciones."],"citas":["Sentirse acompañado desde la autenticidad ya transforma la manera en que vivimos una experiencia grupal."],"preguntas":[],"nota":null},{"id":"cierre-grupal","nombre":"Cierre grupal","tipo":"cierre","tiempo":{"min":8,"max":10,"texto":"8 – 10 minutos"},"pasos":["Reúne al grupo y abre un pequeño espacio para compartir sensaciones o aprendizajes surgidos durante la dinámica. Cierra con una respiración colectiva de reconocimiento por el encuentro vivido."],"citas":[],"preguntas":[],"nota":null}],"queObservar":[],"recomendaciones":[{"texto":"Forma las parejas con intención — a veces la conexión más significativa surge entre personas que menos se han hablado durante el retiro.","origen":"fuente"},{"texto":"Recuerda el acuerdo de escucha antes de comenzar — no interrumpir ni solucionar es la habilidad más difícil y más transformadora de esta dinámica.","origen":"fuente"},{"texto":"Esta dinámica cierra la guía completa — y puede cerrar también cualquier retiro con la misma fuerza con la que lo abrió. La conexión humana auténtica es el principio y el fin de todo.","origen":"fuente"}],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[127,128],"rol":"principal"},{"archivo":"edicion2","paginas":[132,133],"rol":"contraste"}],"correcciones":[],"incidencias":[{"tipo":"numeracion","severidad":"baja","detalle":"Se presenta como «Dinámica final · 63 de 63», aunque el PDF contiene 60 desarrollos distintos."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: Todos los niveles; energía: Humana · Vincular."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente","subtitulo":"fuente","contexto":"fuente","objetivo":"fuente","fases":"fuente","secciones":"fuente","materiales":"fuente","recomendaciones":"fuente","duracion":"fuente","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":{"min":46,"max":58},"orden":60},{"id":"viaje-a-traves-de-los-chakras","version":1,"estado":"revision","motivoEstado":"El separador existe en el PDF principal (p. 45) pero su página repite «Visualización del Futuro». El desarrollo se recuperó de la Edición 2 (pp. 48–49); faltan duración, tiempos por fase y el detalle de cada centro energético.","titulo":"Viaje a través de los Chakras","subtitulo":"Una experiencia para reconectar con el cuerpo, la energía y el equilibrio interior","resumen":"Una experiencia para reconectar con el cuerpo, la energía y el equilibrio interior","contexto":"Nuestro cuerpo guarda emociones, tensiones y experiencias que muchas veces pasan desapercibidas en la rutina diaria. Esta dinámica invita a los participantes a recorrer de manera consciente los distintos centros energéticos del cuerpo, favoreciendo un estado de mayor presencia, equilibrio y conexión interior.","objetivo":null,"momentos":["exploracion"],"temas":["cuerpo","energía","meditación"],"formato":["grupo"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["escaneo-corporal","meditacion-del-arbol"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Frases para acompañar","tipo":"frases","items":["Respira y permite que la energía fluya con naturalidad.","Observa sin necesidad de controlar la experiencia.","Escucha lo que tu cuerpo necesita expresar."]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y relajado donde el grupo pueda sentarse o recostarse cómodamente. Puedes acompañar la experiencia con música suave, sonidos ambientales, velas o iluminación tenue para crear una atmósfera de calma y concentración.","Comienza guiando unas respiraciones lentas para ayudar al grupo a relajarse y conectar con el momento presente.","A medida que la práctica avanza, invita a los participantes a llevar la atención hacia distintas zonas del cuerpo, observando sensaciones, emociones o pensamientos que puedan surgir. Puedes recorrer los chakras desde la base hasta la coronilla, acompañando cada etapa con colores, emociones o palabras asociadas a cada centro energético.","Al finalizar, deja unos minutos de silencio para integrar lo vivido antes de invitar al grupo a regresar lentamente al espacio.","Quienes lo deseen pueden escribir o compartir brevemente cómo se sintieron durante la práctica."],"citas":["Respira y permite que la energía fluya con naturalidad.","Observa sin necesidad de controlar la experiencia.","Escucha lo que tu cuerpo necesita expresar."],"preguntas":[],"nota":"La intención no es “hacerlo perfecto”, sino permitir que cada persona observe cómo se siente física y emocionalmente durante la experiencia.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[45],"rol":"separador"},{"archivo":"edicion2","paginas":[48,49],"rol":"recuperacion"}],"correcciones":[],"incidencias":[{"tipo":"duplicado","severidad":"alta","detalle":"En el PDF principal, la página siguiente al separador 45 repite otra ficha (duplicado exacto)."},{"tipo":"faltantes","severidad":"media","detalle":"Faltan: duración, tiempos por fase, materiales como lista, descripción de cada chakra (la fuente solo indica 'colores, emociones o palabras asociadas' sin detallarlos)."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":61},{"id":"circulo-de-transformacion-alquimica","version":1,"estado":"borrador","motivoEstado":"El separador existe en el PDF principal (p. 55) pero su página repite «Viaje Chamánico Guiado». El texto de la Edición 2 (p. 59) termina en el acto simbólico: faltan integración, cierre, duración y tiempos.","titulo":"Círculo de Transformación Alquímica","subtitulo":"Una experiencia para reconocer aquello que está listo para transformarse","resumen":"Una experiencia para reconocer aquello que está listo para transformarse","contexto":"Toda transformación profunda comienza cuando dejamos de resistir aquello que necesitamos mirar. Esta dinámica invita a los participantes a observar patrones, emociones o etapas de vida que hoy sienten listas para evolucionar, creando un espacio simbólico de cambio y renovación interior.","objetivo":null,"momentos":["exploracion"],"temas":["transformación","ritual","escritura","fuego"],"formato":["grupo"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Ofrece siempre una alternativa sin fuego (romper, enterrar o guardar el papel) para quien prefiera no usarlo.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ritual-de-liberacion","ritual-de-renacimiento"],"notasAdmin":[],"propuestas":[],"preparacion":[{"texto":"Si usas fuego: recipiente resistente al calor, agua o arena a mano, lejos de telas y papeles, y siempre bajo supervisión. Respeta las normas del lugar.","origen":"adaptacion"}],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Qué parte de tu vida necesita un cambio más consciente?","¿Qué estás listo para dejar atrás?","¿Qué nueva energía deseas comenzar a cultivar?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente íntimo y cálido, acompañado de velas, música suave o iluminación tenue que favorezca la introspección y la conexión emocional.","Invita al grupo a sentarse en círculo y comenzar con unos minutos de respiración consciente para entrar en un estado de mayor presencia.","Después, guía una breve reflexión sobre cómo muchas veces los procesos más difíciles también contienen oportunidades de crecimiento, claridad y transformación.","Entrega papel y bolígrafos e invita a cada participante a escribir: aquello que desean transformar, una emoción que ya no quieren seguir sosteniendo, o una versión de sí mismos que sienten lista para evolucionar.","Una vez finalizada la reflexión, invita al grupo a realizar un pequeño acto simbólico de transformación: doblar el papel, guardarlo en un recipiente, quemarlo de forma segura o simplemente sostenerlo mientras realizan una respiración profunda."],"citas":[],"preguntas":["¿Qué parte de tu vida necesita un cambio más consciente?","¿Qué estás listo para dejar atrás?","¿Qué nueva energía deseas comenzar a cultivar?"],"nota":null,"origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"principal","paginas":[55],"rol":"separador"},{"archivo":"edicion2","paginas":[58,59],"rol":"recuperacion"}],"correcciones":[],"incidencias":[{"tipo":"duplicado","severidad":"alta","detalle":"En el PDF principal, la página siguiente al separador 55 repite otra ficha (duplicado exacto)."},{"tipo":"faltantes","severidad":"media","detalle":"Faltan: duración, tiempos por fase, integración y cierre (el texto termina con el acto simbólico)."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":62},{"id":"carta-al-futuro","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación del propietario. Sin duración ni tiempos por fase.","titulo":"Carta al Futuro","subtitulo":"Una experiencia para conectar con la visión personal y los cambios que deseas construir","resumen":"Una experiencia para conectar con la visión personal y los cambios que deseas construir","contexto":"A veces, escribirle a nuestra versión futura nos ayuda a reconocer con más claridad quiénes somos hoy y hacia dónde queremos avanzar. Esta dinámica invita a los participantes a reflexionar sobre su presente, sus aprendizajes y las intenciones que desean sostener después del retiro.","objetivo":null,"momentos":["integracion","cierre"],"temas":["escritura","visión","intención"],"formato":["individual"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["visualizacion-del-futuro","mapa-de-suenos-e-intenciones"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Qué quiero recordar de esta etapa de mi vida?","¿Qué parte de mí deseo fortalecer?","¿Qué decisiones quiero sostener a partir de ahora?","¿Cómo quiero sentirme en el futuro?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y reflexivo donde el grupo pueda escribir sin interrupciones. Puedes acompañar el espacio con música suave, luz cálida o unos minutos previos de respiración consciente para favorecer la introspección.","Invita a cada participante a escribir una carta dirigida a sí mismo en el futuro. La carta puede incluir: emociones, aprendizajes, intenciones, recordatorios, decisiones o aquello que no desean olvidar después de esta experiencia.","Al finalizar, cada participante podrá guardar la carta para abrirla meses después o conservarla como un recordatorio simbólico de su proceso personal."],"citas":[],"preguntas":["¿Qué quiero recordar de esta etapa de mi vida?","¿Qué parte de mí deseo fortalecer?","¿Qué decisiones quiero sostener a partir de ahora?","¿Cómo quiero sentirme en el futuro?"],"nota":"Anima al grupo a escribir desde la honestidad y sin preocuparse por hacerlo “perfecto”. La intención es crear un momento auténtico de conexión con ellos mismos.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[76,77],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":63},{"id":"circulo-de-celebracion","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. Su estructura de compartir es parecida a los cierres; confirmar si se mantiene como actividad propia.","titulo":"Círculo de Celebración","subtitulo":"Un espacio para reconocer el camino recorrido y compartir la energía del grupo","resumen":"Un espacio para reconocer el camino recorrido y compartir la energía del grupo","contexto":"Después de los momentos de introspección y transformación, también es importante abrir espacio para la alegría, la gratitud y la celebración compartida. Esta dinámica invita al grupo a reconocer todo lo vivido durante el retiro desde una energía más ligera, presente y expansiva.","objetivo":null,"momentos":["cierre"],"temas":["celebración","gratitud","círculo"],"formato":["grupo"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"ambos"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Cada persona elige su ritmo: moverse suavemente, quedarse sentada o acompañar desde la quietud también es participar.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["circulo-de-cierre-del-retiro","ritual-de-gratitud-colectiva"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Frases para acompañar","tipo":"frases","items":["Celebrar también es parte del proceso de transformación.","Honrar lo vivido nos ayuda a integrarlo.","Cada experiencia compartida deja algo en los demás."]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente cálido y relajado, acompañado de música, velas, naturaleza o cualquier elemento que ayude a crear una atmósfera de conexión y bienestar.","Invita a los participantes a reunirse en círculo y comenzar con unas respiraciones suaves para conectar con el momento presente.","Después, abre un espacio donde cada persona pueda compartir: un aprendizaje importante, un momento significativo del retiro, algo que agradece, o aquello que desea llevar consigo después de la experiencia.","Si lo deseas, puedes complementar el cierre con música suave, movimiento libre, un brindis simbólico o un pequeño ritual grupal que represente unión y gratitud. Lo importante es crear un momento humano, auténtico y lleno de presencia."],"citas":["Celebrar también es parte del proceso de transformación.","Honrar lo vivido nos ayuda a integrarlo.","Cada experiencia compartida deja algo en los demás."],"preguntas":[],"nota":"La intención no es hacer grandes discursos, sino permitir que cada participante reconozca y celebre su propio proceso y el del grupo.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[78,79],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."},{"tipo":"similitud","severidad":"baja","detalle":"Estructura de compartir parecida a los cierres (aprendizaje, momento, gratitud, lo que se lleva), con énfasis en la celebración y movimiento libre opcional. Registrada como actividad propia; marcar como posible variante para revisión."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":64},{"id":"ejercicio-de-autoaceptacion","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. Sin duración ni tiempos por fase.","titulo":"Ejercicio de Autoaceptación","subtitulo":"Una experiencia para abrazar quién eres con más honestidad y compasión","resumen":"Una experiencia para abrazar quién eres con más honestidad y compasión","contexto":"Muchas veces somos capaces de comprender y cuidar a los demás, pero nos cuesta ofrecer esa misma comprensión hacia nosotros mismos. Esta dinámica invita a los participantes a observarse con más amabilidad, reconociendo tanto sus fortalezas como aquellas partes que normalmente juzgan o rechazan.","objetivo":null,"momentos":["exploracion"],"temas":["autoaceptación","compasión","escritura"],"formato":["individual"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["ritual-de-autoperdon","espejo-de-las-sombras"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Qué parte de mí necesita hoy más comprensión?","¿Qué aspecto de mi historia sigo juzgando demasiado?","¿Cómo cambiaría mi vida si aprendiera a tratarme con más compasión?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y seguro, acompañado de música suave, iluminación cálida o un espacio que favorezca la introspección y la calma emocional.","Comienza guiando unas respiraciones conscientes para ayudar al grupo a relajarse y conectar con el momento presente.","Después, invita a cada participante a reflexionar sobre aquellas partes de sí mismos que más les cuesta aceptar: emociones, errores, inseguridades, cicatrices emocionales o aspectos personales que normalmente intentan ocultar.","Invita al grupo a escribir unas palabras dirigidas hacia sí mismos desde la empatía y el cuidado, como si hablaran con alguien a quien aman profundamente.","Al finalizar, permite unos minutos de silencio para integrar la experiencia antes de abrir un pequeño espacio de reflexión voluntaria."],"citas":[],"preguntas":["¿Qué parte de mí necesita hoy más comprensión?","¿Qué aspecto de mi historia sigo juzgando demasiado?","¿Cómo cambiaría mi vida si aprendiera a tratarme con más compasión?"],"nota":"La intención no es “convertirse en alguien perfecto”, sino comenzar a relacionarse consigo mismos desde un lugar más humano y consciente.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[80,81],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":65},{"id":"taller-de-expresion-emocional","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. El término «terapéutico» del título puede sugerir un servicio clínico.","titulo":"Taller Terapéutico de Expresión Emocional","subtitulo":"Un espacio para reconocer, expresar y comprender lo que sentimos","resumen":"Un espacio para reconocer, expresar y comprender lo que sentimos","contexto":"Las emociones que se expresan de forma consciente pueden convertirse en una fuente de comprensión, alivio y transformación personal. Esta dinámica invita a los participantes a conectar con sus emociones desde la observación, la expresión y la escucha interna, creando un espacio seguro donde puedan sentirse vistos y contenidos.","objetivo":null,"momentos":["exploracion"],"temas":["emociones","expresión","arte"],"formato":["grupo","individual"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"},{"texto":"Cada persona elige su ritmo: moverse suavemente, quedarse sentada o acompañar desde la quietud también es participar.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["jardin-de-las-emociones","el-poder-de-las-emociones"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Qué emoción necesita hoy más espacio dentro de mí?","¿Qué intento evitar sentir?","¿Qué me está mostrando esta emoción sobre mi vida actual?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y acogedor, acompañado de música suave, iluminación cálida o materiales creativos que ayuden a favorecer la expresión emocional.","Comienza guiando unas respiraciones conscientes para ayudar al grupo a relajarse y conectar con el momento presente.","Después, invita a los participantes a identificar una emoción que haya estado presente en sus vidas recientemente: miedo, tristeza, alegría, enojo, confusión o cualquier emoción que necesite más atención y escucha.","La experiencia puede desarrollarse a través de escritura, dibujo, movimiento corporal o reflexión grupal, dependiendo de la energía y necesidades del grupo.","Al finalizar, invita al grupo a respirar profundamente y reconocer que todas las emociones cumplen una función dentro de la experiencia humana."],"citas":[],"preguntas":["¿Qué emoción necesita hoy más espacio dentro de mí?","¿Qué intento evitar sentir?","¿Qué me está mostrando esta emoción sobre mi vida actual?"],"nota":"Recuerda que la intención no es “arreglar” las emociones, sino permitir que puedan ser observadas y expresadas con mayor conciencia y compasión.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[82,83],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."},{"tipo":"revision","severidad":"media","detalle":"El término 'terapéutico' en el título puede sugerir un servicio clínico; requiere decisión del propietario antes de publicar."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":66},{"id":"meditacion-de-integracion","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. Sin duración ni tiempos por fase.","titulo":"Meditación de Integración","subtitulo":"Una experiencia para asimilar lo vivido y conectar con una sensación de equilibrio interior","resumen":"Una experiencia para asimilar lo vivido y conectar con una sensación de equilibrio interior","contexto":"Después de atravesar experiencias profundas, el cuerpo y la mente también necesitan espacios de calma para integrar lo aprendido. Esta dinámica invita a los participantes a desacelerar y permitir que las emociones, reflexiones y descubrimientos del retiro encuentren un espacio de mayor claridad y presencia.","objetivo":null,"momentos":["integracion","cierre"],"temas":["integración","meditación","calma"],"formato":["grupo"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["meditacion-de-reconexion-interior","circulo-de-reflexion-nocturna"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Frases para acompañar","tipo":"frases","items":["Permite que lo vivido encuentre su propio lugar dentro de ti.","No necesitas comprenderlo todo en este momento.","La integración también ocurre en silencio."]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y cómodo donde el grupo pueda sentarse o recostarse sin interrupciones. Puedes acompañar la experiencia con música suave, sonidos naturales o iluminación tenue que favorezca la relajación y el descanso emocional.","Comienza guiando unas respiraciones lentas para ayudar a liberar tensión y conectar con el momento presente.","Después, invita al grupo a recorrer internamente todo lo vivido durante el retiro: los aprendizajes, las emociones, las conversaciones, los silencios y las experiencias que dejaron huella en cada persona.","Después de algunos minutos de meditación y calma, invita al grupo a regresar lentamente al espacio y conectar nuevamente con el cuerpo y la respiración.","Quienes lo deseen pueden escribir una breve reflexión o compartir alguna sensación surgida durante la práctica."],"citas":["Permite que lo vivido encuentre su propio lugar dentro de ti.","No necesitas comprenderlo todo en este momento.","La integración también ocurre en silencio."],"preguntas":[],"nota":"La intención no es analizar todo lo ocurrido, sino permitir que cada participante observe cómo se siente ahora después del proceso vivido.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[106,107],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":67},{"id":"ritual-de-conexion-ancestral","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. Sin duración ni tiempos por fase.","titulo":"Ritual de Conexión Ancestral","subtitulo":"Una experiencia para honrar las raíces, la historia y la sabiduría que nos acompaña","resumen":"Una experiencia para honrar las raíces, la historia y la sabiduría que nos acompaña","contexto":"Cada persona forma parte de una historia más grande: familia, memorias, aprendizajes y experiencias que, de alguna manera, también dejaron huella en su camino. Esta dinámica invita a los participantes a conectar simbólicamente con sus raíces y reconocer aquello que desean honrar, agradecer o transformar dentro de su historia personal.","objetivo":null,"momentos":["exploracion"],"temas":["raíces","familia","ritual"],"formato":["individual","grupo"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[{"texto":"Si alguien muestra angustia intensa (llanto que no cede, respiración agitada o desconexión), pausa la consigna general con calma, ofrece agua y un lugar aparte, y acompaña o pide a otra persona del equipo que acompañe.","origen":"adaptacion"}],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["circulo-de-historias-de-vida"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"media","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Qué aprendizajes importantes recibí de quienes estuvieron antes que yo?","¿Qué aspectos de mi historia deseo agradecer?","¿Qué patrones o cargas siento listos para transformar?","¿Qué legado quiero continuar construyendo de manera más consciente?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente íntimo y significativo, acompañado de velas, elementos naturales, fotografías simbólicas o música suave que ayude a crear una atmósfera de calma y reflexión.","Comienza guiando unas respiraciones conscientes para ayudar al grupo a entrar en un estado de mayor presencia y conexión interior.","Después, invita a los participantes a reflexionar sobre las personas, enseñanzas o experiencias que marcaron su vida y que hoy siguen acompañando su camino de alguna forma.","La experiencia puede desarrollarse a través de escritura, reflexión silenciosa, compartir grupal o pequeños rituales simbólicos según la energía del grupo.","Al finalizar, invita al grupo a cerrar con una respiración colectiva, una palabra compartida o unos minutos de silencio consciente para integrar la experiencia."],"citas":[],"preguntas":["¿Qué aprendizajes importantes recibí de quienes estuvieron antes que yo?","¿Qué aspectos de mi historia deseo agradecer?","¿Qué patrones o cargas siento listos para transformar?","¿Qué legado quiero continuar construyendo de manera más consciente?"],"nota":"La intención no es idealizar el pasado, sino reconocer cómo nuestras raíces también forman parte de quienes somos hoy.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[108,109],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":68},{"id":"dinamica-de-coherencia-interior","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. Tema cercano a «Mesa Redonda sobre Valores» en formato individual.","titulo":"Dinámica de Coherencia Interior","subtitulo":"Una experiencia para alinear pensamientos, emociones y acciones con mayor autenticidad","resumen":"Una experiencia para alinear pensamientos, emociones y acciones con mayor autenticidad","contexto":"Muchas veces sabemos lo que sentimos o lo que deseamos, pero nuestras decisiones y hábitos terminan alejándose de aquello que realmente valoramos. Esta dinámica invita a los participantes a reflexionar sobre la coherencia entre su mundo interior y la manera en que viven su día a día.","objetivo":null,"momentos":["exploracion","integracion"],"temas":["valores","coherencia","escritura"],"formato":["individual"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["mesa-redonda-sobre-valores"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Estoy viviendo de acuerdo con aquello que realmente valoro?","¿Qué decisiones no se sienten coherentes conmigo hoy?","¿Qué parte de mi vida necesita más honestidad y alineación?","¿Qué pequeños cambios podrían acercarme más a quien quiero ser?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente tranquilo y reflexivo donde el grupo pueda sentirse cómodo para escribir, pensar y compartir desde la honestidad.","Puedes comenzar con unas respiraciones conscientes o una breve meditación para ayudar a desacelerar y conectar con el momento presente.","Después, invita a cada participante a observar distintas áreas de su vida: relaciones, trabajo, bienestar, emociones, hábitos o decisiones recientes. La intención es reconocer qué aspectos se sienten alineados con sus valores y cuáles necesitan más autenticidad, equilibrio o presencia.","Invita al grupo a escribir algunas reflexiones o acciones concretas que deseen comenzar a integrar después del retiro.","Al finalizar, puedes abrir un pequeño espacio para compartir descubrimientos o cerrar con unos minutos de silencio e integración."],"citas":[],"preguntas":["¿Estoy viviendo de acuerdo con aquello que realmente valoro?","¿Qué decisiones no se sienten coherentes conmigo hoy?","¿Qué parte de mi vida necesita más honestidad y alineación?","¿Qué pequeños cambios podrían acercarme más a quien quiero ser?"],"nota":"La intención no es generar culpa ni exigencia, sino crear un espacio de claridad y conciencia personal.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[110,111],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."},{"tipo":"similitud","severidad":"baja","detalle":"Tema cercano a 'Mesa Redonda sobre Valores' (valores y alineación), pero en formato de reflexión individual por áreas de vida. Registrada como actividad propia; marcar similitud para revisión."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":69},{"id":"visualizacion-del-lugar-seguro","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. El último párrafo está cortado en la fuente.","titulo":"Visualización del Lugar Seguro","subtitulo":"Una experiencia para conectar con la calma, la seguridad y el refugio interior","resumen":"Una experiencia para conectar con la calma, la seguridad y el refugio interior","contexto":"En momentos de estrés, incertidumbre o agotamiento emocional, muchas personas necesitan volver a un espacio interno donde puedan sentirse tranquilas, sostenidas y en paz. Esta dinámica invita a los participantes a crear y explorar un “lugar seguro” a través de una visualización guiada enfocada en la calma y la contención emocional.","objetivo":null,"momentos":["apertura","integracion"],"temas":["calma","visualización","seguridad"],"formato":["grupo"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Quien lo prefiera puede mantener los ojos abiertos, con la mirada suave hacia el suelo.","origen":"adaptacion"},{"texto":"Si una imagen resulta incómoda, se puede abrir los ojos, volver a la respiración o dejar la visualización y descansar.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["meditacion-templo-interior","meditacion-de-reconexion-interior"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"intermedia","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Frases para acompañar","tipo":"frases","items":["Permite que este espacio te sostenga.","No necesitas hacer nada más que estar aquí.","Recuerda que siempre puedes volver a este lugar dentro de ti."]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente cómodo y silencioso donde el grupo pueda sentarse o recostarse sin interrupciones. Puedes acompañar la experiencia con música suave, sonidos naturales o iluminación tenue para favorecer la relajación y la introspección.","Comienza guiando unas respiraciones lentas para ayudar al grupo a liberar tensión y conectar con el momento presente.","Después, invita a los participantes a imaginar un lugar donde se sientan completamente seguros y en calma. Puede ser un espacio real o imaginario: una playa, un bosque, una montaña, una habitación acogedora o cualquier entorno que despierte sensación de tranquilidad y protección.","Guía la experiencia invitando a observar: los colores, los sonidos, la temperatura, las texturas y las emociones que aparecen dentro de ese lugar.","Después de unos minutos de visualización y silencio, invita al grupo a regresar lentamente al espacio y observar cómo se siente el cuerpo después de la experiencia.","Quienes lo deseen pueden escribir o compartir alguna sensación surgida durante la práctica."],"citas":["Permite que este espacio te sostenga.","No necesitas hacer nada más que estar aquí.","Recuerda que siempre puedes volver a este lugar dentro de ti."],"preguntas":[],"nota":null,"origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[122,123],"rol":"principal"}],"correcciones":[{"campo":"pasos.ultimo","original":"Quienes lo deseen pueden escribir o compartir alguna sensación surgida durante la [texto cortado en la fuente]","corregido":"Quienes lo deseen pueden escribir o compartir alguna sensación surgida durante la práctica.","motivo":"Frase cortada en la fuente; se completa con la palabra evidente por el contexto (propuesta)."}],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."},{"tipo":"revision","severidad":"media","detalle":"El último párrafo queda cortado en la fuente ('…alguna sensación surgida durante la')."}],"clasificacion":{"momentos":{"origen":"editorial","motivo":"Clasificación editorial a partir del tipo, el momento y las recomendaciones de la ficha."},"intensidad":{"origen":"editorial","motivo":"Clasificación editorial. Nivel indicado en la fuente: no especificado; energía: no especificada."},"experiencia":{"origen":"editorial","motivo":"Clasificación editorial según la complejidad de conducción y contención."},"temas":{"origen":"editorial","motivo":"Etiquetas editoriales para la búsqueda."},"espacio":{"origen":"editorial","motivo":"Según el espacio indicado o deducido de la ficha."}},"sistemaProfesional":null,"imagen":null,"actualizado":"2026-10-23","procedencia":{"titulo":"fuente-ed2","subtitulo":"fuente-ed2","contexto":"fuente-ed2","fases":"fuente-ed2","secciones":"fuente-ed2","consentimiento":"adaptacion","criteriosPausa":"adaptacion","momentos":"editorial","temas":"editorial","intensidad":"editorial","experiencia":"editorial"},"sumaFases":null,"orden":70},{"id":"ceremonia-de-reconocimiento-personal","version":1,"estado":"revision","motivoEstado":"Solo aparece en la Edición 2: pendiente de aprobación. Sin duración ni tiempos por fase.","titulo":"Ceremonia de Reconocimiento Personal","subtitulo":"Un espacio para honrar el camino recorrido y reconocer el propio crecimiento","resumen":"Un espacio para honrar el camino recorrido y reconocer el propio crecimiento","contexto":"Muchas veces avanzamos tanto mirando lo que falta que olvidamos reconocer todo lo que ya hemos atravesado, aprendido y transformado. Esta dinámica invita a los participantes a detenerse y observar con más conciencia su propio recorrido, reconociendo fortalezas, aprendizajes y procesos personales que merecen ser valorados.","objetivo":null,"momentos":["cierre","integracion"],"temas":["reconocimiento","autovaloración","escritura"],"formato":["grupo","individual"],"tipoFuente":null,"duracion":null,"notaDuracion":null,"nivelFuente":null,"energiaFuente":null,"momentoFuente":null,"enfoqueFuente":null,"espacio":{"tipo":"interior"},"participantes":null,"materiales":[],"ambiente":[],"consentimiento":[{"texto":"Participar es voluntario: cualquier persona puede pasar, observar o detenerse en cualquier momento, sin dar explicaciones.","origen":"adaptacion"},{"texto":"Nadie necesita leer ni mostrar lo que escribe; puede guardarlo, romperlo o conservarlo en privado.","origen":"adaptacion"},{"texto":"Compartir siempre es opcional y vale decir «paso». Acuerden al inicio que lo compartido queda en el grupo.","origen":"adaptacion"}],"criteriosPausa":[],"cuandoUtilizar":[],"cuandoEvitar":[],"relacionadas":["circulo-de-reconocimiento-y-alabanza","ceremonia-de-la-luz-interior"],"notasAdmin":[],"propuestas":[],"preparacion":[],"experiencia":"inicial","intensidad":"suave","adaptaciones":[],"secciones":[{"titulo":"Preguntas para acompañar","tipo":"preguntas","items":["¿Qué parte de mi camino merece hoy ser reconocida?","¿Qué desafío me ayudó a crecer más de lo que imaginaba?","¿Qué fortaleza descubrí en mí durante este proceso?","¿Qué versión de mí estoy aprendiendo a valorar más?"]}],"fases":[{"id":"desarrollo","nombre":"Desarrollo","tipo":"desarrollo","tiempo":null,"pasos":["Prepara un ambiente íntimo y cálido, acompañado de iluminación suave, velas o música tranquila que favorezca la introspección y la conexión emocional.","Invita al grupo a sentarse en círculo y comenzar con unas respiraciones conscientes para ayudar a entrar en un estado de mayor presencia.","Después, guía una breve reflexión sobre todo aquello que cada persona ha logrado sostener, superar o transformar a lo largo de su vida.","Invita a los participantes a escribir unas palabras hacia sí mismos desde el reconocimiento y la gratitud personal.","Quienes lo deseen pueden compartir una reflexión, una palabra o un aprendizaje importante con el grupo.","Al finalizar, puedes cerrar con unos minutos de silencio consciente o una breve práctica de respiración para integrar la experiencia."],"citas":[],"preguntas":["¿Qué parte de mi camino merece hoy ser reconocida?","¿Qué desafío me ayudó a crecer más de lo que imaginaba?","¿Qué fortaleza descubrí en mí durante este proceso?","¿Qué versión de mí estoy aprendiendo a valorar más?"],"nota":"La intención no es alimentar el ego, sino aprender a observar el propio camino con más respeto, humanidad y compasión.","origen":"fuente-ed2"}],"queObservar":[],"recomendaciones":[],"variantes":[],"fuentes":[{"archivo":"edicion2","paginas":[124,125],"rol":"principal"}],"correcciones":[],"incidencias":[{"tipo":"faltantes","severidad":"media","detalle":"Redacción narrativa sin duración, materiales en lista ni tiempos por fase."}],"clasificacion":{"momentos":{"origen":"